window.KB_EXPANDED = {"version":"gold111","count":231,"source":"ai_drafted","vocab":229,"list":[{"id":"acinetobacter_infections","name":"Acinetobacter Infections","system":"Multisystem / Infectious Disease","class":"infective","find":{"icuStay":6,"mechanicalVentilation":6,"hospitalDay48":6,"centralLine":6,"mdrRisk":6,"creHistory":6,"fever":2,"worseningOxygenation":2,"increasedSputumVolume":2,"priorAntibiotics":2,"antibioticsLast90Days":2,"hospitalizationLast90Days":2,"petechialRash":2,"organDysfunction":2,"oralIntakeAdequate":-6,"clinicallyImproving":-6,"afebrile24h":-6},"tiers":{"pathognomonic":[],"discriminative":["icuStay","mechanicalVentilation","hospitalDay48","centralLine","mdrRisk","creHistory"],"supportive":["fever","worseningOxygenation","increasedSputumVolume","priorAntibiotics","antibioticsLast90Days","hospitalizationLast90Days","petechialRash","organDysfunction"],"negative":["oralIntakeAdequate","clinicallyImproving","afebrile24h"]},"rationale":"Acinetobacter infection is essentially a healthcare-associated/device-associated syndrome, so ICU stay, prolonged mechanical ventilation with late-onset pneumonia, central line presence, and MDR risk factors are the key discriminators rather than any specific bedside sign."},{"id":"actinomycosis","name":"Actinomycosis","system":"Multisystem / Infectious Disease","class":"infective","find":{"purulentDrainage":6,"boneInvolvement":6,"dysphagia":6,"facialSwelling":6,"weightLoss":6,"prolongedFever":2,"subacuteOnset":2,"prolongedCough2Weeks":2,"hemoptysis":2,"abdominalPain":2,"abdominalDistension":2,"immunocompromised":2,"lymphadenopathy":-6},"tiers":{"pathognomonic":[],"discriminative":["purulentDrainage","boneInvolvement","dysphagia","facialSwelling","weightLoss"],"supportive":["prolongedFever","subacuteOnset","prolongedCough2Weeks","hemoptysis","abdominalPain","abdominalDistension","immunocompromised"],"negative":["lymphadenopathy"]},"rationale":"Actinomycosis presents as a slowly progressive, indurated mass-like lesion crossing tissue planes with sinus tracts and purulent drainage, often at the jaw, chest, or abdomen, with relative sparing of lymphatic spread which argues against it when prominent lymphadenopathy dominates."},{"id":"acute_and_chronic_myocarditis","name":"Acute and Chronic Myocarditis","system":"Cardiovascular","class":"infective","find":{"chestPain":6,"palpitations":6,"ecgIschemia":6,"newMurmur":6,"dyspnea":6,"fever":2,"subacuteOnset":2,"myalgiaArthralgia":2,"tachycardia":2,"orthopnea":2,"raisedJVP":2,"legSwellingBilateral":2,"severeCriteria":-6,"purulentSputum":-6,"dysuria":-6,"abdominalPain":-6},"tiers":{"pathognomonic":[],"discriminative":["chestPain","palpitations","ecgIschemia","newMurmur","dyspnea"],"supportive":["fever","subacuteOnset","myalgiaArthralgia","tachycardia","orthopnea","raisedJVP","legSwellingBilateral"],"negative":["severeCriteria","purulentSputum","dysuria","abdominalPain"]},"rationale":"Myocarditis presents with chest pain, dyspnea, palpitations and ECG ischemic changes/troponin rise mimicking ACS, often after a febrile viral prodrome, but is a clinical-lab-imaging (troponin, ECG, CMR/biopsy) diagnosis without a single bedside pathognomonic finding."},{"id":"acute_appendicitis","name":"Acute Appendicitis and Peritonitis","system":"Gastroenterology / Surgical","class":"non_infective","find":{"severeAbdominalPain":6,"abdominalPain":6,"nauseaVomiting":6,"fever":2,"abdominalDistension":2,"constipationOrDiarrhea":2,"dysuria":2,"urinaryFrequency":2,"bloodyStool":-6,"jaundice":-6,"rightUpperQuadrantPain":-6,"murphySign":-6},"tiers":{"pathognomonic":[],"discriminative":["severeAbdominalPain","abdominalPain","nauseaVomiting"],"supportive":["fever","abdominalDistension","constipationOrDiarrhea","dysuria","urinaryFrequency"],"negative":["bloodyStool","jaundice","rightUpperQuadrantPain","murphySign"]},"rationale":"Acute appendicitis classically presents with migratory abdominal pain localizing to the right lower quadrant with nausea/vomiting following pain onset, but no single bedside finding is truly pathognomonic; presence of bloody stool, jaundice, or RUQ pain/Murphy sign points toward mimics rather than appendicitis."},{"id":"acute_infectious_diarrheal_diseases_and","name":"Acute Infectious Diarrheal Diseases and Bacterial Food Poisoning","system":"Gastrointestinal","class":"infective","find":{"diarrhea":6,"bloodyStool":6,"tenesmus":6,"contaminatedFoodWaterExposure":6,"dehydration":6,"nauseaVomiting":2,"abdominalPain":2,"fever":2,"abdominalDistension":2,"highFeverGI":2,"severeAbdominalPain":2,"chestPain":-6,"dysuria":-6,"neckStiffness":-6,"cough":-6},"tiers":{"pathognomonic":[],"discriminative":["diarrhea","bloodyStool","tenesmus","contaminatedFoodWaterExposure","dehydration"],"supportive":["nauseaVomiting","abdominalPain","fever","abdominalDistension","highFeverGI","severeAbdominalPain"],"negative":["chestPain","dysuria","neckStiffness","cough"]},"rationale":"Acute infectious diarrhea/food poisoning is diagnosed clinically by watery or bloody/mucoid diarrhea with tenesmus following contaminated food/water exposure, often with dehydration, vomiting, and abdominal pain; findings pointing to respiratory, urinary, or meningeal syndromes argue against it."},{"id":"acute_intestinal_obstruction","name":"Acute Intestinal Obstruction","system":"Gastrointestinal","class":"non_infective","find":{"abdominalDistension":6,"constipationOrDiarrhea":6,"nauseaVomiting":6,"severeAbdominalPain":6,"abdominalPain":6,"dehydration":2,"fever":2,"tachycardia":2,"hypotension":2,"diarrhea":-6,"oralIntakeAdequate":-6},"tiers":{"pathognomonic":[],"discriminative":["abdominalDistension","constipationOrDiarrhea","nauseaVomiting","severeAbdominalPain","abdominalPain"],"supportive":["dehydration","fever","tachycardia","hypotension"],"negative":["diarrhea","oralIntakeAdequate"]},"rationale":"The cardinal tetrad of colicky abdominal pain, distention, vomiting, and obstipation (constipation) is highly discriminative for mechanical obstruction, while none of the available bedside findings are truly pathognomonic; presence of ongoing diarrhea or normal oral intake argues against obstruction."},{"id":"acute_lymphoid_leukemia","name":"Acute Lymphoid Leukemia","system":"Hematologic/Oncologic","class":"non_infective","find":{"neutropenia":6,"thrombocytopenia":6,"hepatosplenomegaly":6,"lymphadenopathy":6,"petechialRash":6,"fever":2,"weightLoss":2,"malignancy":2,"hemoglobin":2,"platelets":2,"mucocutaneousBleeding":2,"bleedingManifestation":2},"tiers":{"pathognomonic":[],"discriminative":["neutropenia","thrombocytopenia","hepatosplenomegaly","lymphadenopathy","petechialRash"],"supportive":["fever","weightLoss","malignancy","hemoglobin","platelets","mucocutaneousBleeding","bleedingManifestation"],"negative":[]},"rationale":"ALL presents with marrow-failure features (cytopenias, bleeding, infection) plus tumor-bulk signs like lymphadenopathy and hepatosplenomegaly; definitive diagnosis requires marrow biopsy/immunophenotyping so no single bedside finding is pathognomonic."},{"id":"acute_meningitis","name":"Acute Meningitis","system":"Central Nervous System","class":"infective","find":{"neckStiffness":6,"photophobia":6,"headacheSevere":6,"alteredSensorium":6,"petechialRash":6,"seizure":6,"fever":2,"rigors":2,"behavioralChange":2,"toxicAppearing":2,"immunocompromised":2,"thunderclapHeadache":-6},"tiers":{"pathognomonic":[],"discriminative":["neckStiffness","photophobia","headacheSevere","alteredSensorium","petechialRash","seizure"],"supportive":["fever","rigors","behavioralChange","toxicAppearing","immunocompromised"],"negative":["thunderclapHeadache"]},"rationale":"Neck stiffness, photophobia, severe headache with fever and altered sensorium form the classic meningitic syndrome, and petechial/purpuric rash strongly points to meningococcemia; seizures and focal deficits reflect CNS irritation/complications, while a thunderclap headache pattern argues more for subarachnoid hemorrhage than meningitis."},{"id":"acute_myeloid_leukemia","name":"Acute Myeloid Leukemia (AML)","system":"Oncology / Hematology","class":"non_infective","find":{"mucocutaneousBleeding":6,"bleedingManifestation":6,"neutropenia":6,"absoluteNeutrophilCountLow":6,"thrombocytopenia":6,"hepatosplenomegaly":6,"fever":2,"weightLoss":2,"petechialRash":2,"mucositis":2,"lymphadenopathy":2,"hemoglobin":2,"platelets":2,"oralIntakeAdequate":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["mucocutaneousBleeding","bleedingManifestation","neutropenia","absoluteNeutrophilCountLow","thrombocytopenia","hepatosplenomegaly"],"supportive":["fever","weightLoss","petechialRash","mucositis","lymphadenopathy","hemoglobin","platelets"],"negative":["oralIntakeAdequate","clinicallyImproving"]},"rationale":"AML has no bedside pathognomonic sign; its diagnosis rests on marrow/blood morphology and genetics, but marrow-failure features (bleeding/bruising from thrombocytopenia, severe/prolonged neutropenia, mucocutaneous bleeding) alongside organomegaly and constitutional symptoms are the closest discriminative bedside/lab clues."},{"id":"acute_rheumatic_fever","name":"Acute Rheumatic Fever","system":"Rheumatology / Cardiology","class":"non_infective","find":{"polyarthralgia":6,"jointSwelling":6,"symmetricSmallJointInvolvement":6,"soreThroat":6,"myalgiaArthralgia":6,"fever":2,"rash":2,"maculopapularRash":2,"lymphadenopathy":2,"tachycardia":2,"newMurmur":2,"purulentDrainage":-6,"crepitusOrBullae":-6,"boneInvolvement":-6},"tiers":{"pathognomonic":[],"discriminative":["polyarthralgia","jointSwelling","symmetricSmallJointInvolvement","soreThroat","myalgiaArthralgia"],"supportive":["fever","rash","maculopapularRash","lymphadenopathy","tachycardia","newMurmur"],"negative":["purulentDrainage","crepitusOrBullae","boneInvolvement"]},"rationale":"ARF classically presents with migratory polyarthritis/arthralgia (often symmetric, small and large joints), preceded by streptococcal sore throat, with carditis manifesting as a new murmur; fever and rash (erythema marginatum-like) are supportive but non-specific, while findings suggesting a localized suppurative/soft-tissue or bone infection argue against this autoimmune diagnosis."},{"id":"adrenal_disorders","name":"Adrenal Cortical Disorders","system":"Endocrine","class":"non_infective","find":{"hypotension":6,"syncope":6,"abdominalPain":6,"nauseaVomiting":6,"weightLoss":6,"fever":2,"tachycardia":2,"dehydration":2,"severeAbdominalPain":2,"alteredSensorium":2,"hypertensionHx":-6},"tiers":{"pathognomonic":[],"discriminative":["hypotension","syncope","abdominalPain","nauseaVomiting","weightLoss"],"supportive":["fever","tachycardia","dehydration","severeAbdominalPain","alteredSensorium"],"negative":["hypertensionHx"]},"rationale":"Adrenal insufficiency/crisis presents with postural hypotension progressing to shock, often with GI symptoms mimicking acute abdomen, weight loss, and altered sensorium, while Cushing's is largely diagnosed biochemically rather than by bedside findings in this vocabulary."},{"id":"alcohol_and_alcohol_use_disorders","name":"Alcohol and Alcohol Use Disorders","system":"Neurologic / Psychiatric (multisystem)","class":"non_infective","find":{"alcoholExcess":6,"ataxia":6,"asterixis":6,"liverDisease":6,"behavioralChange":2,"alteredSensorium":2,"seizure":2,"nauseaVomiting":2,"jaundice":2,"hematemesis":2,"pregnancy":-6},"tiers":{"pathognomonic":[],"discriminative":["alcoholExcess","ataxia","asterixis","liverDisease"],"supportive":["behavioralChange","alteredSensorium","seizure","nauseaVomiting","jaundice","hematemesis"],"negative":["pregnancy"]},"rationale":"A history of alcohol excess/dependence with signs like ataxia, asterixis, and known liver disease strongly points to alcohol use disorder, while altered sensorium, seizures, GI bleeding and behavioral change are supportive but non-specific findings seen in withdrawal or intoxication."},{"id":"alcohol_liver_disease","name":"Alcohol-Associated Liver Disease","system":"Hepatology","class":"non_infective","find":{"alcoholExcess":6,"jaundice":6,"hepatosplenomegaly":6,"ascites":6,"asterixis":6,"rightUpperQuadrantPain":2,"abdominalDistension":2,"fever":2,"nauseaVomiting":2,"encephalopathyGrade":2,"ascitesGrade":2,"ivDrugUse":-6},"tiers":{"pathognomonic":[],"discriminative":["alcoholExcess","jaundice","hepatosplenomegaly","ascites","asterixis"],"supportive":["rightUpperQuadrantPain","abdominalDistension","fever","nauseaVomiting","encephalopathyGrade","ascitesGrade"],"negative":["ivDrugUse"]},"rationale":"Alcohol-associated liver disease is suggested by a history of alcohol excess with jaundice, tender hepatomegaly, ascites, and asterixis reflecting decompensation, but no single bedside finding is pathognomonic since viral hepatitis, MASLD, Wilson's disease, and DILI must be excluded biochemically/histologically."},{"id":"altitude_illness","name":"Altitude Illness","system":"Environmental / Multisystem (Neurologic-Pulmonary)","class":"non_infective","find":{"ataxia":6,"alteredSensorium":6,"hemoptysis":6,"increasedDyspnea":6,"dyspnea":6,"headache":2,"headacheSevere":2,"nauseaVomiting":2,"tachypnea":2,"tachycardia":2,"hypoxia":2,"crepitations":2,"focalNeuroDeficit":-6,"neckStiffness":-6,"consolidation":-6,"purulentSputum":-6},"tiers":{"pathognomonic":[],"discriminative":["ataxia","alteredSensorium","hemoptysis","increasedDyspnea","dyspnea"],"supportive":["headache","headacheSevere","nauseaVomiting","tachypnea","tachycardia","hypoxia","crepitations"],"negative":["focalNeuroDeficit","neckStiffness","consolidation","purulentSputum"]},"rationale":"Altitude illness spans AMS (nonspecific headache/nausea/fatigue) to HACE (ataxia plus altered consciousness without focal deficits, hallmark for this diagnosis) and HAPE (noncardiogenic pulmonary edema with dyspnea, tachypnea, hypoxia, and blood-tinged sputum); focal neurologic deficits, meningismus, and lobar consolidation argue against it and favor mimics."},{"id":"amoebiasis","name":"Amoebiasis (Intestinal)","system":"Infectious Diseases","class":"infective","find":{"bloodyStool":6,"tenesmus":6,"subacuteOnset":6,"abdominalPain":6,"diarrhea":2,"weightLoss":2,"severeAbdominalPain":2,"abdominalDistension":2,"dehydration":2,"contaminatedFoodWaterExposure":2,"fever":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["bloodyStool","tenesmus","subacuteOnset","abdominalPain"],"supportive":["diarrhea","weightLoss","severeAbdominalPain","abdominalDistension","dehydration","contaminatedFoodWaterExposure"],"negative":["fever","toxicAppearing"]},"rationale":"Amoebic colitis presents subacutely with gradual lower abdominal pain, tenesmus, and bloody/mucoid stools after fecal-oral exposure, but no single finding is pathognomonic; notably fewer than 40% of patients are febrile, making high fever/toxic appearance argue against typical amoebic dysentery and favor bacterial causes instead."},{"id":"amyloidosis","name":"Amyloidosis","system":"Hematology / Multisystem","class":"non_infective","find":{"hepatosplenomegaly":6,"legSwellingBilateral":6,"proteinuria":6,"raisedJVP":6,"weightLoss":6,"dyspnea":2,"orthopnea":2,"ascites":2,"jaundice":2,"albumin":2,"dysphagia":2,"ataxia":2,"fever":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","legSwellingBilateral","proteinuria","raisedJVP","weightLoss"],"supportive":["dyspnea","orthopnea","ascites","jaundice","albumin","dysphagia","ataxia"],"negative":["fever","petechialRash"]},"rationale":"Amyloidosis lacks a single bedside-pathognomonic finding (macroglossia/periorbital ecchymoses are not in the vocabulary); it is best suggested by multisystem features - nephrotic-range proteinuria with hypoalbuminemia, restrictive heart failure signs (raised JVP, bilateral edema, orthopnea), hepatosplenomegaly, and unexplained weight loss - while acute fever/toxic features argue against it."},{"id":"amyloidosis_and_other_restrictive_cardiomy","name":"Amyloidosis and Other Restrictive Cardiomyopathies","system":"Cardiovascular","class":"non_infective","find":{"orthopnea":6,"raisedJVP":6,"ascites":6,"hepatosplenomegaly":6,"legSwellingBilateral":6,"dyspnea":2,"chestPain":2,"palpitations":2,"syncope":2,"abdominalDistension":2,"atrialFibHx":2,"knownHeartFailure":2,"hypertensionHx":-6},"tiers":{"pathognomonic":[],"discriminative":["orthopnea","raisedJVP","ascites","hepatosplenomegaly","legSwellingBilateral"],"supportive":["dyspnea","chestPain","palpitations","syncope","abdominalDistension","atrialFibHx","knownHeartFailure"],"negative":["hypertensionHx"]},"rationale":"Cardiac amyloidosis/RCM presents with predominantly right-sided heart failure findings (raised JVP, ascites, hepatosplenomegaly, bilateral edema, orthopnea) with no truly pathognomonic bedside sign; longstanding uncontrolled hypertension argues for hypertensive heart disease instead."},{"id":"amyotrophic_lateral_sclerosis","name":"Amyotrophic Lateral Sclerosis (ALS)","system":"Neurology","class":"non_infective","find":{"ascendingWeakness":6,"dysphagia":6,"focalNeuroDeficit":6,"rigidity":6,"subacuteOnset":6,"ataxia":2,"weightLoss":2,"dyspnea":2,"fever":-6,"neckStiffness":-6,"petechialRash":-6,"photophobia":-6},"tiers":{"pathognomonic":[],"discriminative":["ascendingWeakness","dysphagia","focalNeuroDeficit","rigidity","subacuteOnset"],"supportive":["ataxia","weightLoss","dyspnea"],"negative":["fever","neckStiffness","petechialRash","photophobia"]},"rationale":"ALS is diagnosed clinically by finding combined upper and lower motor neuron signs (spasticity/rigidity plus progressive limb or bulbar weakness with dysphagia) evolving subacutely to chronically without a bedside pathognomonic sign; fever, meningism, and rash argue for an infective/inflammatory mimic instead."},{"id":"anemia_due_to_acute_blood","name":"Anemia Due to Acute Blood Loss","system":"Hematologic","class":"non_infective","find":{"melena":6,"gibPresentation":6,"hematemesis":6,"syncope":6,"hemoglobin":6,"tachycardia":2,"hypotension":2,"dyspnea":2,"hematuria":2,"bloodyStool":2,"hepatosplenomegaly":-6,"jaundice":-6},"tiers":{"pathognomonic":[],"discriminative":["melena","gibPresentation","hematemesis","syncope","hemoglobin"],"supportive":["tachycardia","hypotension","dyspnea","hematuria","bloodyStool"],"negative":["hepatosplenomegaly","jaundice"]},"rationale":"Acute blood loss anemia is identified by an overt bleeding source (GI bleed with melena/hematemesis, or other hemorrhage) with hemodynamic signs of hypovolemia (tachycardia, hypotension, syncope) and a falling hemoglobin, rather than by any pathognomonic finding; hemolysis-associated findings like jaundice or splenomegaly argue against it."},{"id":"antiphospholipid_syndrome","name":"Antiphospholipid Syndrome","system":"Rheumatology","class":"non_infective","find":{"legSwellingUnilateral":6,"calfTenderness":6,"focalNeuroDeficit":6,"thrombocytopenia":6,"pregnancy":6,"cerebrovascularDisease":2,"chestPain":2,"pleuriticChestPain":2,"dyspnea":2,"hemoptysis":2,"hematuria":2,"fever":-6,"petechialRash":-6,"rigors":-6},"tiers":{"pathognomonic":[],"discriminative":["legSwellingUnilateral","calfTenderness","focalNeuroDeficit","thrombocytopenia","pregnancy"],"supportive":["cerebrovascularDisease","chestPain","pleuriticChestPain","dyspnea","hemoptysis","hematuria"],"negative":["fever","petechialRash","rigors"]},"rationale":"APS presents with venous/arterial thrombosis (e.g., unilateral leg swelling/DVT, stroke) often with thrombocytopenia and pregnancy morbidity; it lacks pathognomonic bedside findings and is not typically febrile, distinguishing it from infectious/inflammatory mimics."},{"id":"aortic_regurgitation","name":"Aortic Regurgitation","system":"Cardiology","class":"non_infective","find":{"newMurmur":6,"exertionalChestPain":6,"orthopnea":6,"dyspnea":6,"palpitations":2,"chestPain":2,"legSwellingBilateral":2,"raisedJVP":2,"syncope":2,"bilateralCrackles":2,"murphySign":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","exertionalChestPain","orthopnea","dyspnea"],"supportive":["palpitations","chestPain","legSwellingBilateral","raisedJVP","syncope","bilateralCrackles"],"negative":["murphySign","tonsillarExudate"]},"rationale":"AR is best identified by the classic decrescendo diastolic regurgitant murmur (newMurmur) with progressive exertional dyspnea, orthopnea, and atypical exertional chest pain reflecting LV volume overload; no single bedside finding is fully pathognomonic, and unrelated focal findings like Murphy sign or tonsillar exudate argue against this diagnosis."},{"id":"ards","name":"Acute Respiratory Distress Syndrome (ARDS)","system":"Critical Care","class":"non_infective","find":{"pao2fio2":6,"bilateralCrackles":6,"worseningOxygenation":6,"mechanicalVentilation":6,"dyspnea":6,"hypoxia":2,"tachypnea":2,"supplementalOxygen":2,"organDysfunction":2,"suspectedInfectionSource":2,"hypotension":2,"vasopressorRequirement":2,"raisedJVP":-6,"legSwellingBilateral":-6,"orthopnea":-6,"knownHeartFailure":-6},"tiers":{"pathognomonic":[],"discriminative":["pao2fio2","bilateralCrackles","worseningOxygenation","mechanicalVentilation","dyspnea"],"supportive":["hypoxia","tachypnea","supplementalOxygen","organDysfunction","suspectedInfectionSource","hypotension","vasopressorRequirement"],"negative":["raisedJVP","legSwellingBilateral","orthopnea","knownHeartFailure"]},"rationale":"ARDS is defined by acute severe hypoxemia (low PaO2:FiO2) with bilateral pulmonary infiltrates/crackles and rapid-onset dyspnea in a patient with a predisposing insult (sepsis, aspiration, pneumonia), often progressing to mechanical ventilation; findings of volume overload/cardiac failure argue for cardiogenic edema instead."},{"id":"arterial_and_venous_thrombosis","name":"Arterial and Venous Thrombosis","system":"Hematologic / Cardiovascular","class":"non_infective","find":{"legSwellingUnilateral":6,"calfTenderness":6,"pleuriticChestPain":6,"hypoxia":6,"anticoagulated":6,"chestPain":2,"dyspnea":2,"tachycardia":2,"malignancy":2,"legSwellingBilateral":2,"syncope":2,"fever":-6,"rigors":-6,"petechialRash":-6,"diarrhea":-6},"tiers":{"pathognomonic":[],"discriminative":["legSwellingUnilateral","calfTenderness","pleuriticChestPain","hypoxia","anticoagulated"],"supportive":["chestPain","dyspnea","tachycardia","malignancy","legSwellingBilateral","syncope"],"negative":["fever","rigors","petechialRash","diarrhea"]},"rationale":"Unilateral leg swelling with calf tenderness and pleuritic chest pain/hypoxia (suggesting DVT/PE) are the most discriminative bedside clues, while malignancy and anticoagulation status support risk stratification; prominent fever, rigors, or petechial rash argue for an infective or other process rather than thrombosis."},{"id":"arthritis_associated_with_systemic_disease","name":"Arthritis Associated with Systemic Disease, and Other Arthritides","system":"Musculoskeletal/Rheumatologic","class":"non_infective","find":{"jointSwelling":6,"polyarthralgia":6,"hepatosplenomegaly":6,"diabetesHx":6,"sickleCellHx":6,"myalgiaArthralgia":2,"fever":2,"symmetricSmallJointInvolvement":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["jointSwelling","polyarthralgia","hepatosplenomegaly","diabetesHx","sickleCellHx"],"supportive":["myalgiaArthralgia","fever"],"negative":["symmetricSmallJointInvolvement","petechialRash"]},"rationale":"Diagnosis rests on recognizing an atypical joint distribution or effusion (jointSwelling/polyarthralgia) in a patient with an identifiable systemic driver (diabetes, sickle cell disease, hepatosplenomegaly from iron overload/liver disease), while symmetric small-joint involvement and rash argue for primary inflammatory arthritis instead; definitive diagnosis needs labs (transferrin saturation, fac"},{"id":"arthropod_borne_and_rodent_borne","name":"Arthropod-Borne and Rodent-Borne Virus Infections","system":"Infectious / Multisystem","class":"infective","find":{"retroorbitalPain":6,"tickExposure":6,"severeArthralgia":6,"symmetricSmallJointInvolvement":6,"bleedingManifestation":6,"fever":2,"myalgiaArthralgia":2,"headache":2,"rash":2,"maculopapularRash":2,"thrombocytopenia":2,"lymphadenopathy":2,"polyarthralgia":2,"eschar":-6,"conjunctivalSuffusion":-6,"waterExposure":-6},"tiers":{"pathognomonic":[],"discriminative":["retroorbitalPain","tickExposure","severeArthralgia","symmetricSmallJointInvolvement","bleedingManifestation"],"supportive":["fever","myalgiaArthralgia","headache","rash","maculopapularRash","thrombocytopenia","lymphadenopathy","polyarthralgia"],"negative":["eschar","conjunctivalSuffusion","waterExposure"]},"rationale":"Arbovirus/rodent-borne viral syndromes classically present with abrupt fever, severe myalgia/retro-orbital pain, and often symmetric small-joint arthralgia or rash with thrombocytopenia, with tick or mosquito exposure history as a key clue; findings like eschar or conjunctival suffusion point instead to rickettsial disease or leptospirosis, key mimics."},{"id":"aspergillosis","name":"Aspergillosis","system":"Infectious Diseases","class":"infective","find":{"hemoptysis":6,"cavitatingLesion":6,"immunocompromised":6,"neutropenia":6,"facialSwelling":6,"unilateralFacialPain":6,"prolongedFever":2,"fever":2,"weightLoss":2,"dyspnea":2,"cough":2,"prolongedCough2Weeks":2,"chestPain":2,"pleuriticChestPain":2,"oralIntakeAdequate":-6},"tiers":{"pathognomonic":[],"discriminative":["hemoptysis","cavitatingLesion","immunocompromised","neutropenia","facialSwelling","unilateralFacialPain"],"supportive":["prolongedFever","fever","weightLoss","dyspnea","cough","prolongedCough2Weeks","chestPain","pleuriticChestPain"],"negative":["oralIntakeAdequate"]},"rationale":"Invasive aspergillosis is defined by angioinvasive lung disease in neutropenic/immunocompromised hosts, often with hemoptysis and cavitation, or facial/sinus invasion causing facial pain and swelling; no bedside finding is truly pathognomonic since diagnosis requires imaging (halo/air-crescent sign) and antigen/culture confirmation."},{"id":"ataxic_disorders","name":"Ataxic Disorders","system":"Nervous system (cerebellum and spinocerebellar pathways)","class":"non_infective","find":{"ataxia":6,"focalNeuroDeficit":6,"behavioralChange":6,"headache":2,"seizure":2,"alcoholExcess":2,"weightLoss":2,"malignancy":2,"photophobia":-6,"neckStiffness":-6,"fever":-6},"tiers":{"pathognomonic":[],"discriminative":["ataxia","focalNeuroDeficit","behavioralChange"],"supportive":["headache","seizure","alcoholExcess","weightLoss","malignancy"],"negative":["photophobia","neckStiffness","fever"]},"rationale":"Ataxia (unsteady gait/incoordination) is the core defining finding, with focal neurologic deficits and behavioral change helping distinguish structural or paraneoplastic causes; meningismus and fever argue against a primary cerebellar/degenerative process and favor an infectious mimic."},{"id":"atrial_myxoma_and_other_cardiac","name":"Atrial Myxoma and Other Cardiac Tumors","system":"Cardiovascular","class":"non_infective","find":{"syncope":6,"embolicPhenomena":6,"newMurmur":6,"pulsatileMass":6,"fever":2,"weightLoss":2,"dyspnea":2,"orthopnea":2,"raisedJVP":2,"legSwellingBilateral":2,"palpitations":2,"atrialFibHx":2,"persistentBacteremia":-6,"ivDrugUse":-6,"prostheticValve":-6},"tiers":{"pathognomonic":[],"discriminative":["syncope","embolicPhenomena","newMurmur","pulsatileMass"],"supportive":["fever","weightLoss","dyspnea","orthopnea","raisedJVP","legSwellingBilateral","palpitations","atrialFibHx"],"negative":["persistentBacteremia","ivDrugUse","prostheticValve"]},"rationale":"Atrial myxoma classically presents with positional syncope, embolic phenomena, and a new/changing murmur from mechanical mitral obstruction, often with constitutional symptoms mimicking endocarditis; features suggesting true infective endocarditis (persistent bacteremia, IVDU, prosthetic valve) argue against it since myxoma is a key mimic rather than an infectious cause."},{"id":"autoimmune_polyendocrine_syndromes","name":"Autoimmune Polyendocrine Syndromes","system":"Endocrine","class":"non_infective","find":{"hypotension":6,"seizure":6,"weightLoss":6,"nauseaVomiting":2,"abdominalPain":2,"diarrhea":2,"dehydration":2,"polyuriaPolydipsia":2,"alteredSensorium":2},"tiers":{"pathognomonic":[],"discriminative":["hypotension","seizure","weightLoss"],"supportive":["nauseaVomiting","abdominalPain","diarrhea","dehydration","polyuriaPolydipsia","alteredSensorium"],"negative":[]},"rationale":"Diagnosis rests on the clinical triad of mucocutaneous candidiasis, hypoparathyroidism (tetany/seizures), and Addison's disease (hypotension, weight loss); the vocabulary lacks explicit keys for candidiasis, hypocalcemia and hyperpigmentation so only the closest available proxies are used, and no findings truly rule the disease out at the bedside."},{"id":"babesiosis","name":"Babesiosis","system":"Infectious Diseases","class":"infective","find":{"tickExposure":6,"darkUrine":6,"jaundice":6,"splenomegaly":6,"thrombocytopenia":6,"fever":2,"rigors":2,"nightSweats":2,"myalgiaArthralgia":2,"headache":2,"weightLoss":2,"renalImpairment":2,"immunocompromised":2,"travelEndemicArea":-6,"maculopapularRash":-6,"eschar":-6},"tiers":{"pathognomonic":[],"discriminative":["tickExposure","darkUrine","jaundice","splenomegaly","thrombocytopenia"],"supportive":["fever","rigors","nightSweats","myalgiaArthralgia","headache","weightLoss","renalImpairment","immunocompromised"],"negative":["travelEndemicArea","maculopapularRash","eschar"]},"rationale":"Babesiosis presents with tick exposure, hemolytic anemia (jaundice, dark urine), thrombocytopenia and splenomegaly as key discriminators from other tick-borne and febrile hemolytic illnesses; malaria-endemic travel, a distinct maculopapular rash, or an eschar point away from babesiosis toward its mimics (malaria, rickettsial disease)."},{"id":"beh_et_syndrome","name":"Behçet Syndrome","system":"Rheumatologic / Multisystem vasculitis","class":"non_infective","find":{"mucosalLesions":6,"rash":6,"severeArthralgia":6,"abdominalPain":6,"bloodyStool":6,"headacheSevere":2,"focalNeuroDeficit":2,"ataxia":2,"legSwellingUnilateral":2,"legSwellingBilateral":2,"chestPain":2,"dyspnea":2,"abdominalDistension":2,"photophobia":-6,"neckStiffness":-6},"tiers":{"pathognomonic":[],"discriminative":["mucosalLesions","rash","severeArthralgia","abdominalPain","bloodyStool"],"supportive":["headacheSevere","focalNeuroDeficit","ataxia","legSwellingUnilateral","legSwellingBilateral","chestPain","dyspnea","abdominalDistension"],"negative":["photophobia","neckStiffness"]},"rationale":"Behcet syndrome is diagnosed clinically from recurrent oral/genital mucosal ulcers, skin lesions, and arthritis, with vascular (thrombophlebitis/DVT), GI (ileocecal ulceration/bleeding), and neurologic involvement as supportive features; no single bedside finding in this vocabulary is fully pathognomonic since the closest specific signs (genital ulcers, pathergy, hypopyon) are not represented as d"},{"id":"bladder_cancer","name":"Bladder & Urinary Tract Cancer","system":"Oncology","class":"non_infective","find":{"hematuria":6,"flankPain":6,"weightLoss":2,"urinaryFrequency":2,"urinaryRetention":2,"fever":-6,"dysuria":-6},"tiers":{"pathognomonic":[],"discriminative":["hematuria","flankPain"],"supportive":["weightLoss","urinaryFrequency","urinaryRetention"],"negative":["fever","dysuria"]},"rationale":"Painless hematuria (gross or microscopic) is the hallmark presenting finding of urothelial cancer, with flank pain suggesting upper-tract obstruction; fever/dysuria argue for an infectious cause (UTI) rather than malignancy, though these can coexist."},{"id":"blastomycosis","name":"Blastomycosis","system":"Infectious Diseases","class":"infective","find":{"subacuteOnset":6,"prolongedCough2Weeks":6,"cavitatingLesion":6,"boneInvolvement":6,"travelEndemicArea":6,"fever":2,"cough":2,"weightLoss":2,"nightSweats":2,"hemoptysis":2,"dyspnea":2,"immunocompromised":2,"tbContactHistory":-6},"tiers":{"pathognomonic":[],"discriminative":["subacuteOnset","prolongedCough2Weeks","cavitatingLesion","boneInvolvement","travelEndemicArea"],"supportive":["fever","cough","weightLoss","nightSweats","hemoptysis","dyspnea","immunocompromised"],"negative":["tbContactHistory"]},"rationale":"Blastomycosis is a subacute-to-chronic pulmonary fungal infection acquired from endemic soil exposure with occasional cutaneous/osseous dissemination, but it has no truly pathognomonic bedside finding and mimics bacterial pneumonia and TB, so diagnosis relies on imaging/microbiology rather than clinical findings alone."},{"id":"bone_marrow_failure_syndromes_including","name":"Bone Marrow Failure Syndromes Including Aplastic Anemia and Myelodysplasia","system":"Hematologic","class":"non_infective","find":{"petechialRash":6,"thrombocytopenia":6,"neutropenia":6,"absoluteNeutrophilCountLow":6,"mucocutaneousBleeding":6,"fever":2,"immunocompromised":2,"weightLoss":2,"hemoglobin":2,"platelets":2,"mucositis":2,"hepatosplenomegaly":-6,"lymphadenopathy":-6,"splenomegaly":-6},"tiers":{"pathognomonic":[],"discriminative":["petechialRash","thrombocytopenia","neutropenia","absoluteNeutrophilCountLow","mucocutaneousBleeding"],"supportive":["fever","immunocompromised","weightLoss","hemoglobin","platelets","mucositis"],"negative":["hepatosplenomegaly","lymphadenopathy","splenomegaly"]},"rationale":"Aplastic anemia/marrow failure presents with pancytopenia-driven bleeding (petechiae, mucocutaneous bleeding), profound neutropenia and thrombocytopenia without hemolysis or infiltration; hepatosplenomegaly or lymphadenopathy are atypical and point instead toward leukemia, lymphoma, or infiltrative disease."},{"id":"botulism","name":"Botulism","system":"Infectious Diseases","class":"infective","find":{"dysphagia":6,"constipationOrDiarrhea":6,"ataxia":6,"headache":2,"dyspnea":2,"fever":-6,"alteredSensorium":-6,"focalNeuroDeficit":-6,"ascendingWeakness":-6},"tiers":{"pathognomonic":[],"discriminative":["dysphagia","constipationOrDiarrhea","ataxia"],"supportive":["headache","dyspnea"],"negative":["fever","alteredSensorium","focalNeuroDeficit","ascendingWeakness"]},"rationale":"Botulism classically causes descending, symmetric flaccid paralysis with cranial nerve palsies (ptosis, diplopia, dysarthria, dysphagia) and constipation from intestinal paralysis, occurring in a patient who is afebrile with a normal, intact sensorium; presence of fever, true altered consciousness, focal deficits, or ascending (rather than descending) weakness argues against botulism and favors mi"},{"id":"bradyarrhythmias","name":"Bradyarrhythmias & Heart Block","system":"Cardiology","class":"non_infective","find":{"bradycardia":6,"syncope":6,"bradypnea":6,"palpitations":2,"dyspnea":2,"alteredSensorium":2,"hypotension":2,"tachycardia":-6,"fever":-6},"tiers":{"pathognomonic":[],"discriminative":["bradycardia","syncope","bradypnea"],"supportive":["palpitations","dyspnea","alteredSensorium","hypotension"],"negative":["tachycardia","fever"]},"rationale":"Bradyarrhythmias are diagnosed primarily by a documented slow heart rate with syncope/presyncope (Stokes-Adams attacks) and related hypoperfusion symptoms; presence of tachycardia or fever argues against a primary bradyarrhythmic process, and definitive diagnosis requires ECG/monitoring rather than bedside findings alone."},{"id":"brucellosis","name":"Brucellosis","system":"Infectious Diseases","class":"infective","find":{"paroxysmalFever":6,"hepatosplenomegaly":6,"myalgiaArthralgia":6,"jointSwelling":6,"nightSweats":6,"lymphadenopathy":6,"prolongedFever":2,"weightLoss":2,"subacuteOnset":2,"backPain":2,"headache":2,"polyarthralgia":2,"petechialRash":-6,"cavitatingLesion":-6},"tiers":{"pathognomonic":[],"discriminative":["paroxysmalFever","hepatosplenomegaly","myalgiaArthralgia","jointSwelling","nightSweats","lymphadenopathy"],"supportive":["prolongedFever","weightLoss","subacuteOnset","backPain","headache","polyarthralgia"],"negative":["petechialRash","cavitatingLesion"]},"rationale":"Brucellosis presents with an undulant/relapsing fever pattern, night sweats, hepatosplenomegaly, lymphadenopathy, and prominent musculoskeletal involvement (arthralgia/monoarthritis, back pain), but lacks a truly pathognomonic finding since the picture overlaps with typhoid, TB, and other zoonoses; a petechial rash or cavitating lung lesion would argue against it."},{"id":"candidiasis","name":"Candidiasis","system":"Infectious Diseases","class":"infective","find":{"immunocompromised":6,"neutropenia":6,"centralLine":6,"mucosalLesions":6,"rash":6,"fever":2,"myalgiaArthralgia":2,"toxicAppearing":2,"antibioticsLast90Days":2,"diabetesHx":2,"mucositis":2,"persistentBacteremia":2},"tiers":{"pathognomonic":[],"discriminative":["immunocompromised","neutropenia","centralLine","mucosalLesions","rash"],"supportive":["fever","myalgiaArthralgia","toxicAppearing","antibioticsLast90Days","diabetesHx","mucositis","persistentBacteremia"],"negative":[]},"rationale":"Candidiasis is suggested by mucocutaneous white plaques/erosions and, in invasive disease, eruptive skin nodules with fever/myalgias occurring in neutropenic, immunocompromised, catheterized, or antibiotic-exposed hosts, but no single bedside finding is truly pathognomonic and diagnosis ultimately requires culture/KOH."},{"id":"cardiac_trauma","name":"Cardiac Trauma","system":"Cardiovascular","class":"non_infective","find":{"newMurmur":6,"chestPain":6,"hypotension":6,"raisedJVP":6,"ecgIschemia":6,"dyspnea":2,"tachycardia":2,"pleuriticChestPain":2,"syncope":2,"palpitations":2},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","chestPain","hypotension","raisedJVP","ecgIschemia"],"supportive":["dyspnea","tachycardia","pleuriticChestPain","syncope","palpitations"],"negative":[]},"rationale":"Cardiac trauma is a clinical/imaging diagnosis (ECG, troponin, echo) rather than a bedside-findings pattern, but blunt/penetrating chest trauma with a new regurgitant murmur, hypotension, raised JVP, chest pain, and ischemic ECG changes should raise suspicion for blunt cardiac injury or tamponade."},{"id":"cardiovascular_collapse_cardiac_arrest_and","name":"Cardiovascular Collapse, Cardiac Arrest, and Sudden Cardiac Death","system":"cardiovascular","class":"non_infective","find":{"syncope":6,"ecgIschemia":6,"knownCAD":6,"knownHeartFailure":6,"chestPain":2,"palpitations":2,"hypotension":2,"alteredSensorium":2,"seizure":2,"dyspnea":2,"stable":-6,"afebrile24h":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["syncope","ecgIschemia","knownCAD","knownHeartFailure"],"supportive":["chestPain","palpitations","hypotension","alteredSensorium","seizure","dyspnea"],"negative":["stable","afebrile24h","clinicallyImproving"]},"rationale":"Cardiac arrest/sudden cardiac death is an acute collapse event best identified by loss of pulse/consciousness with a lethal arrhythmia on ECG, often on a background of known CAD or heart failure and preceded by syncope, chest pain, or palpitations; no bedside finding is pathognomonic and stability or improvement argue against ongoing collapse."},{"id":"cat_scratch_disease","name":"Bartonellosis (incl. Cat-Scratch Disease)","system":"Infectious Diseases","class":"infective","find":{"lymphadenopathy":6,"tenderCervicalNodes":6,"prolongedFeverUnexplained":6,"hepatosplenomegaly":6,"retroorbitalPain":6,"visualDisturbance":6,"fever":2,"weightLoss":2,"nightSweats":2,"malignancy":2,"myalgiaArthralgia":2,"polyarthralgia":2,"petechialRash":-6,"toxicAppearing":-6,"immunocompromised":-6},"tiers":{"pathognomonic":[],"discriminative":["lymphadenopathy","tenderCervicalNodes","prolongedFeverUnexplained","hepatosplenomegaly","retroorbitalPain","visualDisturbance"],"supportive":["fever","weightLoss","nightSweats","malignancy","myalgiaArthralgia","polyarthralgia"],"negative":["petechialRash","toxicAppearing","immunocompromised"]},"rationale":"Cat-scratch disease classically presents with regional (often axillary/cervical) tender lymphadenopathy following cat contact, sometimes with prolonged unexplained fever, hepatosplenic involvement, or neuroretinitis causing visual disturbance; toxic appearance or petechial rash argue against this typically indolent, self-limited illness."},{"id":"cestode_infections","name":"Cestode (Tapeworm) Infections","system":"Infectious Diseases","class":"infective","find":{"seizure":6,"focalNeuroDeficit":6,"headacheSevere":6,"travelEndemicArea":6,"subacuteOnset":6,"headache":2,"behavioralChange":2,"alteredSensorium":2,"neckStiffness":2,"abdominalDiscomfort":2,"weightLoss":2,"toxicAppearing":-6,"petechialRash":-6,"prolongedFeverUnexplained":-6},"tiers":{"pathognomonic":[],"discriminative":["seizure","focalNeuroDeficit","headacheSevere","travelEndemicArea","subacuteOnset"],"supportive":["headache","behavioralChange","alteredSensorium","neckStiffness","abdominalDiscomfort","weightLoss"],"negative":["toxicAppearing","petechialRash","prolongedFeverUnexplained"]},"rationale":"Cestode infection is chiefly diagnosable via neurocysticercosis, presenting as new-onset seizures or focal neurologic deficit with subacute/chronic course in a patient from an endemic area; there is no single bedside finding that is pathognomonic, and features suggesting acute toxic/systemic sepsis argue against this indolent parasitic disease."},{"id":"chagas_trypanosomiasis","name":"Trypanosomiasis (Chagas & Sleeping Sickness)","system":"Infectious Diseases","class":"infective","find":{"knownHeartFailure":6,"ecgIschemia":6,"dysphagia":6,"abdominalDistension":6,"travelEndemicArea":6,"fever":2,"hepatosplenomegaly":2,"lymphadenopathy":2,"weightLoss":2,"palpitations":2,"syncope":2,"legSwellingBilateral":2,"raisedJVP":2,"stepladderFever":-6,"roseSpots":-6,"paroxysmalFever":-6},"tiers":{"pathognomonic":[],"discriminative":["knownHeartFailure","ecgIschemia","dysphagia","abdominalDistension","travelEndemicArea"],"supportive":["fever","hepatosplenomegaly","lymphadenopathy","weightLoss","palpitations","syncope","legSwellingBilateral","raisedJVP"],"negative":["stepladderFever","roseSpots","paroxysmalFever"]},"rationale":"Chagas is rarely diagnosable from acute bedside findings; the chronic determinate form is suggested by dilated cardiomyopathy signs, conduction/arrhythmia features, or megaesophagus/megacolon-type dysphagia and distension in a patient with endemic exposure, but confirmation requires serology/PCR rather than clinical findings alone."},{"id":"chlamydial_infection","name":"Chlamydial Infections","system":"Infectious Diseases","class":"infective","find":{"dysuria":6,"urinaryFrequency":6,"perinealPain":6,"lymphadenopathy":6,"tenesmus":6,"abdominalPain":2,"rightUpperQuadrantPain":2,"bloodyStool":2,"diarrhea":2,"urinaryRetention":2},"tiers":{"pathognomonic":[],"discriminative":["dysuria","urinaryFrequency","perinealPain","lymphadenopathy","tenesmus"],"supportive":["abdominalPain","rightUpperQuadrantPain","bloodyStool","diarrhea","urinaryRetention"],"negative":[]},"rationale":"Chlamydial infection (C. trachomatis) is largely diagnosed by NAAT rather than bedside signs, but urogenital symptoms (dysuria, urethral/cervical discharge equivalents, perineal pain), LGV-related inguinal lymphadenopathy and tenesmus/proctitis, and Fitz-Hugh-Curtis right-upper-quadrant pain are the closest available discriminative clues; most infections are asymptomatic, limiting bedside usabilit"},{"id":"cholera","name":"Cholera","system":"Infectious Diseases","class":"infective","find":{"dehydration":6,"waterExposure":6,"contaminatedFoodWaterExposure":6,"diarrhea":2,"nauseaVomiting":2,"abdominalDiscomfort":2,"hypotension":2,"tachycardia":2,"oliguria":2,"fever":-6,"bloodyStool":-6,"tenesmus":-6},"tiers":{"pathognomonic":[],"discriminative":["dehydration","waterExposure","contaminatedFoodWaterExposure"],"supportive":["diarrhea","nauseaVomiting","abdominalDiscomfort","hypotension","tachycardia","oliguria"],"negative":["fever","bloodyStool","tenesmus"]},"rationale":"Cholera presents with sudden painless voluminous watery (rice-water) diarrhea and vomiting leading to rapid dehydration, typically after contaminated water/food exposure, with fever usually absent and blood/tenesmus arguing against it in favor of dysenteric causes."},{"id":"chronic_and_recurrent_meningitis","name":"Chronic and Recurrent Meningitis","system":"Central nervous system","class":"infective","find":{"headacheSevere":6,"focalNeuroDeficit":6,"behavioralChange":6,"seizure":6,"subacuteOnset":6,"prolongedFeverUnexplained":6,"headache":2,"neckStiffness":2,"photophobia":2,"fever":2,"nightSweats":2,"eveningFever":2,"alteredSensorium":2,"tbContactHistory":2,"afebrile24h":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["headacheSevere","focalNeuroDeficit","behavioralChange","seizure","subacuteOnset","prolongedFeverUnexplained"],"supportive":["headache","neckStiffness","photophobia","fever","nightSweats","eveningFever","alteredSensorium","tbContactHistory"],"negative":["afebrile24h","clinicallyImproving"]},"rationale":"Chronic/recurrent meningitis is defined by a persistent (>4 week) or relapsing neurologic syndrome with subacute onset, headache, cranial neuropathies/focal deficits, behavioral change, seizures and constitutional symptoms (weight loss, night sweats) often in an immunocompromised or TB-exposed host, whereas classic meningismus (neck stiffness, photophobia) is common but nonspecific and less promin"},{"id":"chronic_hepatitis","name":"Chronic Hepatitis","system":"Hepatology","class":"non_infective","find":{"jaundice":6,"ascites":6,"hepatosplenomegaly":6,"asterixis":6,"encephalopathyGrade":6,"weightLoss":2,"abdominalDiscomfort":2,"nauseaVomiting":2,"darkUrine":2,"liverDisease":2,"alcoholExcess":2,"petechialRash":-6,"doubleSickening":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":[],"discriminative":["jaundice","ascites","hepatosplenomegaly","asterixis","encephalopathyGrade"],"supportive":["weightLoss","abdominalDiscomfort","nauseaVomiting","darkUrine","liverDisease","alcoholExcess"],"negative":["petechialRash","doubleSickening","tonsillarExudate"]},"rationale":"Chronic hepatitis presents with insidious signs of hepatic dysfunction (jaundice, ascites, hepatosplenomegaly, encephalopathy/asterixis) rather than acute infectious findings, and diagnosis fundamentally requires serology/biochemistry/biopsy beyond bedside exam."},{"id":"chronic_lymphocytic_leukemia","name":"Chronic Lymphocytic Leukemia (CLL)","system":"Oncology / Hematology","class":"non_infective","find":{"lymphadenopathy":6,"hepatosplenomegaly":6,"weightLoss":2,"nightSweats":2,"fever":2,"malignancy":2,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["lymphadenopathy","hepatosplenomegaly"],"supportive":["weightLoss","nightSweats","fever","malignancy"],"negative":["petechialRash"]},"rationale":"CLL typically presents with painless lymphadenopathy and hepatosplenomegaly in an older adult, sometimes with constitutional symptoms, but definitive diagnosis requires peripheral blood lymphocyte count and flow cytometry rather than bedside findings alone."},{"id":"chronic_myeloid_leukemia","name":"Chronic Myeloid Leukemia (CML)","system":"Oncology / Hematology","class":"non_infective","find":{"hepatosplenomegaly":6,"splenomegaly":6,"thrombocytopenia":6,"weightLoss":6,"fever":2,"nightSweats":2,"lymphadenopathy":2,"abdominalDiscomfort":2,"malignancy":2,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","splenomegaly","thrombocytopenia","weightLoss"],"supportive":["fever","nightSweats","lymphadenopathy","abdominalDiscomfort","malignancy"],"negative":["petechialRash"]},"rationale":"CML is diagnosed by peripheral smear/marrow cytogenetics (Philadelphia chromosome/BCR::ABL1), not bedside findings; splenomegaly with constitutional symptoms is the main clinical clue, so tiers are kept minimal and usable reflects the need for lab/cytogenetic confirmation."},{"id":"chronic_obstructive_pulmonary_disease","name":"Chronic Obstructive Pulmonary Disease","system":"Respiratory","class":"non_infective","find":{"knownCOPD":6,"increasedDyspnea":6,"increasedSputumVolume":6,"purulentSputum":6,"wheeze":6,"cough":2,"coughRadio":2,"dyspnea":2,"tachypnea":2,"hypoxia":2,"supplementalOxygen":2},"tiers":{"pathognomonic":[],"discriminative":["knownCOPD","increasedDyspnea","increasedSputumVolume","purulentSputum","wheeze"],"supportive":["cough","coughRadio","dyspnea","tachypnea","hypoxia","supplementalOxygen"],"negative":[]},"rationale":"COPD exacerbation is best identified from known COPD history with acute worsening of baseline dyspnea, sputum volume/purulence, and wheeze; cough, dyspnea, tachypnea and hypoxia are supportive but non-specific across respiratory disease."},{"id":"chronic_pancreatitis","name":"Chronic Pancreatitis","system":"Gastroenterology","class":"non_infective","find":{"weightLoss":6,"alcoholExcess":6,"abdominalPain":6,"jaundice":6,"nauseaVomiting":2,"diabetesHx":2,"dehydration":2,"fever":-6,"rigors":-6,"toxicAppearing":-6,"severeAbdominalPain":-6},"tiers":{"pathognomonic":[],"discriminative":["weightLoss","alcoholExcess","abdominalPain","jaundice"],"supportive":["nauseaVomiting","diabetesHx","dehydration"],"negative":["fever","rigors","toxicAppearing","severeAbdominalPain"]},"rationale":"Chronic pancreatitis presents with recurrent/chronic epigastric pain often linked to alcohol excess, weight loss, and features of exocrine/endocrine insufficiency (diabetes, maldigestion), with jaundice from biliary stricture in some; it lacks a bedside pathognomonic sign and acute septic/toxic features argue against it in favor of acute pancreatitis or another acute process."},{"id":"chronic_venous_disease","name":"Chronic Venous Disease & Lymphedema","system":"Vascular","class":"non_infective","find":{"legSwellingUnilateral":6,"legSwellingBilateral":6,"skinErythema":6,"calfTenderness":2,"peripheralVascularDisease":2,"skinWarmth":2,"fever":-6,"toxicAppearing":-6,"rapidlySpreadingErythema":-6,"severePain":-6},"tiers":{"pathognomonic":[],"discriminative":["legSwellingUnilateral","legSwellingBilateral","skinErythema"],"supportive":["calfTenderness","peripheralVascularDisease","skinWarmth"],"negative":["fever","toxicAppearing","rapidlySpreadingErythema","severePain"]},"rationale":"Chronic venous disease presents with chronic, often bilateral (or unilateral if post-thrombotic) leg swelling and skin changes like erythema/pigmentation without acute systemic toxicity; presence of fever, toxic appearance, or rapidly spreading erythema/severe pain argues instead for cellulitis or a necrotizing process."},{"id":"cirrhosis_and_its_complications","name":"Cirrhosis and Its Complications","system":"Gastrointestinal/Hepatobiliary","class":"non_infective","find":{"ascites":6,"encephalopathyGrade":6,"asterixis":6,"jaundice":6,"liverDisease":6,"hepatosplenomegaly":6,"ascitesGrade":2,"abdominalDistension":2,"hematemesis":2,"melena":2,"gibPresentation":2,"alcoholExcess":2,"splenomegaly":2,"bilirubin":2,"knownHeartFailure":-6,"raisedJVP":-6},"tiers":{"pathognomonic":[],"discriminative":["ascites","encephalopathyGrade","asterixis","jaundice","liverDisease","hepatosplenomegaly"],"supportive":["ascitesGrade","abdominalDistension","hematemesis","melena","gibPresentation","alcoholExcess","splenomegaly","bilirubin"],"negative":["knownHeartFailure","raisedJVP"]},"rationale":"Cirrhosis is diagnosed from stigmata of chronic liver disease with portal hypertension (ascites, encephalopathy/asterixis, jaundice, splenomegaly, coagulopathy/hypoalbuminemia) rather than any single pathognomonic sign; features suggesting cardiac (congestive) rather than cirrhotic etiology argue against primary hepatic cirrhosis."},{"id":"coagulation_disorders","name":"Coagulation Disorders","system":"Haematology","class":"non_infective","find":{"jointSwelling":6,"mucocutaneousBleeding":6,"bleedingManifestation":6,"hematuria":6,"melena":2,"hematemesis":2,"gibPresentation":2,"headInjury":2,"petechialRash":-6,"thrombocytopenia":-6},"tiers":{"pathognomonic":[],"discriminative":["jointSwelling","mucocutaneousBleeding","bleedingManifestation","hematuria"],"supportive":["melena","hematemesis","gibPresentation","headInjury"],"negative":["petechialRash","thrombocytopenia"]},"rationale":"Coagulation factor deficiencies (hemophilia, VWD) classically present with hemarthrosis/joint bleeding and deep-tissue or mucosal bleeding out of proportion to trauma, with normal platelet counts distinguishing them from platelet-type petechial bleeding disorders."},{"id":"cocaine_other_psychostimulants_and_halluci","name":"Cocaine, Other Psychostimulants, and Hallucinogens","system":"Neurologic / Substance Use (Toxicology)","class":"non_infective","find":{"behavioralChange":6,"seizure":6,"chestPain":6,"headacheSevere":6,"ivDrugUse":6,"rigidity":6,"tachycardia":2,"hypertensionHx":2,"alteredSensorium":2,"tachypnea":2,"palpitations":2,"focalNeuroDeficit":2,"myalgiaArthralgia":2,"hypotension":-6,"bradycardia":-6,"miosisSecretions":-6,"hypothermia":-6},"tiers":{"pathognomonic":[],"discriminative":["behavioralChange","seizure","chestPain","headacheSevere","ivDrugUse","rigidity"],"supportive":["tachycardia","hypertensionHx","alteredSensorium","tachypnea","palpitations","focalNeuroDeficit","myalgiaArthralgia"],"negative":["hypotension","bradycardia","miosisSecretions","hypothermia"]},"rationale":"Psychostimulant/hallucinogen toxicity presents as sympathomimetic toxidrome with agitation/behavioral change, hyperthermia, tachycardia, hypertension, seizures, chest pain, and IV drug use history, but no single finding is pathognomonic since it overlaps with sepsis, thyroid storm, and serotonin syndrome; hypotension, bradycardia, and cholinergic miosis argue against it."},{"id":"coccidioidomycosis","name":"Coccidioidomycosis","system":"Infectious Diseases","class":"infective","find":{"nightSweats":6,"maculopapularRash":6,"severeArthralgia":6,"subacuteOnset":6,"travelEndemicArea":6,"fever":2,"cough":2,"pleuriticChestPain":2,"weightLoss":2,"lymphadenopathy":2,"headacheSevere":2},"tiers":{"pathognomonic":[],"discriminative":["nightSweats","maculopapularRash","severeArthralgia","subacuteOnset","travelEndemicArea"],"supportive":["fever","cough","pleuriticChestPain","weightLoss","lymphadenopathy","headacheSevere"],"negative":[]},"rationale":"Coccidioidomycosis presents subacutely after inhalation exposure in endemic areas with fever, cough, pleuritic chest pain, night sweats, toxic erythema/rash, and symmetrical 'desert rheumatism' arthralgias; no vocabulary finding argues against the diagnosis, so the negative tier is empty."},{"id":"colorectal_cancer","name":"Colorectal Cancer","system":"Oncology","class":"non_infective","find":{"bloodyStool":6,"melena":6,"gibPresentation":6,"constipationOrDiarrhea":6,"tenesmus":6,"weightLoss":2,"abdominalPain":2,"abdominalDiscomfort":2,"abdominalDistension":2,"dehydration":2},"tiers":{"pathognomonic":[],"discriminative":["bloodyStool","melena","gibPresentation","constipationOrDiarrhea","tenesmus"],"supportive":["weightLoss","abdominalPain","abdominalDiscomfort","abdominalDistension","dehydration"],"negative":[]},"rationale":"Colorectal cancer classically presents with hematochezia/melena, altered bowel habits (constipation or diarrhea), tenesmus (rectosigmoid lesions), and abdominal cramping, often with weight loss and iron-deficiency-related nonspecific abdominal symptoms; no bedside finding is truly pathognomonic since diagnosis requires colonoscopy/biopsy."},{"id":"common_atrial_flutter_and_macroreentrant","name":"Common Atrial Flutter and Macroreentrant and Multifocal Atrial Tachycardias","system":"Cardiovascular","class":"non_infective","find":{"palpitations":6,"syncope":6,"tachycardia":2,"dyspnea":2,"chestPain":2,"atrialFibHx":2,"knownHeartFailure":2},"tiers":{"pathognomonic":[],"discriminative":["palpitations","syncope"],"supportive":["tachycardia","dyspnea","chestPain","atrialFibHx","knownHeartFailure"],"negative":[]},"rationale":"Atrial flutter/macroreentrant AT is fundamentally an ECG diagnosis (sawtooth waves, regular tachycardia); bedside findings like palpitations and syncope are discriminative for an arrhythmic process but are shared with other SVTs, so no bedside finding is pathognomonic."},{"id":"common_viral_respiratory_infections_other","name":"Common Viral Respiratory Infections, Other Than COVID-19","system":"Respiratory","class":"infective","find":{"coryza":6,"nasalCongestion":6,"soreThroat":6,"tenderCervicalNodes":6,"cough":2,"coughRadio":2,"facialPain":2,"wheeze":2,"myalgiaArthralgia":2,"headache":2,"consolidation":-6,"multilobar":-6,"severeCriteria":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["coryza","nasalCongestion","soreThroat","tenderCervicalNodes"],"supportive":["cough","coughRadio","facialPain","wheeze","myalgiaArthralgia","headache"],"negative":["consolidation","multilobar","severeCriteria","toxicAppearing"]},"rationale":"Common non-COVID viral respiratory infections (rhinovirus, RSV, parainfluenza, etc.) present with coryza, nasal congestion, sore throat and mild tender cervical nodes rather than any pathognomonic sign; presence of consolidation, multilobar infiltrates, severity criteria, or toxic appearance argues for bacterial pneumonia or a more severe mimic rather than uncomplicated viral upper/lower respirato"},{"id":"concussion_and_other_traumatic_brain","name":"Concussion and Other Traumatic Brain Injuries","system":"Nervous system","class":"non_infective","find":{"headInjury":6,"gcs":6,"alteredSensorium":6,"focalNeuroDeficit":6,"seizure":6,"headacheSevere":2,"behavioralChange":2,"nauseaVomiting":2,"ataxia":2,"visualDisturbance":2,"fever":-6,"rigors":-6,"toxicAppearing":-6,"neckStiffness":-6},"tiers":{"pathognomonic":[],"discriminative":["headInjury","gcs","alteredSensorium","focalNeuroDeficit","seizure"],"supportive":["headacheSevere","behavioralChange","nauseaVomiting","ataxia","visualDisturbance"],"negative":["fever","rigors","toxicAppearing","neckStiffness"]},"rationale":"TBI is a diagnosis of history (recent head injury/fall) plus exam findings such as reduced GCS, altered sensorium, focal neurologic deficit, or post-traumatic seizure; infectious/inflammatory signs like fever and neck stiffness argue against a purely traumatic etiology and favor meningitis or other differentials."},{"id":"covid19","name":"COVID-19 (SARS-CoV-2)","system":"Infectious Diseases","class":"infective","find":{"cough":6,"soreThroat":6,"dyspnea":6,"myalgiaArthralgia":6,"headache":6,"fever":2,"diarrhea":2,"nauseaVomiting":2,"alteredSensorium":2,"hypoxia":2,"tachypnea":2,"purulentSputum":-6,"tonsillarExudate":-6,"consolidation":-6},"tiers":{"pathognomonic":[],"discriminative":["cough","soreThroat","dyspnea","myalgiaArthralgia","headache"],"supportive":["fever","diarrhea","nauseaVomiting","alteredSensorium","hypoxia","tachypnea"],"negative":["purulentSputum","tonsillarExudate","consolidation"]},"rationale":"COVID-19 has no pathognomonic finding; anosmia/dysgeusia is classic but not in the vocabulary, so respiratory/constitutional symptoms (cough, sore throat, dyspnea, myalgia, headache) are the closest discriminators, while purulent sputum, tonsillar exudate, and lobar consolidation argue more for bacterial pneumonia/pharyngitis."},{"id":"cryptococcosis","name":"Cryptococcosis","system":"Infectious Diseases","class":"infective","find":{"immunocompromised":6,"headacheSevere":6,"neckStiffness":6,"behavioralChange":6,"visualDisturbance":6,"subacuteOnset":6,"fever":2,"prolongedFeverUnexplained":2,"alteredSensorium":2,"photophobia":2,"seizure":2,"focalNeuroDeficit":2,"cough":2,"petechialRash":-6,"roseSpots":-6},"tiers":{"pathognomonic":[],"discriminative":["immunocompromised","headacheSevere","neckStiffness","behavioralChange","visualDisturbance","subacuteOnset"],"supportive":["fever","prolongedFeverUnexplained","alteredSensorium","photophobia","seizure","focalNeuroDeficit","cough"],"negative":["petechialRash","roseSpots"]},"rationale":"Cryptococcosis classically presents as a subacute-to-chronic meningoencephalitis in immunocompromised hosts with headache, neck stiffness, behavioral change, and visual disturbance (from raised ICP), often without classic meningismus; no single bedside finding is pathognomonic since diagnosis requires CSF antigen/culture."},{"id":"cystic_fibrosis","name":"Cystic Fibrosis","system":"Respiratory","class":"non_infective","find":{"knownBronchiectasis":6,"increasedSputumVolume":6,"purulentSputum":6,"foulSmellingSputum":6,"hemoptysis":6,"cough":2,"prolongedCough2Weeks":2,"increasedDyspnea":2,"wheeze":2,"weightLoss":2,"crepitations":2,"tbContactHistory":-6,"travelEndemicArea":-6},"tiers":{"pathognomonic":[],"discriminative":["knownBronchiectasis","increasedSputumVolume","purulentSputum","foulSmellingSputum","hemoptysis"],"supportive":["cough","prolongedCough2Weeks","increasedDyspnea","wheeze","weightLoss","crepitations"],"negative":["tbContactHistory","travelEndemicArea"]},"rationale":"CF cannot be diagnosed from bedside findings alone (requires sweat chloride/CFTR genetics), but pulmonary exacerbations present with known bronchiectasis, increased purulent/foul-smelling sputum, hemoptysis, and chronic productive cough, distinguishing it from acute infective mimics."},{"id":"cytomegalovirus_infection","name":"Cytomegalovirus (CMV) Infection","system":"Infectious Diseases","class":"infective","find":{"hepatosplenomegaly":6,"prolongedFever":6,"immunocompromised":6,"fever":2,"weightLoss":2,"lymphadenopathy":2,"malignancy":2,"tonsillarExudate":-6,"tenderCervicalNodes":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","prolongedFever","immunocompromised"],"supportive":["fever","weightLoss","lymphadenopathy","malignancy"],"negative":["tonsillarExudate","tenderCervicalNodes"]},"rationale":"CMV mononucleosis classically presents as a heterophile-negative, prolonged febrile illness with hepatosplenomegaly, often in immunocompromised hosts, distinguishing it from EBV mononucleosis where exudative pharyngitis and tender cervical lymphadenopathy are prominent (arguing against CMV)."},{"id":"deep_venous_thrombosis_and_pulmonary","name":"Deep-Venous Thrombosis and Pulmonary Thromboembolism","system":"Cardiovascular / Venous (Vascular)","class":"non_infective","find":{"legSwellingUnilateral":6,"calfTenderness":6,"pleuriticChestPain":6,"hemoptysis":6,"syncope":6,"dyspnea":2,"chestPain":2,"tachycardia":2,"tachypnea":2,"hypoxia":2,"legSwellingBilateral":2,"fever":-6,"rigors":-6,"skinErythema":-6},"tiers":{"pathognomonic":[],"discriminative":["legSwellingUnilateral","calfTenderness","pleuriticChestPain","hemoptysis","syncope"],"supportive":["dyspnea","chestPain","tachycardia","tachypnea","hypoxia","legSwellingBilateral"],"negative":["fever","rigors","skinErythema"]},"rationale":"Unilateral leg swelling with calf tenderness plus pleuritic chest pain, hemoptysis, or syncope strongly suggest DVT/PE, while fever/rigors/erythema point instead toward cellulitis mimicking DVT."},{"id":"dementia_with_lewy_bodies","name":"Dementia with Lewy Bodies","system":"Nervous system","class":"non_infective","find":{"behavioralChange":6,"ataxia":6,"alteredSensorium":2,"syncope":2,"cerebrovascularDisease":2,"focalNeuroDeficit":-6},"tiers":{"pathognomonic":[],"discriminative":["behavioralChange","ataxia"],"supportive":["alteredSensorium","syncope","cerebrovascularDisease"],"negative":["focalNeuroDeficit"]},"rationale":"DLB's defining features (visual hallucinations, cognitive fluctuation, REM sleep behavior disorder, parkinsonism) have no corresponding keys in this vocabulary; only nonspecific behavioral/cognitive and gait findings are approximable, and a clear focal neurological deficit argues against DLB in favor of a structural/vascular cause."},{"id":"diabetes_mellitus","name":"Diabetes Mellitus","system":"Endocrine / Metabolic","class":"non_infective","find":{"polyuriaPolydipsia":6,"ketonemia":6,"weightLoss":6,"diabeticFootUlcer":6,"diabetesHx":2,"dehydration":2,"alteredSensorium":2,"nauseaVomiting":2,"abdominalPain":2,"complicatedUTIRisk":2},"tiers":{"pathognomonic":[],"discriminative":["polyuriaPolydipsia","ketonemia","weightLoss","diabeticFootUlcer"],"supportive":["diabetesHx","dehydration","alteredSensorium","nauseaVomiting","abdominalPain","complicatedUTIRisk"],"negative":[]},"rationale":"Diabetes is diagnosed by hyperglycemia criteria (HbA1c/FPG/OGTT) rather than a single pathognomonic bedside sign, but polyuria/polydipsia with weight loss and ketonemia are strongly discriminative presenting features, especially with DKA, while a known diabetic foot ulcer is a classic complication-based clue."},{"id":"diabetes_mellitus_complications","name":"Diabetes Mellitus: Complications","system":"Endocrine/Metabolic (multisystem)","class":"non_infective","find":{"diabeticFootUlcer":6,"proteinuria":6,"polyuriaPolydipsia":6,"boneInvolvement":6,"diabetesHx":6,"dysuria":2,"urinaryFrequency":2,"peripheralVascularDisease":2,"ascendingWeakness":2,"visualDisturbance":2,"hypertensionHx":2},"tiers":{"pathognomonic":[],"discriminative":["diabeticFootUlcer","proteinuria","polyuriaPolydipsia","boneInvolvement","diabetesHx"],"supportive":["dysuria","urinaryFrequency","peripheralVascularDisease","ascendingWeakness","visualDisturbance","hypertensionHx"],"negative":[]},"rationale":"Diabetic complications are largely diagnosed via screening (retinal exam, UACR, monofilament testing) rather than acute bedside findings, but foot ulceration, proteinuria/albuminuria, polyuria-polydipsia, suspected osteomyelitis, and known diabetes history are the closest available discriminative markers, with peripheral vascular disease, neuropathic symptoms, visual disturbance, and urinary sympt"},{"id":"diabetes_mellitus_management_and_therapies","name":"Diabetes Mellitus: Management and Therapies","system":"Endocrine/Metabolic","class":"non_infective","find":{"ketonemia":6,"polyuriaPolydipsia":6,"diabetesHx":6,"nauseaVomiting":2,"abdominalPain":2,"alteredSensorium":2,"tachycardia":2,"hypotension":2,"dehydration":2},"tiers":{"pathognomonic":[],"discriminative":["ketonemia","polyuriaPolydipsia","diabetesHx"],"supportive":["nauseaVomiting","abdominalPain","alteredSensorium","tachycardia","hypotension","dehydration"],"negative":[]},"rationale":"Ketonemia with high-anion-gap acidosis plus polyuria/polydipsia and known diabetes history are strongly discriminative for diabetic decompensation (DKA/HHS), while GI symptoms, altered sensorium, and volume-depletion signs are supportive but non-specific."},{"id":"dilated_cardiomyopathy","name":"Dilated Cardiomyopathy","system":"Cardiology","class":"non_infective","find":{"newMurmur":6,"raisedJVP":6,"orthopnea":6,"atrialFibHx":6,"embolicPhenomena":6,"dyspnea":2,"legSwellingBilateral":2,"bilateralCrackles":2,"palpitations":2,"syncope":2,"knownHeartFailure":2,"consolidation":-6,"murphySign":-6,"focalNeuroDeficit":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","raisedJVP","orthopnea","atrialFibHx","embolicPhenomena"],"supportive":["dyspnea","legSwellingBilateral","bilateralCrackles","palpitations","syncope","knownHeartFailure"],"negative":["consolidation","murphySign","focalNeuroDeficit"]},"rationale":"DCM presents with progressive heart-failure findings (raised JVP, orthopnea, bilateral edema/crackles, new regurgitant murmur from LV dilation causing functional MR) and arrhythmia/embolic complications (AF, embolic phenomena), but no single bedside finding is pathognomonic and definitive diagnosis requires echocardiography."},{"id":"diphtheria","name":"Diphtheria","system":"Infectious Diseases","class":"infective","find":{"tonsillarExudate":12,"soreThroat":6,"tenderCervicalNodes":6,"facialSwelling":6,"dysphagia":6,"fever":2,"toxicAppearing":2,"coryza":-6,"nasalCongestion":-6},"tiers":{"pathognomonic":["tonsillarExudate"],"discriminative":["soreThroat","tenderCervicalNodes","facialSwelling","dysphagia"],"supportive":["fever","toxicAppearing"],"negative":["coryza","nasalCongestion"]},"rationale":"The tightly adherent gray pseudomembrane (best represented by tonsillarExudate) with bull-neck submandibular/facial swelling and dysphagia strongly points to diphtheria, while prominent coryza/nasal congestion favor a viral pharyngitis mimic instead."},{"id":"diseases_caused_by_gram_negative","name":"Diseases Caused by Gram-Negative Enteric Bacilli","system":"Multisystem / Infectious Diseases","class":"infective","find":{"flankPain":6,"costovertebralTenderness":6,"feverGU":6,"dysuria":6,"urinaryFrequency":6,"rightUpperQuadrantPain":6,"fever":2,"rigors":2,"toxicAppearing":2,"organDysfunction":2,"lactateElevated":2,"hypotension":2,"abdominalPain":2,"indwellingCatheter":2,"soreThroat":-6,"tonsillarExudate":-6,"photophobia":-6,"retroorbitalPain":-6},"tiers":{"pathognomonic":[],"discriminative":["flankPain","costovertebralTenderness","feverGU","dysuria","urinaryFrequency","rightUpperQuadrantPain"],"supportive":["fever","rigors","toxicAppearing","organDysfunction","lactateElevated","hypotension","abdominalPain","indwellingCatheter"],"negative":["soreThroat","tonsillarExudate","photophobia","retroorbitalPain"]},"rationale":"This category represents extraintestinal infections by enteric gram-negative bacilli (mainly E. coli, Klebsiella), most commonly presenting as UTI/pyelonephritis or bacteremia with an abdominal or urinary source, with hepatobiliary infection (hvKp liver abscess) as a distinctive variant; findings are syndromic (source-localizing) rather than pathognomonic for the organism itself."},{"id":"diseases_of_esophagus","name":"Diseases of the Esophagus","system":"Gastroenterology","class":"non_infective","find":{"dysphagia":6,"weightLoss":6,"subacuteOnset":6,"chestPain":2,"nauseaVomiting":2,"hematemesis":2,"fever":-6,"diarrhea":-6,"bloodyStool":-6},"tiers":{"pathognomonic":[],"discriminative":["dysphagia","weightLoss","subacuteOnset"],"supportive":["chestPain","nauseaVomiting","hematemesis"],"negative":["fever","diarrhea","bloodyStool"]},"rationale":"Esophageal disease (achalasia, structural stricture, motility disorder) presents mainly with dysphagia (progressive, with weight loss suggesting malignancy or pseudoachalasia) rather than acute infectious features; presence of fever or diarrhea points away toward an infectious/GI process instead."},{"id":"diseases_of_the_aorta","name":"Diseases of the Aorta","system":"Cardiovascular","class":"non_infective","find":{"chestPain":6,"backPain":6,"pulsatileMass":6,"syncope":6,"focalNeuroDeficit":6,"hypotension":6,"dyspnea":2,"newMurmur":2,"hypertensionHx":2,"ageOver50":2,"legSwellingUnilateral":2,"abdominalPain":2,"pleuriticChestPain":-6,"fever":-6},"tiers":{"pathognomonic":[],"discriminative":["chestPain","backPain","pulsatileMass","syncope","focalNeuroDeficit","hypotension"],"supportive":["dyspnea","newMurmur","hypertensionHx","ageOver50","legSwellingUnilateral","abdominalPain"],"negative":["pleuriticChestPain","fever"]},"rationale":"Aortic disease (aneurysm/dissection) is best distinguished by tearing chest/back pain radiating to the interscapular area, a pulsatile abdominal mass, syncope, focal neurologic deficits from branch occlusion, and hypotension/shock from rupture, while pleuritic pain and fever argue for alternative pleuropulmonary or infective causes rather than aortic catastrophe."},{"id":"diseases_of_the_spinal_cord","name":"Diseases of the Spinal Cord","system":"Nervous system","class":"non_infective","find":{"ascendingWeakness":6,"backPain":6,"urinaryRetention":6,"focalNeuroDeficit":6,"fever":2,"subacuteOnset":2,"weightLoss":2,"malignancy":2,"headInjury":2,"dysuria":2,"headacheSevere":-6,"neckStiffness":-6,"photophobia":-6,"seizure":-6},"tiers":{"pathognomonic":[],"discriminative":["ascendingWeakness","backPain","urinaryRetention","focalNeuroDeficit"],"supportive":["fever","subacuteOnset","weightLoss","malignancy","headInjury","dysuria"],"negative":["headacheSevere","neckStiffness","photophobia","seizure"]},"rationale":"Spinal cord disease is best recognized by a horizontal sensory/motor level with weakness, bladder/bowel dysfunction, and back pain, often with red-flag features (fever, malignancy) suggesting compression or infection; meningitic/encephalitic findings like neck stiffness and photophobia argue against an isolated cord process."},{"id":"disorders_caused_by_venomous_snakebites","name":"Disorders Caused by Venomous Snakebites and Marine Animal Exposures","system":"Toxicology / Envenomation (multisystem)","class":"non_infective","find":{"severePain":6,"crepitusOrBullae":6,"rapidlySpreadingErythema":6,"bleedingManifestation":6,"mucocutaneousBleeding":6,"skinErythema":2,"skinWarmth":2,"thrombocytopenia":2,"renalImpairment":2,"oliguria":2,"hypotension":2,"symmetricSmallJointInvolvement":-6,"tonsillarExudate":-6,"purulentNasalDischarge":-6},"tiers":{"pathognomonic":[],"discriminative":["severePain","crepitusOrBullae","rapidlySpreadingErythema","bleedingManifestation","mucocutaneousBleeding"],"supportive":["skinErythema","skinWarmth","thrombocytopenia","renalImpairment","oliguria","hypotension"],"negative":["symmetricSmallJointInvolvement","tonsillarExudate","purulentNasalDischarge"]},"rationale":"Venomous snakebite envenomation is diagnosed clinically from progressive local findings at the bite site (severe/out-of-proportion pain, rapidly spreading erythema/swelling, hemorrhagic bullae or crepitus) combined with systemic coagulopathy/bleeding and renal injury, with no single vocabulary finding being fully pathognomonic since these overlap with cellulitis and other envenomation mimics."},{"id":"disorders_of_absorption","name":"Malabsorption (Disorders of Absorption)","system":"Gastroenterology","class":"non_infective","find":{"diarrhea":6,"weightLoss":6,"abdominalDistension":6,"dehydration":6,"abdominalPain":2,"nauseaVomiting":2,"constipationOrDiarrhea":2,"subacuteOnset":2,"bloodyStool":2,"hypotension":2,"gibPresentation":-6,"jaundice":-6,"murphySign":-6},"tiers":{"pathognomonic":[],"discriminative":["diarrhea","weightLoss","abdominalDistension","dehydration"],"supportive":["abdominalPain","nauseaVomiting","constipationOrDiarrhea","subacuteOnset","bloodyStool","hypotension"],"negative":["gibPresentation","jaundice","murphySign"]},"rationale":"Malabsorption/disorders of absorption present with chronic diarrhea (often steatorrheic), unintentional weight loss, abdominal distension, and dehydration from ongoing GI losses, but no single bedside finding is pathognomonic; findings like jaundice or a positive Murphy sign point instead toward hepatobiliary disease rather than a primary absorptive disorder."},{"id":"disorders_of_the_neurohypophysis","name":"Disorders of the Neurohypophysis","system":"Endocrine","class":"non_infective","find":{"polyuriaPolydipsia":6,"dehydration":6,"proteinuria":6,"headache":2,"seizure":2,"alteredSensorium":2,"nauseaVomiting":2,"behavioralChange":2,"oliguria":-6,"fever":-6},"tiers":{"pathognomonic":[],"discriminative":["polyuriaPolydipsia","dehydration","proteinuria"],"supportive":["headache","seizure","alteredSensorium","nauseaVomiting","behavioralChange"],"negative":["oliguria","fever"]},"rationale":"Disorders of the neurohypophysis (AVP deficiency/resistance and SIAD) present bedside primarily through marked polyuria-polydipsia with dilute urine and dehydration, sometimes with severe hyponatremia symptoms (headache, seizure, altered sensorium, nausea); presence of oliguria or fever argues against a pure water-balance disorder of this axis."},{"id":"disorders_of_the_pleura","name":"Disorders of the Pleura","system":"Respiratory","class":"non_infective","find":{"pleuriticChestPain":6,"dyspnea":6,"orthopnea":6,"raisedJVP":6,"legSwellingBilateral":6,"abdominalDistension":6,"chestPain":2,"cough":2,"fever":2,"weightLoss":2,"dysphagia":2,"malignancy":2,"liverDisease":2,"knownHeartFailure":2},"tiers":{"pathognomonic":[],"discriminative":["pleuriticChestPain","dyspnea","orthopnea","raisedJVP","legSwellingBilateral","abdominalDistension"],"supportive":["chestPain","cough","fever","weightLoss","dysphagia","malignancy","liverDisease","knownHeartFailure"],"negative":[]},"rationale":"Pleural effusion presents with pleuritic chest pain, dyspnea, and signs of the underlying cause (orthopnea/raised JVP for cardiac, ascites/liver disease for hepatic hydrothorax, weight loss/malignancy for neoplastic exudate); no single bedside finding is pathognomonic since diagnosis requires thoracentesis and fluid analysis."},{"id":"diverticular_disease","name":"Diverticular Disease","system":"Gastroenterology","class":"non_infective","find":{"severeAbdominalPain":6,"abdominalDistension":6,"constipationOrDiarrhea":6,"bloodyStool":6,"melena":6,"gibPresentation":6,"fever":2,"abdominalPain":2,"nauseaVomiting":2,"dehydration":2,"tenesmus":-6,"diarrhea":-6},"tiers":{"pathognomonic":[],"discriminative":["severeAbdominalPain","abdominalDistension","constipationOrDiarrhea","bloodyStool","melena","gibPresentation"],"supportive":["fever","abdominalPain","nauseaVomiting","dehydration"],"negative":["tenesmus","diarrhea"]},"rationale":"Acute diverticulitis presents with fever and left-sided abdominal pain/distension with altered bowel habit, while diverticulosis is a leading cause of abrupt painless lower-GI bleeding (bloody stool/melena) in older adults; tenesmus and diarrhea are more typical of colitis/IBD mimics and argue against uncomplicated diverticular disease."},{"id":"donovanosis","name":"Donovanosis","system":"Genitourinary / Sexually Transmitted Infection","class":"infective","find":{"sharplyDemarcatedBorder":6,"rapidlySpreadingErythema":6,"lymphadenopathy":2,"subacuteOnset":2,"fever":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["sharplyDemarcatedBorder","rapidlySpreadingErythema"],"supportive":["lymphadenopathy","subacuteOnset"],"negative":["fever","toxicAppearing"]},"rationale":"Donovanosis presents as a chronic, painless, beefy-red ulcerogranulomatous genital ulcer with a raised, well-demarcated border that bleeds easily, and notably lacks tender inguinal lymphadenopathy or systemic toxicity/fever, which helps distinguish it from chancroid and other ulcerative STIs; no vocabulary key exists for the classic beefy-red bleeding ulcer itself, limiting precise discriminative "},{"id":"ectoparasite_infestations_and_arthropod_in","name":"Ectoparasite Infestations and Arthropod Injuries","system":"Dermatologic / Skin and Soft Tissue (with neurologic and systemic envenomation involvement)","class":"infective","find":{"rash":6,"skinErythema":6,"purulentDrainage":6,"ascendingWeakness":6,"severePain":6,"lymphadenopathy":2,"skinWarmth":2,"fever":2,"myalgiaArthralgia":2,"petechialRash":-6,"jointSwelling":-6},"tiers":{"pathognomonic":[],"discriminative":["rash","skinErythema","purulentDrainage","ascendingWeakness","severePain"],"supportive":["lymphadenopathy","skinWarmth","fever","myalgiaArthralgia"],"negative":["petechialRash","jointSwelling"]},"rationale":"Ectoparasite infestations and arthropod injuries are diagnosed primarily by exposure history and skin exam (burrows, bite reactions, erythema, local pain/swelling) rather than by systemic findings; ascending flaccid weakness after tick exposure is a distinctive red-flag pattern (tick paralysis), while systemic/rheumatologic signs like petechial rash or true joint swelling argue for alternative dia"},{"id":"enterococcal_infections","name":"Enterococcal Infections","system":"Infectious Diseases (multisystem)","class":"infective","find":{"newMurmur":6,"prostheticValve":6,"persistentBacteremia":6,"longTermCatheter":6,"indwellingCatheter":6,"centralLine":6,"fever":2,"rigors":2,"dysuria":2,"urinaryFrequency":2,"feverGU":2,"embolicPhenomena":2,"nursingHomeResident":2,"immunocompromised":2,"tonsillarExudate":-6,"coryza":-6,"doubleSickening":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","prostheticValve","persistentBacteremia","longTermCatheter","indwellingCatheter","centralLine"],"supportive":["fever","rigors","dysuria","urinaryFrequency","feverGU","embolicPhenomena","nursingHomeResident","immunocompromised"],"negative":["tonsillarExudate","coryza","doubleSickening"]},"rationale":"Enterococcal infection is suggested by device- or catheter-associated bacteremia, a new regurgitant murmur or embolic phenomena signaling endocarditis (especially with a prosthetic valve), and healthcare-associated urinary or line sources; no single finding is pathognomonic since presentations overlap with staphylococcal and streptococcal device infections."},{"id":"enterovirus_parechovirus_and_reovirus_infe","name":"Enterovirus, Parechovirus, and Reovirus Infections","system":"Multisystem / Infectious Disease (neurologic, cardiac, mucocutaneous)","class":"infective","find":{"neckStiffness":6,"headacheSevere":6,"photophobia":6,"alteredSensorium":6,"rash":6,"fever":2,"soreThroat":2,"myalgiaArthralgia":2,"diarrhea":2,"nauseaVomiting":2,"lymphadenopathy":2,"petechialRash":-6,"focalNeuroDeficit":-6},"tiers":{"pathognomonic":[],"discriminative":["neckStiffness","headacheSevere","photophobia","alteredSensorium","rash"],"supportive":["fever","soreThroat","myalgiaArthralgia","diarrhea","nauseaVomiting","lymphadenopathy"],"negative":["petechialRash","focalNeuroDeficit"]},"rationale":"Enteroviral/parechovirus infections most often present as aseptic meningitis (neck stiffness, headache, photophobia, altered sensorium) with a nonspecific febrile viral prodrome and mucocutaneous rash, distinguishing it from bacterial causes; presence of petechial rash or a focal neurologic deficit should raise concern for bacterial meningitis or an alternative process rather than typical enterovi"},{"id":"familial_mediterranean_fever_and_other","name":"Familial Mediterranean Fever and Other Hereditary Autoinflammatory Diseases","system":"Immune-mediated / Rheumatologic","class":"non_infective","find":{"severeAbdominalPain":6,"abdominalPain":6,"jointSwelling":6,"severePain":6,"skinErythema":6,"prolongedFever":6,"fever":2,"abdominalDistension":2,"pleuriticChestPain":2,"myalgiaArthralgia":2,"polyarthralgia":2,"rash":2,"proteinuria":2,"prolongedFeverUnexplained":-6,"ascites":-6},"tiers":{"pathognomonic":[],"discriminative":["severeAbdominalPain","abdominalPain","jointSwelling","severePain","skinErythema","prolongedFever"],"supportive":["fever","abdominalDistension","pleuriticChestPain","myalgiaArthralgia","polyarthralgia","rash","proteinuria"],"negative":["prolongedFeverUnexplained","ascites"]},"rationale":"FMF presents with short recurrent self-limited attacks of fever with sterile peritonitis (severe abdominal pain), monoarticular joint swelling/effusion, erysipelas-like erythema over the lower leg, and myalgia/arthralgia, typically lasting 24-72 hours; true ascites and unexplained prolonged (>=3 week) fever argue against FMF since attacks are brief and peritoneal fluid is minimal/sterile rather th"},{"id":"fibromyalgia","name":"Fibromyalgia","system":"Musculoskeletal / Rheumatologic","class":"non_infective","find":{"myalgiaArthralgia":6,"subacuteOnset":6,"polyarthralgia":2,"headache":2,"abdominalDiscomfort":2,"fever":-6,"petechialRash":-6,"jointSwelling":-6,"weightLoss":-6},"tiers":{"pathognomonic":[],"discriminative":["myalgiaArthralgia","subacuteOnset"],"supportive":["polyarthralgia","headache","abdominalDiscomfort"],"negative":["fever","petechialRash","jointSwelling","weightLoss"]},"rationale":"Fibromyalgia is a clinical, criteria-based diagnosis of chronic widespread musculoskeletal pain/tenderness without objective inflammatory or systemic findings, so presence of fever, rash, true joint swelling, or weight loss argues for an alternative diagnosis rather than FM."},{"id":"filariasis","name":"Filariasis","system":"Infectious Diseases","class":"infective","find":{"hepatosplenomegaly":6,"lymphadenopathy":6,"legSwellingUnilateral":6,"travelEndemicArea":6,"skinErythema":6,"fever":2,"rigors":2,"myalgiaArthralgia":2,"rash":2,"legSwellingBilateral":2,"chestPain":2,"petechialRash":-6,"bloodyStool":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","lymphadenopathy","legSwellingUnilateral","travelEndemicArea","skinErythema"],"supportive":["fever","rigors","myalgiaArthralgia","rash","legSwellingBilateral","chestPain"],"negative":["petechialRash","bloodyStool"]},"rationale":"Lymphatic filariasis is diagnosed by microscopy/antigen testing rather than bedside signs, but acute adenolymphangitis with retrograde lymphangitis, unilateral limb/genital lymphedema, lymphadenopathy, and travel/residence in an endemic area are the most distinguishing clinical clues versus bacterial cellulitis/lymphangitis mimics."},{"id":"focal_atrial_tachycardia","name":"Focal Atrial Tachycardia","system":"Cardiovascular","class":"non_infective","find":{"palpitations":6,"tachycardia":6,"syncope":2,"chestPain":2,"dyspnea":2,"fever":-6,"hypotension":-6},"tiers":{"pathognomonic":[],"discriminative":["palpitations","tachycardia"],"supportive":["syncope","chestPain","dyspnea"],"negative":["fever","hypotension"]},"rationale":"Focal AT is fundamentally an ECG diagnosis (discrete P-wave morphology, warm-up/cool-down, persistence despite AV block) rather than a bedside-findings diagnosis; palpitations with tachycardia are the main clinical clues, while overt sepsis-type findings argue against a primary arrhythmic etiology."},{"id":"frontotemporal_dementia","name":"Frontotemporal Dementia","system":"Neurology","class":"non_infective","find":{"behavioralChange":6,"ataxia":2,"focalNeuroDeficit":2,"fever":-6,"alteredSensorium":-6,"seizure":-6,"neckStiffness":-6},"tiers":{"pathognomonic":[],"discriminative":["behavioralChange"],"supportive":["ataxia","focalNeuroDeficit"],"negative":["fever","alteredSensorium","seizure","neckStiffness"]},"rationale":"FTD presents with insidious behavioral/personality change, disinhibition, or progressive language decline in a middle-aged adult with relatively preserved memory, and lacks acute infectious/meningeal or systemic features; presence of fever, neck stiffness, seizure, or acute altered sensorium argues against a primary neurodegenerative process."},{"id":"gallbladder_disease","name":"Gallbladder & Biliary Tract Disease","system":"Hepatobiliary","class":"non_infective","find":{"rightUpperQuadrantPain":6,"murphySign":6,"jaundice":6,"abdominalPain":2,"nauseaVomiting":2,"fever":2,"abdominalDiscomfort":2,"diarrhea":-6,"bloodyStool":-6},"tiers":{"pathognomonic":[],"discriminative":["rightUpperQuadrantPain","murphySign","jaundice"],"supportive":["abdominalPain","nauseaVomiting","fever","abdominalDiscomfort"],"negative":["diarrhea","bloodyStool"]},"rationale":"Gallbladder disease presents with steady right upper quadrant pain and a positive Murphy sign, with jaundice and fever/rigors signaling complications like cholangitis or cholecystitis; diarrhea and bloody stool point away toward a GI/enteric process instead."},{"id":"gas_gangrene","name":"Gas Gangrene (Clostridial Myonecrosis)","system":"Infectious Diseases","class":"infective","find":{"crepitusOrBullae":12,"severePain":6,"rapidlySpreadingErythema":6,"purulentDrainage":6,"skinWarmth":6,"toxicAppearing":6,"fever":2,"tachycardia":2,"hypotension":2,"alteredSensorium":2,"organDysfunction":2,"lactateElevated":2,"sharplyDemarcatedBorder":-6},"tiers":{"pathognomonic":["crepitusOrBullae"],"discriminative":["severePain","rapidlySpreadingErythema","purulentDrainage","skinWarmth","toxicAppearing"],"supportive":["fever","tachycardia","hypotension","alteredSensorium","organDysfunction","lactateElevated"],"negative":["sharplyDemarcatedBorder"]},"rationale":"Gas gangrene is marked by crepitus/hemorrhagic bullae with foul-smelling discharge and pain out of proportion to exam, distinguishing it from mimics like erysipelas that have sharply demarcated borders; systemic toxicity and organ dysfunction are supportive but non-specific."},{"id":"gastrointestinal_neuroendocrine_tumors","name":"Gastrointestinal Neuroendocrine Tumors","system":"Gastrointestinal/Oncology","class":"non_infective","find":{"diarrhea":6,"flankPain":6,"weightLoss":6,"hepatosplenomegaly":6,"abdominalPain":6,"nauseaVomiting":2,"abdominalDistension":2,"dehydration":2,"jaundice":2,"malignancy":2,"palpitations":2,"fever":-6,"petechialRash":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["diarrhea","flankPain","weightLoss","hepatosplenomegaly","abdominalPain"],"supportive":["nauseaVomiting","abdominalDistension","dehydration","jaundice","malignancy","palpitations"],"negative":["fever","petechialRash","toxicAppearing"]},"rationale":"GI NETs (carcinoid syndrome, VIPoma, gastrinoma etc.) are primarily diagnosed via hormone assays (5-HIAA, gastrin, VIP) and somatostatin-receptor imaging/biopsy rather than bedside findings, but chronic secretory diarrhea, weight loss, abdominal pain, and hepatic (metastatic) involvement are the closest recognizable clinical clues; acute infectious-type findings argue against this indolent oncolog"},{"id":"glomerular_diseases","name":"Glomerular Diseases (Spectrum)","system":"Nephrology","class":"non_infective","find":{"hematuria":6,"proteinuria":6,"legSwellingBilateral":6,"hypertensionHx":6,"oliguria":6,"renalImpairment":6,"darkUrine":2,"dyspnea":2,"headacheSevere":2,"facialSwelling":2,"dysuria":-6,"flankPain":-6,"complicatedUTIRisk":-6},"tiers":{"pathognomonic":[],"discriminative":["hematuria","proteinuria","legSwellingBilateral","hypertensionHx","oliguria","renalImpairment"],"supportive":["darkUrine","dyspnea","headacheSevere","facialSwelling"],"negative":["dysuria","flankPain","complicatedUTIRisk"]},"rationale":"Glomerular diseases classically present with the nephritic/nephrotic spectrum: hematuria and heavy proteinuria plus bilateral edema, hypertension, oliguria and rising creatinine, whereas dysuria, flank pain and typical UTI features argue for a lower-urinary-tract or pyelonephritic process instead."},{"id":"glycogen_storage_diseases_and_other","name":"Glycogen Storage Diseases and Other Inherited Disorders of Carbohydrate Metabolism","system":"Endocrine/Metabolic","class":"non_infective","find":{"hepatosplenomegaly":6,"ketonemia":6,"abdominalDistension":2,"weightLoss":2,"jaundice":2,"nauseaVomiting":2,"dehydration":2,"petechialRash":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","ketonemia"],"supportive":["abdominalDistension","weightLoss","jaundice","nauseaVomiting","dehydration"],"negative":["petechialRash","toxicAppearing"]},"rationale":"Glycogen storage diseases classically present with hepatomegaly/hepatosplenomegaly and fasting hypoglycemia with abnormal ketosis (hypoketotic in GSD I, ketotic in GSD III), but definitive diagnosis requires enzyme/genetic testing rather than bedside findings alone."},{"id":"gonorrhea","name":"Gonorrhea","system":"Infectious Diseases","class":"infective","find":{"dysuria":6,"urinaryFrequency":6,"tonsillarExudate":6,"jointSwelling":6,"polyarthralgia":6,"rash":6,"fever":2,"perinealPain":2,"abdominalPain":2,"lymphadenopathy":2,"myalgiaArthralgia":2,"diarrhea":-6,"cough":-6,"photophobia":-6},"tiers":{"pathognomonic":[],"discriminative":["dysuria","urinaryFrequency","tonsillarExudate","jointSwelling","polyarthralgia","rash"],"supportive":["fever","perinealPain","abdominalPain","lymphadenopathy","myalgiaArthralgia"],"negative":["diarrhea","cough","photophobia"]},"rationale":"Gonorrhea presents with urethritis/cervicitis (dysuria, discharge-related urinary frequency) or pharyngeal/anorectal infection, and disseminated infection classically causes an arthritis-dermatitis syndrome (joint swelling, polyarthralgia, rash); no single bedside finding is truly pathognomonic since urethral discharge and Gram-stain findings are not in the vocabulary."},{"id":"gout_and_other_crystal_associated","name":"Gout and Other Crystal-Associated Arthropathies","system":"Musculoskeletal / Rheumatologic","class":"non_infective","find":{"jointSwelling":6,"skinErythema":6,"skinWarmth":6,"severePain":6,"fever":2,"polyarthralgia":2,"myalgiaArthralgia":2,"toxicAppearing":-6,"hypotension":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["jointSwelling","skinErythema","skinWarmth","severePain"],"supportive":["fever","polyarthralgia","myalgiaArthralgia"],"negative":["toxicAppearing","hypotension","petechialRash"]},"rationale":"Gout/crystal arthropathy presents as an acutely hot, red, swollen, exquisitely tender joint (often mimicking cellulitis) that can be mistaken for septic arthritis; definitive diagnosis requires synovial fluid crystal analysis which is not part of the bedside vocabulary, so no pathognomonic finding-signature key exists. Systemic toxicity/hypotension/petechiae would argue for sepsis or another proce"},{"id":"gynecologic_malignancies","name":"Gynecologic Malignancies","system":"Reproductive (Female Genital Tract)","class":"non_infective","find":{"abdominalDistension":6,"ascites":6,"weightLoss":6,"abdominalPain":2,"abdominalDiscomfort":2,"nauseaVomiting":2,"urinaryFrequency":2,"malignancy":2,"flankPain":2,"fever":-6,"rigors":-6,"pregnancy":-6},"tiers":{"pathognomonic":[],"discriminative":["abdominalDistension","ascites","weightLoss"],"supportive":["abdominalPain","abdominalDiscomfort","nauseaVomiting","urinaryFrequency","malignancy","flankPain"],"negative":["fever","rigors","pregnancy"]},"rationale":"Gynecologic malignancies (ovarian, cervical, endometrial) are largely diagnosed by imaging, tumor markers, and biopsy rather than bedside findings, but new ascites with abdominal distension and unintentional weight loss are the closest available discriminative clues to advanced disease; acute infectious signs like fever/rigors argue against a purely malignant process and favor a mimic such as tubo"},{"id":"haemophilus_and_moraxella_infections","name":"Haemophilus and Moraxella Infections","system":"Respiratory / Infectious Diseases","class":"infective","find":{"knownCOPD":6,"increasedDyspnea":6,"increasedSputumVolume":6,"purulentSputum":6,"neckStiffness":6,"fever":2,"cough":2,"purulentNasalDischarge":2,"crepitations":2,"consolidation":2,"tenderCervicalNodes":2,"ruralExposure":-6,"eschar":-6,"travelEndemicArea":-6},"tiers":{"pathognomonic":[],"discriminative":["knownCOPD","increasedDyspnea","increasedSputumVolume","purulentSputum","neckStiffness"],"supportive":["fever","cough","purulentNasalDischarge","crepitations","consolidation","tenderCervicalNodes"],"negative":["ruralExposure","eschar","travelEndemicArea"]},"rationale":"H. influenzae/Moraxella most classically cause COPD exacerbations (increased dyspnea/sputum volume/purulence) and otitis/sinusitis/pneumonia with nonspecific respiratory findings, while confirmation requires culture/Gram stain rather than a specific bedside sign; findings of vector-borne/tropical exposure argue against this diagnosis."},{"id":"heart_failure_management","name":"Heart Failure: Management","system":"Cardiovascular","class":"non_infective","find":{"raisedJVP":6,"orthopnea":6,"bilateralCrackles":6,"legSwellingBilateral":6,"knownHeartFailure":6,"dyspnea":2,"tachycardia":2,"hypoxia":2,"hepatosplenomegaly":2,"ascites":2,"jaundice":2,"atrialFibHx":2,"hypertensionHx":2,"pleuriticChestPain":-6,"purulentSputum":-6,"consolidation":-6},"tiers":{"pathognomonic":[],"discriminative":["raisedJVP","orthopnea","bilateralCrackles","legSwellingBilateral","knownHeartFailure"],"supportive":["dyspnea","tachycardia","hypoxia","hepatosplenomegaly","ascites","jaundice","atrialFibHx","hypertensionHx"],"negative":["pleuriticChestPain","purulentSputum","consolidation"]},"rationale":"Heart failure is best identified by congestive signs such as raised JVP, orthopnea, bilateral basal crackles, and bilateral leg edema in a patient with known heart failure or predisposing cardiac disease, while findings pointing to a primary pulmonary infection (pleuritic pain, purulent sputum, consolidation) argue against it."},{"id":"heart_failure_pathophysiology_and_diagnosi","name":"Heart Failure: Pathophysiology and Diagnosis","system":"Cardiovascular","class":"non_infective","find":{"orthopnea":6,"raisedJVP":6,"bilateralCrackles":6,"legSwellingBilateral":6,"knownHeartFailure":6,"dyspnea":2,"tachycardia":2,"tachypnea":2,"hypoxia":2,"chestPain":2,"atrialFibHx":2,"knownCAD":2,"hypertensionHx":2,"calfTenderness":-6,"legSwellingUnilateral":-6},"tiers":{"pathognomonic":[],"discriminative":["orthopnea","raisedJVP","bilateralCrackles","legSwellingBilateral","knownHeartFailure"],"supportive":["dyspnea","tachycardia","tachypnea","hypoxia","chestPain","atrialFibHx","knownCAD","hypertensionHx"],"negative":["calfTenderness","legSwellingUnilateral"]},"rationale":"Orthopnea, raised JVP with edema, bilateral basal crackles, bilateral leg swelling, and known HF history are relatively discriminative bedside clues for heart failure, while dyspnea/tachycardia/hypoxia are supportive but non-specific; unilateral leg swelling/calf tenderness point away toward DVT rather than HF."},{"id":"heat_related_illnesses","name":"Heat-Related Illnesses","system":"Environmental/Thermoregulatory","class":"non_infective","find":{"alteredSensorium":6,"seizure":6,"rigidity":6,"hypotension":6,"tachypnea":6,"tachycardia":2,"organDysfunction":2,"lactateElevated":2,"toxicAppearing":2,"dehydration":2,"oliguria":2,"neckStiffness":-6,"photophobia":-6,"petechialRash":-6,"travelEndemicArea":-6},"tiers":{"pathognomonic":[],"discriminative":["alteredSensorium","seizure","rigidity","hypotension","tachypnea"],"supportive":["tachycardia","organDysfunction","lactateElevated","toxicAppearing","dehydration","oliguria"],"negative":["neckStiffness","photophobia","petechialRash","travelEndemicArea"]},"rationale":"Heatstroke is best identified by CNS dysfunction (altered sensorium, seizure) with hyperthermia and organ dysfunction/hypotension in the setting of heat exposure, since no single vocabulary key captures core temperature or anhidrosis; meningismus and rash/travel findings point toward infectious mimics (meningitis, malaria) rather than heat illness."},{"id":"heavy_metal_poisoning","name":"Heavy Metal Poisoning","system":"Toxicology / Environmental Medicine","class":"non_infective","find":{"ascendingWeakness":6,"abdominalPain":6,"hematemesis":6,"alteredSensorium":6,"seizure":6,"nauseaVomiting":2,"diarrhea":2,"hypotension":2,"renalImpairment":2,"dehydration":2,"headache":2,"prolongedFeverUnexplained":-6,"roseSpots":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["ascendingWeakness","abdominalPain","hematemesis","alteredSensorium","seizure"],"supportive":["nauseaVomiting","diarrhea","hypotension","renalImpairment","dehydration","headache"],"negative":["prolongedFeverUnexplained","roseSpots","petechialRash"]},"rationale":"Heavy metal poisoning lacks a single pathognomonic bedside finding within this vocabulary (garlicky breath, Mees' lines, gum lead-lines are not listed keys), but the combination of severe abdominal pain with hematemesis/hemorrhagic gastroenteritis, ascending peripheral neuropathy (weakness), altered sensorium/seizure (encephalopathy), and renal impairment in a toxic-exposure context is discriminat"},{"id":"hemolytic_anemia","name":"Hemolytic Anemia","system":"Haematology","class":"non_infective","find":{"jaundice":6,"darkUrine":6,"hepatosplenomegaly":6,"splenomegaly":6,"fever":2,"hematuria":2,"melena":-6,"gibPresentation":-6},"tiers":{"pathognomonic":[],"discriminative":["jaundice","darkUrine","hepatosplenomegaly","splenomegaly"],"supportive":["fever","hematuria"],"negative":["melena","gibPresentation"]},"rationale":"Hemolytic anemia classically presents with jaundice, dark urine (hemoglobinuria), and splenomegaly/hepatosplenomegaly from increased extravascular red-cell destruction, while overt GI bleeding sources argue against a hemolytic mechanism for anemia."},{"id":"herpes_simplex","name":"Herpes Simplex Virus Infection","system":"Infectious Diseases","class":"infective","find":{"mucosalLesions":6,"tenderCervicalNodes":6,"focalNeuroDeficit":6,"seizure":6,"behavioralChange":6,"fever":2,"headache":2,"alteredSensorium":2,"lymphadenopathy":2,"rash":2,"immunocompromised":2},"tiers":{"pathognomonic":[],"discriminative":["mucosalLesions","tenderCervicalNodes","focalNeuroDeficit","seizure","behavioralChange"],"supportive":["fever","headache","alteredSensorium","lymphadenopathy","rash","immunocompromised"],"negative":[]},"rationale":"HSV is diagnosed by characteristic grouped vesicular/ulcerative mucocutaneous lesions and, in encephalitis, fever with altered sensorium, focal neurologic deficits, seizures, or behavioral change reflecting temporal-lobe involvement; no single bedside finding is fully pathognomonic since VZV can mimic the skin lesions."},{"id":"histoplasmosis","name":"Histoplasmosis","system":"Infectious Diseases","class":"infective","find":{"prolongedCough2Weeks":6,"nightSweats":6,"weightLoss":6,"cavitatingLesion":6,"immunocompromised":6,"hepatosplenomegaly":6,"fever":2,"dyspnea":2,"chestPain":2,"lymphadenopathy":2,"hemoptysis":2,"myalgiaArthralgia":2,"rash":2},"tiers":{"pathognomonic":[],"discriminative":["prolongedCough2Weeks","nightSweats","weightLoss","cavitatingLesion","immunocompromised","hepatosplenomegaly"],"supportive":["fever","dyspnea","chestPain","lymphadenopathy","hemoptysis","myalgiaArthralgia","rash"],"negative":[]},"rationale":"Histoplasmosis lacks a truly pathognomonic bedside finding, but chronic cavitary disease with prolonged cough, night sweats, weight loss and upper-lobe cavitation in a smoker (mimicking TB) plus disseminated disease with hepatosplenomegaly in an immunocompromised host are strongly discriminative; fever, dyspnea, chest pain, lymphadenopathy and arthralgia/rash (erythema nodosum reaction) are suppor"},{"id":"hiv_aids","name":"HIV/AIDS","system":"Infectious Diseases","class":"infective","find":{"lymphadenopathy":6,"maculopapularRash":6,"soreThroat":6,"weightLoss":6,"immunocompromised":6,"fever":2,"headache":2,"myalgiaArthralgia":2,"rash":2,"prolongedFever":2,"hepatosplenomegaly":2},"tiers":{"pathognomonic":[],"discriminative":["lymphadenopathy","maculopapularRash","soreThroat","weightLoss","immunocompromised"],"supportive":["fever","headache","myalgiaArthralgia","rash","prolongedFever","hepatosplenomegaly"],"negative":[]},"rationale":"Acute HIV presents as a nonspecific mononucleosis-like syndrome (fever, sore throat, lymphadenopathy, rash, myalgias) with no pathognomonic bedside sign; definitive diagnosis requires HIV Ag/Ab or viral load testing rather than clinical findings alone."},{"id":"HLH","name":"Hemophagocytic Lymphohistiocytosis (HLH)","system":"Hematology / Immunology","class":"non_infective","find":{"hepatosplenomegaly":6,"thrombocytopenia":6,"malignancy":6,"immunocompromised":6,"fever":2,"prolongedFever":2,"prolongedFeverUnexplained":2,"hemoglobin":2,"platelets":2,"bilirubin":2,"lymphadenopathy":2,"jaundice":2,"clinicallyImproving":-6,"afebrile24h":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","thrombocytopenia","malignancy","immunocompromised"],"supportive":["fever","prolongedFever","prolongedFeverUnexplained","hemoglobin","platelets","bilirubin","lymphadenopathy","jaundice"],"negative":["clinicallyImproving","afebrile24h"]},"rationale":"HLH presents as unremitting fever with hepatosplenomegaly and progressive multi-lineage cytopenias (especially thrombocytopenia) that fail to respond to antibiotics, often in an immunocompromised or malignancy-associated host; no single bedside finding is pathognomonic, and definitive diagnosis relies on ferritin, triglycerides, fibrinogen and marrow findings not present in this vocabulary."},{"id":"hodgkin_lymphoma","name":"Hodgkin's Lymphoma","system":"Oncology / Hematology","class":"non_infective","find":{"lymphadenopathy":6,"nightSweats":6,"weightLoss":6,"hepatosplenomegaly":6,"prolongedFeverUnexplained":6,"fever":2,"prolongedFever":2,"eveningFever":2,"malignancy":2,"subacuteOnset":2,"tonsillarExudate":-6,"soreThroat":-6},"tiers":{"pathognomonic":[],"discriminative":["lymphadenopathy","nightSweats","weightLoss","hepatosplenomegaly","prolongedFeverUnexplained"],"supportive":["fever","prolongedFever","eveningFever","malignancy","subacuteOnset"],"negative":["tonsillarExudate","soreThroat"]},"rationale":"Hodgkin lymphoma classically presents with nontender lymphadenopathy (neck/supraclavicular/axilla) plus B symptoms (fever, night sweats, weight loss), sometimes with hepatosplenomegaly or fever of unknown origin; it is ultimately a biopsy-confirmed diagnosis so no bedside finding is pathognomonic, and prominent pharyngitis/tonsillar exudate points instead toward infectious mononucleosis, a key mim"},{"id":"hyperthyroidism_and_other_causes_of","name":"Hyperthyroidism and Other Causes of Thyrotoxicosis","system":"Endocrine","class":"non_infective","find":{"weightLoss":6,"palpitations":6,"diarrhea":6,"atrialFibHx":6,"tachycardia":2,"fever":2,"alteredSensorium":2,"seizure":2,"jaundice":2,"nauseaVomiting":2,"hypothermia":-6,"bradycardia":-6},"tiers":{"pathognomonic":[],"discriminative":["weightLoss","palpitations","diarrhea","atrialFibHx"],"supportive":["tachycardia","fever","alteredSensorium","seizure","jaundice","nauseaVomiting"],"negative":["hypothermia","bradycardia"]},"rationale":"Hyperthyroidism/thyrotoxicosis is suggested by unintentional weight loss with palpitations, tachycardia, diarrhea and new atrial fibrillation, with thyroid storm marked by fever, altered sensorium and seizure; hypothermia or bradycardia would argue against it."},{"id":"hypothermia_and_peripheral_cold_injuries","name":"Hypothermia and Peripheral Cold Injuries","system":"Environmental / Multisystem","class":"non_infective","find":{"hypothermia":6,"bradycardia":6,"bradypnea":6,"alteredSensorium":6,"crepitusOrBullae":6,"ataxia":2,"alcoholExcess":2,"headInjury":2,"fever":-6,"rigors":-6,"tachycardia":-6},"tiers":{"pathognomonic":[],"discriminative":["hypothermia","bradycardia","bradypnea","alteredSensorium","crepitusOrBullae"],"supportive":["ataxia","alcoholExcess","headInjury"],"negative":["fever","rigors","tachycardia"]},"rationale":"Hypothermia (core temp <35C) with associated bradycardia, depressed respiration, and altered mental status is the defining picture, while frostbite adds hemorrhagic bullae/crepitus over affected tissue; fever and tachycardia argue against primary hypothermia."},{"id":"hypothyroidism","name":"Hypothyroidism","system":"Endocrine","class":"non_infective","find":{"bradycardia":6,"hypothermia":6,"alteredSensorium":6,"legSwellingBilateral":2,"constipationOrDiarrhea":2,"bradypnea":2,"fever":-6,"tachycardia":-6},"tiers":{"pathognomonic":[],"discriminative":["bradycardia","hypothermia","alteredSensorium"],"supportive":["legSwellingBilateral","constipationOrDiarrhea","bradypnea"],"negative":["fever","tachycardia"]},"rationale":"The available vocabulary is sepsis/acute-infection oriented and lacks hypothyroidism-specific terms (myxedema, cold intolerance, dry skin, goiter); only proxy findings like bradycardia, hypothermia, and altered sensorium (severe myxedema coma) are usable, while fever and tachycardia argue against it."},{"id":"igg4_related_disease","name":"IgG4-Related Disease","system":"Immune-Mediated / Multisystem (Rheumatology)","class":"non_infective","find":{"jaundice":6,"facialSwelling":6,"lymphadenopathy":6,"weightLoss":6,"abdominalPain":2,"hepatosplenomegaly":2,"subacuteOnset":2,"backPain":2,"asterixis":2,"fever":-6,"toxicAppearing":-6,"petechialRash":-6,"hypotension":-6},"tiers":{"pathognomonic":[],"discriminative":["jaundice","facialSwelling","lymphadenopathy","weightLoss"],"supportive":["abdominalPain","hepatosplenomegaly","subacuteOnset","backPain","asterixis"],"negative":["fever","toxicAppearing","petechialRash","hypotension"]},"rationale":"IgG4-RD lacks a single bedside pathognomonic sign; tumefactive salivary/lacrimal (facial) swelling, painless obstructive jaundice from pancreatobiliary involvement, lymphadenopathy, and weight loss are the most discriminative clinical clues, while true diagnosis rests on serum IgG4, imaging, and biopsy. Presence of high fever, toxic appearance, or petechial rash argues against this indolent fibroi"},{"id":"infections_acquired_in_health_care","name":"Infections Acquired in Health Care Facilities","system":"Infectious Disease / Hospital Epidemiology","class":"infective","find":{"hospitalDay48":6,"centralLine":6,"indwellingCatheter":6,"longTermCatheter":6,"mechanicalVentilation":6,"hospitalizationLast90Days":6,"fever":2,"antibioticsLast90Days":2,"immunocompromised":2,"erythemaAtSite":2,"purulentDrainage":2,"purulentSecretions":2,"diarrhea":2,"afebrile24h":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["hospitalDay48","centralLine","indwellingCatheter","longTermCatheter","mechanicalVentilation","hospitalizationLast90Days"],"supportive":["fever","antibioticsLast90Days","immunocompromised","erythemaAtSite","purulentDrainage","purulentSecretions","diarrhea"],"negative":["afebrile24h","clinicallyImproving"]},"rationale":"Health care-associated infection is defined largely by timing/context (onset >48h after admission) and device/exposure risk factors (central line, urinary catheter, ventilator, recent hospitalization/ICU stay, prior antibiotics) rather than a specific clinical syndrome, so findings are mostly contextual/device-related plus nonspecific infectious signs."},{"id":"infections_due_to_campylobacter_and","name":"Infections Due to Campylobacter and Related Organisms","system":"Gastrointestinal","class":"infective","find":{"bloodyStool":6,"contaminatedFoodWaterExposure":6,"severeAbdominalPain":6,"tenesmus":6,"diarrhea":2,"abdominalPain":2,"fever":2,"nauseaVomiting":2,"myalgiaArthralgia":2,"dehydration":2,"prolongedFeverUnexplained":-6,"roseSpots":-6},"tiers":{"pathognomonic":[],"discriminative":["bloodyStool","contaminatedFoodWaterExposure","severeAbdominalPain","tenesmus"],"supportive":["diarrhea","abdominalPain","fever","nauseaVomiting","myalgiaArthralgia","dehydration"],"negative":["prolongedFeverUnexplained","roseSpots"]},"rationale":"Campylobacter enteritis presents with acute diarrhea (often bloody), cramping abdominal pain, tenesmus, and fever following contaminated food/water exposure; findings overlap substantially with other bacterial enteritides so no truly pathognomonic key exists, while prolonged unexplained fever and rose spots point instead toward typhoid fever."},{"id":"infections_due_to_mixed_anaerobic","name":"Infections Due to Mixed Anaerobic Organisms","system":"Infectious Diseases (multisystem)","class":"infective","find":{"foulSmellingSputum":6,"cavitatingLesion":6,"crepitusOrBullae":6,"rapidlySpreadingErythema":6,"aspirationRiskFactor":6,"dysphagia":6,"fever":2,"toxicAppearing":2,"purulentSputum":2,"purulentDrainage":2,"abdominalPain":2,"severeAbdominalPain":2,"consolidation":2,"pleuriticPain":2},"tiers":{"pathognomonic":[],"discriminative":["foulSmellingSputum","cavitatingLesion","crepitusOrBullae","rapidlySpreadingErythema","aspirationRiskFactor","dysphagia"],"supportive":["fever","toxicAppearing","purulentSputum","purulentDrainage","abdominalPain","severeAbdominalPain","consolidation","pleuriticPain"],"negative":[]},"rationale":"Mixed anaerobic infection is best signaled by foul-smelling discharge/sputum, cavitating lung lesions, aspiration risk, and soft-tissue crepitus/bullae or rapidly spreading erythema seen in synergistic necrotizing infections; general septic/inflammatory findings are supportive but nonspecific and no single bedside finding is truly pathognomonic."},{"id":"infections_due_to_pseudomonas_burkholderia","name":"Infections Due to Pseudomonas, Burkholderia, and Stenotrophomonas Species","system":"Multisystem / Infectious Diseases","class":"infective","find":{"eschar":12,"immunocompromised":6,"neutropenia":6,"mechanicalVentilation":6,"purulentSecretions":6,"longTermCatheter":6,"mdrRisk":6,"fever":2,"hypotension":2,"toxicAppearing":2,"hospitalizationLast90Days":2,"icuStay":2,"antibioticsLast90Days":2,"purulentSputum":2,"hemoptysis":2,"oralIntakeAdequate":-6,"clinicallyImproving":-6,"afebrile24h":-6},"tiers":{"pathognomonic":["eschar"],"discriminative":["immunocompromised","neutropenia","mechanicalVentilation","purulentSecretions","longTermCatheter","mdrRisk"],"supportive":["fever","hypotension","toxicAppearing","hospitalizationLast90Days","icuStay","antibioticsLast90Days","purulentSputum","hemoptysis"],"negative":["oralIntakeAdequate","clinicallyImproving","afebrile24h"]},"rationale":"Pseudomonas/Burkholderia infections are opportunistic, clustering in immunocompromised, neutropenic, ventilated, or catheterized/ICU patients with prior antibiotic exposure; the eschar (as in ecthyma gangrenosum) is the closest available near-pathognomonic marker, while most other findings (fever, purulent secretions, cavitation) are supportive but shared with other gram-negative infections."},{"id":"infections_due_to_the_hacek","name":"Infections Due to the HACEK Group and Miscellaneous Gram-Negative Bacteria","system":"Infectious Diseases (cardiovascular/systemic)","class":"infective","find":{"newMurmur":6,"embolicPhenomena":6,"prostheticValve":6,"persistentBacteremia":6,"subacuteOnset":6,"fever":2,"prolongedFever":2,"weightLoss":2,"hepatosplenomegaly":2,"myalgiaArthralgia":2,"petechialRash":2,"focalNeuroDeficit":2,"dysphagia":2,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","embolicPhenomena","prostheticValve","persistentBacteremia","subacuteOnset"],"supportive":["fever","prolongedFever","weightLoss","hepatosplenomegaly","myalgiaArthralgia","petechialRash","focalNeuroDeficit","dysphagia"],"negative":["toxicAppearing"]},"rationale":"HACEK infections classically present as subacute, culture-positive endocarditis in a patient with a prosthetic or damaged valve, often after a dental procedure, with a new regurgitant murmur, persistent bacteremia, and prominent embolic/vascular-immunologic phenomena; acute toxic presentation argues against the typically indolent HACEK course."},{"id":"infections_of_the_skin_muscles","name":"Infections of the Skin, Muscles, and Soft Tissues","system":"Skin / Soft Tissue / Musculoskeletal (Infectious Diseases)","class":"infective","find":{"crepitusOrBullae":12,"severePain":6,"rapidlySpreadingErythema":6,"skinErythema":6,"skinWarmth":6,"purulentDrainage":6,"deepTissueInvolvement":6,"fever":2,"toxicAppearing":2,"organDysfunction":2,"boneInvolvement":2,"peripheralVascularDisease":2,"lymphadenopathy":2,"sharplyDemarcatedBorder":2},"tiers":{"pathognomonic":["crepitusOrBullae"],"discriminative":["severePain","rapidlySpreadingErythema","skinErythema","skinWarmth","purulentDrainage","deepTissueInvolvement"],"supportive":["fever","toxicAppearing","organDysfunction","boneInvolvement","peripheralVascularDisease","lymphadenopathy","sharplyDemarcatedBorder"],"negative":[]},"rationale":"Necrotizing/deep soft-tissue infection is suggested by pain out of proportion to exam plus crepitus or hemorrhagic bullae (near-pathognomonic for necrotizing fasciitis/myonecrosis), while rapidly spreading erythema, warmth, purulent drainage and deep tissue involvement support simpler cellulitis/abscess along the same anatomic spectrum; sharply demarcated raised borders are more typical of erysipe"},{"id":"infectious_arthritis","name":"Infectious Arthritis","system":"Musculoskeletal","class":"infective","find":{"jointSwelling":6,"purulentDrainage":6,"severePain":6,"boneInvolvement":6,"ivDrugUse":6,"fever":2,"rigors":2,"skinErythema":2,"skinWarmth":2,"polyarthralgia":2,"myalgiaArthralgia":2,"immunocompromised":2,"symmetricSmallJointInvolvement":-6,"rash":-6},"tiers":{"pathognomonic":[],"discriminative":["jointSwelling","purulentDrainage","severePain","boneInvolvement","ivDrugUse"],"supportive":["fever","rigors","skinErythema","skinWarmth","polyarthralgia","myalgiaArthralgia","immunocompromised"],"negative":["symmetricSmallJointInvolvement","rash"]},"rationale":"Infectious/septic arthritis is best signaled by an acutely hot, swollen, painful joint (often mono/oligoarticular) with purulent drainage or suspected bone involvement, supported by fever/rigors and risk factors like IV drug use or immunocompromise; symmetric small-joint polyarthritis or a prominent rash pattern points more toward reactive/gonococcal-dermatitis or rheumatoid mimics."},{"id":"infectious_complications_of_bites","name":"Infectious Complications of Bites","system":"Skin and Soft Tissue / Infectious Disease","class":"infective","find":{"purulentDrainage":6,"rapidlySpreadingErythema":6,"boneInvolvement":6,"jointSwelling":6,"deepTissueInvolvement":6,"fever":2,"skinErythema":2,"skinWarmth":2,"lymphadenopathy":2,"severePain":2,"immunocompromised":2},"tiers":{"pathognomonic":[],"discriminative":["purulentDrainage","rapidlySpreadingErythema","boneInvolvement","jointSwelling","deepTissueInvolvement"],"supportive":["fever","skinErythema","skinWarmth","lymphadenopathy","severePain","immunocompromised"],"negative":[]},"rationale":"Bite infections present with local wound cellulitis/purulent discharge, often rapidly spreading (Pasteurella) or with joint/bone involvement from deep puncture wounds (cat bites, fight bites); systemic sepsis/DIC (Capnocytophaga) occurs mainly in asplenic or immunocompromised hosts after dog bites."},{"id":"infectious_mononucleosis","name":"Infectious Mononucleosis (EBV)","system":"Infectious Diseases","class":"infective","find":{"tenderCervicalNodes":6,"tonsillarExudate":6,"hepatosplenomegaly":6,"splenomegaly":6,"lymphadenopathy":6,"fever":2,"soreThroat":2,"weightLoss":2,"rash":2,"abdominalPain":2,"purulentNasalDischarge":-6,"dysuria":-6},"tiers":{"pathognomonic":[],"discriminative":["tenderCervicalNodes","tonsillarExudate","hepatosplenomegaly","splenomegaly","lymphadenopathy"],"supportive":["fever","soreThroat","weightLoss","rash","abdominalPain"],"negative":["purulentNasalDischarge","dysuria"]},"rationale":"IM classically presents with the triad of fever, sore throat with tonsillar exudate, and tender (often posterior cervical) lymphadenopathy, plus splenomegaly/hepatosplenomegaly which is a key discriminator from streptococcal pharyngitis; no single finding is truly pathognomonic since serology/atypical lymphocytes are needed for confirmation."},{"id":"inflammatory_bowel_disease","name":"Inflammatory Bowel Disease","system":"Gastroenterology","class":"non_infective","find":{"bloodyStool":6,"tenesmus":6,"abdominalPain":6,"weightLoss":6,"subacuteOnset":6,"diarrhea":2,"abdominalDistension":2,"fever":2,"dehydration":2,"nauseaVomiting":2,"hepatosplenomegaly":2,"contaminatedFoodWaterExposure":-6,"travelEndemicArea":-6},"tiers":{"pathognomonic":[],"discriminative":["bloodyStool","tenesmus","abdominalPain","weightLoss","subacuteOnset"],"supportive":["diarrhea","abdominalDistension","fever","dehydration","nauseaVomiting","hepatosplenomegaly"],"negative":["contaminatedFoodWaterExposure","travelEndemicArea"]},"rationale":"Chronic bloody diarrhea with tenesmus, abdominal pain, weight loss and a subacute-to-chronic course distinguish IBD from acute infective colitis, though no bedside finding is truly pathognomonic; recent contaminated food/water exposure or travel to an endemic area argue for an infective mimic instead."},{"id":"influenza","name":"Influenza","system":"Infectious Diseases","class":"infective","find":{"coryza":6,"soreThroat":6,"myalgiaArthralgia":6,"cough":6,"nasalCongestion":6,"fever":2,"rigors":2,"headache":2,"hypoxia":2,"purulentSputum":-6,"consolidation":-6,"tonsillarExudate":-6,"bloodyStool":-6},"tiers":{"pathognomonic":[],"discriminative":["coryza","soreThroat","myalgiaArthralgia","cough","nasalCongestion"],"supportive":["fever","rigors","headache","hypoxia"],"negative":["purulentSputum","consolidation","tonsillarExudate","bloodyStool"]},"rationale":"Influenza is a clinical syndrome of abrupt-onset fever with myalgia, headache, sore throat, coryza and cough, none of which are individually pathognomonic; findings suggesting bacterial superinfection or an alternative focal process (purulent sputum, consolidation, exudative pharyngitis, bloody stool) argue against uncomplicated influenza."},{"id":"intestinal_nematode_infections","name":"Intestinal Nematode (Roundworm) Infections","system":"Infectious Diseases","class":"infective","find":{"abdominalPain":6,"dysphagia":6,"nauseaVomiting":6,"cough":6,"weightLoss":6,"diarrhea":2,"abdominalDistension":2,"dehydration":2,"constipationOrDiarrhea":2,"abdominalDiscomfort":2,"severeAbdominalPain":2,"bloodyStool":-6,"tenesmus":-6},"tiers":{"pathognomonic":[],"discriminative":["abdominalPain","dysphagia","nauseaVomiting","cough","weightLoss"],"supportive":["diarrhea","abdominalDistension","dehydration","constipationOrDiarrhea","abdominalDiscomfort","severeAbdominalPain"],"negative":["bloodyStool","tenesmus"]},"rationale":"Intestinal nematode infections are diagnosed largely by exposure history, GI symptoms (abdominal pain, nausea/vomiting, weight loss), a Loffler-like cough during larval lung migration, and stool/serologic testing rather than any single pathognomonic bedside sign; severe bloody diarrhea/tenesmus argue more for other enteric or inflammatory processes."},{"id":"intraabdominal_infections_and_abscesses","name":"Intraabdominal Infections and Abscesses","system":"Gastrointestinal/Abdominal","class":"infective","find":{"severeAbdominalPain":6,"abdominalDistension":6,"ascites":6,"murphySign":6,"rightUpperQuadrantPain":6,"liverDisease":6,"abdominalPain":2,"fever":2,"rigors":2,"nauseaVomiting":2,"toxicAppearing":2,"jaundice":2,"hepatosplenomegaly":2,"organDysfunction":2,"diarrhea":-6,"bloodyStool":-6,"dysuria":-6,"costovertebralTenderness":-6},"tiers":{"pathognomonic":[],"discriminative":["severeAbdominalPain","abdominalDistension","ascites","murphySign","rightUpperQuadrantPain","liverDisease"],"supportive":["abdominalPain","fever","rigors","nauseaVomiting","toxicAppearing","jaundice","hepatosplenomegaly","organDysfunction"],"negative":["diarrhea","bloodyStool","dysuria","costovertebralTenderness"]},"rationale":"Intraabdominal infection/abscess is suggested by severe localized abdominal pain, distension, ascites (especially with liver disease pointing to spontaneous bacterial peritonitis), RUQ pain/Murphy sign for hepatobiliary source, and systemic sepsis features; findings pointing to a urinary or lower-GI source argue against it."},{"id":"iron_deficiency_anemia","name":"Iron Deficiency Anemia","system":"Haematology","class":"non_infective","find":{"melena":6,"gibPresentation":6,"bloodyStool":6,"hematemesis":6,"hematuria":6,"weightLoss":2,"dysphagia":2,"tachycardia":2,"pregnancy":2,"hemoglobin":2,"hepatosplenomegaly":-6,"thrombocytopenia":-6,"jaundice":-6},"tiers":{"pathognomonic":[],"discriminative":["melena","gibPresentation","bloodyStool","hematemesis","hematuria"],"supportive":["weightLoss","dysphagia","tachycardia","pregnancy","hemoglobin"],"negative":["hepatosplenomegaly","thrombocytopenia","jaundice"]},"rationale":"Iron deficiency anemia is diagnosed primarily by labs (low ferritin, microcytic hypochromic picture) rather than a distinct bedside exam sign, but GI blood loss features (melena, GI bleeding presentation, bloody stool, hematemesis, hematuria) are the key discriminative clues pointing to an underlying source, while weight loss and dysphagia support chronic occult loss or malignancy; splenomegaly, t"},{"id":"ischemic_heart_disease","name":"Ischemic Heart Disease","system":"Cardiovascular","class":"non_infective","find":{"exertionalChestPain":6,"ecgIschemia":6,"knownCAD":6,"chestPain":6,"dyspnea":2,"orthopnea":2,"palpitations":2,"diabetesHx":2,"hypertensionHx":2,"raisedJVP":2,"pleuriticChestPain":-6},"tiers":{"pathognomonic":[],"discriminative":["exertionalChestPain","ecgIschemia","knownCAD","chestPain"],"supportive":["dyspnea","orthopnea","palpitations","diabetesHx","hypertensionHx","raisedJVP"],"negative":["pleuriticChestPain"]},"rationale":"Exertional pressure-type chest pain with dynamic ECG ischemic changes in a patient with known CAD or classic risk factors is highly discriminative for ischemic heart disease, while pleuritic pain argues against it and points toward pericarditis instead."},{"id":"legionellosis","name":"Legionellosis (Legionnaires' Disease)","system":"Infectious Diseases","class":"infective","find":{"diarrhea":6,"nauseaVomiting":6,"alteredSensorium":6,"subacuteOnset":6,"hospitalDay48":6,"fever":2,"cough":2,"purulentSputum":2,"dyspnea":2,"headache":2,"myalgiaArthralgia":2,"consolidation":2,"multilobar":2,"tonsillarExudate":-6,"soreThroat":-6},"tiers":{"pathognomonic":[],"discriminative":["diarrhea","nauseaVomiting","alteredSensorium","subacuteOnset","hospitalDay48"],"supportive":["fever","cough","purulentSputum","dyspnea","headache","myalgiaArthralgia","consolidation","multilobar"],"negative":["tonsillarExudate","soreThroat"]},"rationale":"Legionella pneumonia is an atypical CAP that classically combines respiratory findings with prominent GI symptoms (diarrhea, nausea/vomiting) and confusion/altered sensorium, often with subacute onset or hospital-acquired timing and renal impairment, which help distinguish it from typical bacterial or other atypical pneumonias; no single bedside finding is pathognomonic, and pharyngitis-type findi"},{"id":"leishmaniasis","name":"Leishmaniasis","system":"Infectious Diseases","class":"infective","find":{"hepatosplenomegaly":6,"prolongedFeverUnexplained":6,"weightLoss":6,"travelEndemicArea":6,"lymphadenopathy":6,"fever":2,"rigors":2,"prolongedFever":2,"thrombocytopenia":2,"immunocompromised":2,"mucocutaneousBleeding":2,"mixedMalariaConfirmed":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","prolongedFeverUnexplained","weightLoss","travelEndemicArea","lymphadenopathy"],"supportive":["fever","rigors","prolongedFever","thrombocytopenia","immunocompromised","mucocutaneousBleeding"],"negative":["mixedMalariaConfirmed","tonsillarExudate"]},"rationale":"Visceral leishmaniasis classically presents with prolonged unexplained fever, massive hepatosplenomegaly, weight loss/wasting, pancytopenia (bleeding, thrombocytopenia), and lymphadenopathy in a returning traveler or endemic-area resident; no single bedside finding is pathognomonic without tissue/serologic confirmation."},{"id":"leprosy","name":"Leprosy (Hansen's Disease)","system":"Infectious Diseases","class":"infective","find":{"skinErythema":6,"subacuteOnset":6,"prolongedFever":6,"rash":2,"lymphadenopathy":2,"weightLoss":2,"jointSwelling":2,"toxicAppearing":-6,"hypotension":-6},"tiers":{"pathognomonic":[],"discriminative":["skinErythema","subacuteOnset","prolongedFever"],"supportive":["rash","lymphadenopathy","weightLoss","jointSwelling"],"negative":["toxicAppearing","hypotension"]},"rationale":"Leprosy is diagnosed primarily by hypopigmented/anesthetic skin lesions and thickened peripheral nerves (findings not present in the vocabulary as specific keys), so only loosely related chronic dermatologic/systemic findings map to available vocabulary keys; acute toxic/septic presentations argue against this indolent chronic disease."},{"id":"listeriosis","name":"Listeriosis","system":"Infectious Diseases","class":"infective","find":{"pregnancy":6,"immunocompromised":6,"neckStiffness":6,"alteredSensorium":6,"focalNeuroDeficit":6,"ataxia":6,"fever":2,"rigors":2,"myalgiaArthralgia":2,"seizure":2,"headache":2,"nauseaVomiting":2,"diarrhea":2,"roseSpots":-6,"tonsillarExudate":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["pregnancy","immunocompromised","neckStiffness","alteredSensorium","focalNeuroDeficit","ataxia"],"supportive":["fever","rigors","myalgiaArthralgia","seizure","headache","nauseaVomiting","diarrhea"],"negative":["roseSpots","tonsillarExudate","petechialRash"]},"rationale":"Listeriosis is a foodborne bacteremic/meningoencephalitic illness of pregnant, elderly, and immunocompromised hosts, presenting with fever plus bacteremia symptoms or meningoencephalitis/rhombencephalitis (neck stiffness, altered sensorium, focal deficits, ataxia); no single bedside finding is pathognomonic, and findings like rose spots or tonsillar exudate point toward alternative diagnoses (typh"},{"id":"lyme_disease","name":"Lyme Disease (Lyme Borreliosis)","system":"Infectious Diseases","class":"infective","find":{"eschar":6,"tickExposure":6,"maculopapularRash":6,"jointSwelling":6,"focalNeuroDeficit":6,"rash":2,"fever":2,"myalgiaArthralgia":2,"polyarthralgia":2,"lymphadenopathy":2,"headache":2,"subacuteOnset":2,"mucosalLesions":-6},"tiers":{"pathognomonic":[],"discriminative":["eschar","tickExposure","maculopapularRash","jointSwelling","focalNeuroDeficit"],"supportive":["rash","fever","myalgiaArthralgia","polyarthralgia","lymphadenopathy","headache","subacuteOnset"],"negative":["mucosalLesions"]},"rationale":"Erythema migrans (best mapped to maculopapularRash/rash with tickExposure) is the hallmark early finding, while later disseminated disease features cranial/peripheral neuropathy, migratory large-joint arthritis, and rare AV-block carditis; mucosal blistering argues against Lyme (favoring erythema multiforme) and no single vocabulary key captures true EM well enough to be called pathognomonic."},{"id":"malnutrition_and_nutritional_assessment","name":"Malnutrition and Nutritional Assessment","system":"Gastrointestinal / Nutritional","class":"non_infective","find":{"weightLoss":6,"dehydration":2,"abdominalDiscomfort":2,"oralIntakeAdequate":2},"tiers":{"pathognomonic":[],"discriminative":["weightLoss"],"supportive":["dehydration","abdominalDiscomfort","oralIntakeAdequate"],"negative":[]},"rationale":"Malnutrition (per GLIM criteria) is diagnosed primarily from nonvolitional weight loss combined with reduced intake/assimilation or disease burden; the vocabulary offers no pathognomonic sign and only weightLoss maps closely to a phenotypic diagnostic criterion, while most other supportive features (edema/dehydration affecting weight assessment, reduced oral intake) are nonspecific and shared with"},{"id":"mastocytosis","name":"Mastocytosis","system":"Immunology / Hematology","class":"non_infective","find":{"maculopapularRash":6,"rash":6,"flankPain":6,"syncope":6,"hepatosplenomegaly":6,"diarrhea":6,"tachycardia":2,"hypotension":2,"abdominalPain":2,"nauseaVomiting":2,"bleedingManifestation":2,"petechialRash":-6,"tonsillarExudate":-6,"purulentSputum":-6},"tiers":{"pathognomonic":[],"discriminative":["maculopapularRash","rash","flankPain","syncope","hepatosplenomegaly","diarrhea"],"supportive":["tachycardia","hypotension","abdominalPain","nauseaVomiting","bleedingManifestation"],"negative":["petechialRash","tonsillarExudate","purulentSputum"]},"rationale":"Mastocytosis presents with mast-cell mediator release symptoms (flushing/rash with Darier's sign, tachycardia, hypotension/syncope) plus organ infiltration (hepatosplenomegaly, weight loss) and GI symptoms (diarrhea, abdominal pain); tissue biopsy and tryptase are required for definitive diagnosis so bedside findings are only supportive."},{"id":"measles","name":"Measles (Rubeola)","system":"Infectious Diseases","class":"infective","find":{"coryza":6,"conjunctivalSuffusion":6,"maculopapularRash":6,"cough":6,"lymphadenopathy":6,"fever":2,"rash":2,"headache":2,"abdominalPain":2,"diarrhea":2,"nasalCongestion":2,"tonsillarExudate":-6,"petechialRash":-6,"eschar":-6},"tiers":{"pathognomonic":[],"discriminative":["coryza","conjunctivalSuffusion","maculopapularRash","cough","lymphadenopathy"],"supportive":["fever","rash","headache","abdominalPain","diarrhea","nasalCongestion"],"negative":["tonsillarExudate","petechialRash","eschar"]},"rationale":"Measles is defined by the prodromal triad of cough, coryza, and conjunctivitis followed by a cephalocaudal maculopapular rash; Koplik's spots (pathognomonic) have no matching vocabulary key so pathognomonic is left empty. Tonsillar exudate, petechial/purpuric rash, and eschar argue against measles and favor mimics like streptococcal pharyngitis, meningococcemia/rickettsial disease, or scrub typhus"},{"id":"megaloblastic_anemias","name":"Megaloblastic Anemias","system":"Hematologic","class":"non_infective","find":{"ataxia":6,"focalNeuroDeficit":6,"behavioralChange":6,"hepatosplenomegaly":6,"weightLoss":2,"jaundice":2,"dyspnea":2,"palpitations":2,"fever":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["ataxia","focalNeuroDeficit","behavioralChange","hepatosplenomegaly"],"supportive":["weightLoss","jaundice","dyspnea","palpitations"],"negative":["fever","petechialRash"]},"rationale":"Megaloblastic anemia is diagnosed primarily via CBC/marrow morphology and cobalamin/folate/MMA levels rather than bedside findings, but subacute combined degeneration (ataxia, neuro deficits, behavioral change) plus mild jaundice/hepatosplenomegaly from ineffective erythropoiesis are the closest available discriminators."},{"id":"meningococcal_disease","name":"Meningococcal Disease","system":"Infectious Diseases","class":"infective","find":{"petechialRash":12,"neckStiffness":6,"photophobia":6,"headacheSevere":6,"alteredSensorium":6,"toxicAppearing":6,"fever":2,"rigors":2,"tachycardia":2,"hypotension":2,"seizure":2,"myalgiaArthralgia":2,"vasopressorRequirement":2,"lactateElevated":2,"prolongedFeverUnexplained":-6,"subacuteOnset":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":["petechialRash"],"discriminative":["neckStiffness","photophobia","headacheSevere","alteredSensorium","toxicAppearing"],"supportive":["fever","rigors","tachycardia","hypotension","seizure","myalgiaArthralgia","vasopressorRequirement","lactateElevated"],"negative":["prolongedFeverUnexplained","subacuteOnset","tonsillarExudate"]},"rationale":"A nonblanching petechial/purpuric rash with fever plus meningismus (neck stiffness, photophobia, severe headache) and rapid septic deterioration is highly suggestive of meningococcal disease, though the rash can be absent early; subacute or prolonged-fever presentations argue against this fulminant process."},{"id":"menstrual_disorders_and_pelvic_pain","name":"Menstrual Disorders and Pelvic Pain","system":"Reproductive / Gynecologic","class":"non_infective","find":{"perinealPain":6,"pregnancy":6,"abdominalPain":6,"severeAbdominalPain":6,"abdominalDiscomfort":2,"abdominalDistension":2,"nauseaVomiting":2,"backPain":2,"fever":2,"dysuria":-6,"urinaryFrequency":-6,"costovertebralTenderness":-6,"bloodyStool":-6},"tiers":{"pathognomonic":[],"discriminative":["perinealPain","pregnancy","abdominalPain","severeAbdominalPain"],"supportive":["abdominalDiscomfort","abdominalDistension","nauseaVomiting","backPain","fever"],"negative":["dysuria","urinaryFrequency","costovertebralTenderness","bloodyStool"]},"rationale":"Menstrual disorders and pelvic pain are chiefly diagnosed via menstrual history, beta-hCG, hormone levels, and pelvic ultrasound rather than bedside vitals or basic labs, so only nonspecific pelvic/abdominal pain findings map to the controlled vocabulary; urinary and GI-specific findings argue for alternative sources of pelvic pain."},{"id":"mesenteric_vascular_insufficiency","name":"Mesenteric Vascular Insufficiency","system":"Gastrointestinal / Vascular","class":"non_infective","find":{"severeAbdominalPain":6,"abdominalPain":6,"atrialFibHx":6,"bloodyStool":6,"weightLoss":6,"ageOver50":6,"nauseaVomiting":2,"abdominalDistension":2,"diarrhea":2,"lactateElevated":2,"toxicAppearing":2,"hypotension":2,"oralIntakeAdequate":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["severeAbdominalPain","abdominalPain","atrialFibHx","bloodyStool","weightLoss","ageOver50"],"supportive":["nauseaVomiting","abdominalDistension","diarrhea","lactateElevated","toxicAppearing","hypotension"],"negative":["oralIntakeAdequate","clinicallyImproving"]},"rationale":"Acute mesenteric ischemia is characterized by severe abdominal pain out of proportion to exam, often with atrial fibrillation as an embolic source and bloody stools from mucosal necrosis, while chronic mesenteric ischemia presents with postprandial pain and weight loss in older patients with atherosclerosis; no single bedside finding is pathognomonic."},{"id":"mitral_regurgitation","name":"Mitral Regurgitation","system":"Cardiology","class":"non_infective","find":{"newMurmur":6,"orthopnea":6,"raisedJVP":6,"bilateralCrackles":6,"legSwellingBilateral":6,"dyspnea":2,"palpitations":2,"atrialFibHx":2,"hypotension":2,"exertionalChestPain":2,"murphySign":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","orthopnea","raisedJVP","bilateralCrackles","legSwellingBilateral"],"supportive":["dyspnea","palpitations","atrialFibHx","hypotension","exertionalChestPain"],"negative":["murphySign","tonsillarExudate"]},"rationale":"MR is diagnosed clinically by a holosystolic apical murmur radiating to the axilla with signs of volume overload (raised JVP, bilateral crackles, peripheral edema, orthopnea) and can precipitate atrial fibrillation or acute pulmonary edema; no single bedside finding is pathognomonic since murmur character overlaps with other valvulopathies."},{"id":"mitral_stenosis","name":"Mitral Stenosis","system":"Cardiology","class":"non_infective","find":{"newMurmur":6,"hemoptysis":6,"atrialFibHx":6,"embolicPhenomena":6,"orthopnea":6,"dyspnea":2,"palpitations":2,"raisedJVP":2,"legSwellingBilateral":2,"bilateralCrackles":2,"syncope":2,"exertionalChestPain":-6,"ecgIschemia":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","hemoptysis","atrialFibHx","embolicPhenomena","orthopnea"],"supportive":["dyspnea","palpitations","raisedJVP","legSwellingBilateral","bilateralCrackles","syncope"],"negative":["exertionalChestPain","ecgIschemia"]},"rationale":"Mitral stenosis is classically identified by its characteristic new diastolic murmur with exertional dyspnea/orthopnea, hemoptysis, atrial fibrillation, and embolic phenomena, none of which alone are pathognomonic without echocardiographic confirmation; ischemic chest pain patterns argue against it in favor of coronary disease."},{"id":"mitral_valve_prolapse","name":"Mitral Valve Prolapse","system":"Cardiovascular","class":"non_infective","find":{"newMurmur":6,"chestPain":6,"palpitations":6,"syncope":6,"exertionalChestPain":6,"dyspnea":2,"embolicPhenomena":2,"atrialFibHx":2,"fever":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","chestPain","palpitations","syncope","exertionalChestPain"],"supportive":["dyspnea","embolicPhenomena","atrialFibHx"],"negative":["fever","toxicAppearing"]},"rationale":"MVP is best identified by the classic dynamic auscultatory finding of a mid/late systolic click with a late systolic murmur, plus associated palpitations, atypical chest pain, and syncope from arrhythmia; fever/toxic appearance would suggest an alternative diagnosis such as endocarditis or acute infection rather than MVP."},{"id":"monkeypox","name":"Mpox (Monkeypox) & Poxvirus Infections","system":"Infectious Diseases","class":"infective","find":{"rash":6,"lymphadenopathy":6,"mucosalLesions":6,"fever":2,"headache":2,"myalgiaArthralgia":2,"soreThroat":2,"immunocompromised":2},"tiers":{"pathognomonic":[],"discriminative":["rash","lymphadenopathy","mucosalLesions"],"supportive":["fever","headache","myalgiaArthralgia","soreThroat","immunocompromised"],"negative":[]},"rationale":"Mpox is discriminated by a centrifugal vesiculopustular rash with lymphadenopathy (classically distinguishing it from smallpox) and mucosal lesions, often preceded by fever, headache, sore throat, and myalgia; no single bedside finding is fully pathognomonic since rash morphology/distribution (not captured as a discrete vocabulary key) is the true clincher."},{"id":"mucormycosis","name":"Mucormycosis","system":"Infectious Diseases","class":"infective","find":{"eschar":12,"unilateralFacialPain":6,"facialSwelling":6,"facialPain":6,"immunocompromised":6,"neutropenia":6,"purulentNasalDischarge":2,"headacheSevere":2,"focalNeuroDeficit":2,"fever":2,"toxicAppearing":2,"symptomsOver10Days":-6,"doubleSickening":-6},"tiers":{"pathognomonic":["eschar"],"discriminative":["unilateralFacialPain","facialSwelling","facialPain","immunocompromised","neutropenia"],"supportive":["purulentNasalDischarge","headacheSevere","focalNeuroDeficit","fever","toxicAppearing"],"negative":["symptomsOver10Days","doubleSickening"]},"rationale":"Mucormycosis classically presents with rhino-orbital-cerebral disease marked by facial pain/swelling and a black necrotic eschar in an immunocompromised or DKA/neutropenic host, distinguishing it from typical bacterial sinusitis which follows a slower double-sickening pattern."},{"id":"multiple_and_mixed_valvular_heart","name":"Multiple and Mixed Valvular Heart Disease","system":"Cardiovascular","class":"non_infective","find":{"raisedJVP":6,"orthopnea":6,"legSwellingBilateral":6,"atrialFibHx":6,"exertionalChestPain":6,"dyspnea":2,"palpitations":2,"syncope":2,"bilateralCrackles":2,"ascites":2,"hepatosplenomegaly":2,"knownHeartFailure":2,"newMurmur":-6,"fever":-6,"embolicPhenomena":-6},"tiers":{"pathognomonic":[],"discriminative":["raisedJVP","orthopnea","legSwellingBilateral","atrialFibHx","exertionalChestPain"],"supportive":["dyspnea","palpitations","syncope","bilateralCrackles","ascites","hepatosplenomegaly","knownHeartFailure"],"negative":["newMurmur","fever","embolicPhenomena"]},"rationale":"Multiple/mixed valvular heart disease is a chronic structural diagnosis best identified by combined signs of biventricular volume/pressure overload (raised JVP, orthopnea, bilateral edema, new AF) rather than any single pathognomonic bedside finding; acute fever or a new murmur suggesting endocarditis argues for an alternative or superimposed process."},{"id":"mumps","name":"Mumps","system":"Infectious Diseases","class":"infective","find":{"tenderCervicalNodes":6,"facialSwelling":6,"soreThroat":6,"fever":2,"headache":2,"myalgiaArthralgia":2,"nauseaVomiting":2,"abdominalPain":2,"tonsillarExudate":-6,"purulentNasalDischarge":-6,"rash":-6},"tiers":{"pathognomonic":[],"discriminative":["tenderCervicalNodes","facialSwelling","soreThroat"],"supportive":["fever","headache","myalgiaArthralgia","nauseaVomiting","abdominalPain"],"negative":["tonsillarExudate","purulentNasalDischarge","rash"]},"rationale":"Mumps is defined by parotitis/salivary gland swelling (approximated here by facialSwelling and tenderCervicalNodes) with a nonspecific viral prodrome; no single vocabulary key captures true parotid swelling, so pathognomonic is left empty, and findings like tonsillar exudate or purulent nasal discharge point toward alternative causes of neck/facial swelling or pharyngitis rather than mumps."},{"id":"myasthenia_gravis","name":"Myasthenia Gravis","system":"Neurology","class":"non_infective","find":{"dysphagia":6,"focalNeuroDeficit":6,"subacuteOnset":2,"ascendingWeakness":2,"fever":-6,"neckStiffness":-6,"seizure":-6},"tiers":{"pathognomonic":[],"discriminative":["dysphagia","focalNeuroDeficit"],"supportive":["subacuteOnset","ascendingWeakness"],"negative":["fever","neckStiffness","seizure"]},"rationale":"Myasthenia gravis lacks a truly pathognomonic bedside finding in this vocabulary (ptosis/fatigable weakness are not represented as keys), but fluctuating bulbar weakness (dysphagia) and absence of other focal CNS signs help distinguish it from mimics; fever, meningism, and seizures argue against a pure NMJ disorder."},{"id":"mycoplasma_infection","name":"Mycoplasma Infection","system":"Infectious Diseases","class":"infective","find":{"prolongedCough2Weeks":6,"wheeze":6,"subacuteOnset":6,"mucosalLesions":6,"maculopapularRash":6,"cough":2,"coughRadio":2,"fever":2,"headache":2,"crepitations":2,"consolidation":2,"multilobar":2,"pleuriticChestPain":2,"toxicAppearing":-6,"severeCriteria":-6},"tiers":{"pathognomonic":[],"discriminative":["prolongedCough2Weeks","wheeze","subacuteOnset","mucosalLesions","maculopapularRash"],"supportive":["cough","coughRadio","fever","headache","crepitations","consolidation","multilobar","pleuriticChestPain"],"negative":["toxicAppearing","severeCriteria"]},"rationale":"Mycoplasma pneumoniae ('walking pneumonia') presents with a subacute, gradually worsening nonproductive cough, headache, and wheeze/crepitations often out of proportion to a relatively well-appearing patient, with extrapulmonary features like maculopapular rash or mucosal lesions (SJS/MIRM) being distinctive; the absence of toxic appearance or severe consolidation argues against more fulminant bac"},{"id":"nafld","name":"MASLD / NAFLD (Fatty Liver Disease)","system":"Hepatology","class":"non_infective","find":{"hepatosplenomegaly":6,"liverDisease":6,"ascites":6,"asterixis":6,"abdominalDiscomfort":2,"rightUpperQuadrantPain":2,"jaundice":2,"diabetesHx":2,"hypertensionHx":2,"alcoholExcess":-6,"fever":-6,"weightLoss":-6},"tiers":{"pathognomonic":[],"discriminative":["hepatosplenomegaly","liverDisease","ascites","asterixis"],"supportive":["abdominalDiscomfort","rightUpperQuadrantPain","jaundice","diabetesHx","hypertensionHx"],"negative":["alcoholExcess","fever","weightLoss"]},"rationale":"MASLD is usually asymptomatic and diagnosed incidentally via labs/imaging, so bedside findings are largely nonspecific until advanced fibrosis/cirrhosis produces stigmata like hepatosplenomegaly, ascites, jaundice, or asterixis; significant alcohol use argues against MASLD in favor of alcohol-associated liver disease."},{"id":"neoplasms_of_the_lung","name":"Neoplasms of the Lung","system":"Respiratory / Thoracic Oncology","class":"non_infective","find":{"hemoptysis":6,"prolongedCough2Weeks":6,"weightLoss":6,"cavitatingLesion":6,"cough":2,"dyspnea":2,"chestPain":2,"lymphadenopathy":2,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["hemoptysis","prolongedCough2Weeks","weightLoss","cavitatingLesion"],"supportive":["cough","dyspnea","chestPain","lymphadenopathy"],"negative":["clinicallyImproving"]},"rationale":"Lung cancer cannot be confirmed by bedside findings alone (requires imaging and tissue biopsy), but chronic cough with hemoptysis, unintentional weight loss, and a cavitating lesion in an at-risk patient are the classic discriminative red flags that trigger workup."},{"id":"nephrolithiasis","name":"Nephrolithiasis","system":"Renal/Genitourinary","class":"non_infective","find":{"flankPain":6,"hematuria":6,"costovertebralTenderness":6,"severeAbdominalPain":6,"urinaryFrequency":6,"nauseaVomiting":2,"dysuria":2,"abdominalPain":2,"feverGU":2,"perinealPain":2,"murphySign":-6,"tenesmus":-6,"diarrhea":-6},"tiers":{"pathognomonic":[],"discriminative":["flankPain","hematuria","costovertebralTenderness","severeAbdominalPain","urinaryFrequency"],"supportive":["nauseaVomiting","dysuria","abdominalPain","feverGU","perinealPain"],"negative":["murphySign","tenesmus","diarrhea"]},"rationale":"Colicky flank pain radiating toward the groin with costovertebral angle tenderness and hematuria is the classic renal-colic triad that discriminates nephrolithiasis from its mimics; nausea/vomiting and urinary frequency/dysuria are supportive but nonspecific, while findings pointing to alternate abdominal pathology (positive Murphy sign, tenesmus, diarrhea) argue against a stone."},{"id":"nervous_system_disorders_in_critical","name":"Nervous System Disorders in Critical Care","system":"Nervous System","class":"non_infective","find":{"focalNeuroDeficit":6,"seizure":6,"gcs":6,"headInjury":6,"behavioralChange":6,"headacheSevere":2,"neckStiffness":2,"alteredSensorium":2,"hypoxia":2,"organDysfunction":2,"afebrile24h":-6,"clinicallyImproving":-6,"stable":-6},"tiers":{"pathognomonic":[],"discriminative":["focalNeuroDeficit","seizure","gcs","headInjury","behavioralChange"],"supportive":["headacheSevere","neckStiffness","alteredSensorium","hypoxia","organDysfunction"],"negative":["afebrile24h","clinicallyImproving","stable"]},"rationale":"This is a broad critical-care neurologic syndrome category (coma/encephalopathy from structural or metabolic causes) rather than a single specific disease, so findings are nonspecific and mainly reflect depressed consciousness (low GCS) with or without focal deficits/seizures suggesting a structural lesion; no pathognomonic bedside sign exists and diagnosis ultimately requires neuroimaging."},{"id":"neuromyelitis_optica","name":"Neuromyelitis Optica","system":"Nervous system","class":"non_infective","find":{"visualDisturbance":6,"ascendingWeakness":6,"focalNeuroDeficit":6,"backPain":6,"headache":2,"seizure":2,"behavioralChange":2,"urinaryRetention":2,"nauseaVomiting":2,"fever":-6,"rigors":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":[],"discriminative":["visualDisturbance","ascendingWeakness","focalNeuroDeficit","backPain"],"supportive":["headache","seizure","behavioralChange","urinaryRetention","nauseaVomiting"],"negative":["fever","rigors","tonsillarExudate"]},"rationale":"NMO presents with bilateral severe optic neuritis (visual disturbance/loss) and longitudinally extensive transverse myelitis causing ascending weakness, focal deficits, back pain, and bladder dysfunction, but no single bedside finding is fully pathognomonic without MRI/AQP4-IgG confirmation."},{"id":"nocardiosis","name":"Nocardiosis","system":"Infectious Diseases","class":"infective","find":{"immunocompromised":6,"cavitatingLesion":6,"subacuteOnset":6,"focalNeuroDeficit":6,"multilobar":6,"cough":2,"purulentSputum":2,"fever":2,"weightLoss":2,"consolidation":2,"headache":2,"seizure":2},"tiers":{"pathognomonic":[],"discriminative":["immunocompromised","cavitatingLesion","subacuteOnset","focalNeuroDeficit","multilobar"],"supportive":["cough","purulentSputum","fever","weightLoss","consolidation","headache","seizure"],"negative":[]},"rationale":"Nocardiosis is a subacute opportunistic pulmonary infection in immunocompromised hosts producing cavitating/nodular infiltrates with non-malodorous purulent sputum, and it frequently disseminates to the CNS causing focal neurologic deficits or seizures from ring-enhancing brain abscesses; no single bedside finding is pathognomonic and diagnosis ultimately requires microbiologic/imaging confirmatio"},{"id":"non_hodgkin_lymphoma","name":"Non-Hodgkin's Lymphoma","system":"Oncology / Hematology","class":"non_infective","find":{"lymphadenopathy":6,"hepatosplenomegaly":6,"nightSweats":6,"weightLoss":6,"prolongedFeverUnexplained":6,"fever":2,"malignancy":2,"subacuteOnset":2,"abdominalDistension":2,"splenomegaly":2,"tonsillarExudate":-6,"soreThroat":-6,"rash":-6},"tiers":{"pathognomonic":[],"discriminative":["lymphadenopathy","hepatosplenomegaly","nightSweats","weightLoss","prolongedFeverUnexplained"],"supportive":["fever","malignancy","subacuteOnset","abdominalDistension","splenomegaly"],"negative":["tonsillarExudate","soreThroat","rash"]},"rationale":"NHL classically presents with painless multi-site lymphadenopathy and constitutional B symptoms (fever, drenching night sweats, weight loss) with hepatosplenomegaly, but no single finding is pathognomonic since diagnosis requires tissue biopsy; findings suggesting an acute infectious/reactive process argue against it."},{"id":"nontuberculous_mycobacterial_infection","name":"Nontuberculous Mycobacterial Infection","system":"Infectious Diseases","class":"infective","find":{"knownBronchiectasis":6,"cavitatingLesion":6,"prolongedCough2Weeks":6,"hemoptysis":6,"immunocompromised":6,"cough":2,"increasedSputumVolume":2,"weightLoss":2,"nightSweats":2,"subacuteOnset":2,"lymphadenopathy":2,"toxicAppearing":-6,"severeCriteria":-6},"tiers":{"pathognomonic":[],"discriminative":["knownBronchiectasis","cavitatingLesion","prolongedCough2Weeks","hemoptysis","immunocompromised"],"supportive":["cough","increasedSputumVolume","weightLoss","nightSweats","subacuteOnset","lymphadenopathy"],"negative":["toxicAppearing","severeCriteria"]},"rationale":"NTM disease typically presents as a subacute-to-chronic pulmonary syndrome (chronic cough, hemoptysis, weight loss, night sweats) in patients with pre-existing bronchiectasis or cavitary lung disease, or as disseminated disease in the immunocompromised; diagnosis ultimately requires imaging and specialized mycobacterial cultures rather than being clinchable on bedside findings alone."},{"id":"obesity","name":"Obesity","system":"Endocrine / Metabolic","class":"non_infective","find":{"weight":6,"hypertensionHx":2,"diabetesHx":2,"weightLoss":-6},"tiers":{"pathognomonic":[],"discriminative":["weight"],"supportive":["hypertensionHx","diabetesHx"],"negative":["weightLoss"]},"rationale":"Obesity is diagnosed anthropometrically via BMI derived from weight (and height, not in vocabulary), not from acute clinical findings; it is commonly associated with hypertension and diabetes, while unintentional weight loss argues against it."},{"id":"oncologic_emergencies","name":"Oncologic Emergencies","system":"Oncology / Emergency","class":"non_infective","find":{"facialSwelling":6,"backPain":6,"ascendingWeakness":6,"focalNeuroDeficit":6,"malignancy":6,"dyspnea":2,"cough":2,"headacheSevere":2,"papilledema":2,"seizure":2,"weightLoss":2,"oralIntakeAdequate":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["facialSwelling","backPain","ascendingWeakness","focalNeuroDeficit","malignancy"],"supportive":["dyspnea","cough","headacheSevere","papilledema","seizure","weightLoss"],"negative":["oralIntakeAdequate","clinicallyImproving"]},"rationale":"Oncologic emergencies (SVCS, malignant cord compression, raised ICP) are best flagged by facial/upper-body swelling with dyspnea, back pain with neurologic deficit, and a background of active malignancy; findings are heterogeneous across the three mechanisms so pathognomonic single-key markers are lacking."},{"id":"opioid_related_disorders","name":"Opioid-Related Disorders","system":"Neurologic/Psychiatric (substance use)","class":"non_infective","find":{"miosisSecretions":6,"bradypnea":6,"drugOverdose":6,"ivDrugUse":6,"alteredSensorium":2,"hypothermia":2,"bradycardia":2,"hypotension":2,"seizure":2},"tiers":{"pathognomonic":[],"discriminative":["miosisSecretions","bradypnea","drugOverdose","ivDrugUse"],"supportive":["alteredSensorium","hypothermia","bradycardia","hypotension","seizure"],"negative":[]},"rationale":"Opioid toxicity is best identified by the combination of pinpoint pupils/secretions, slow shallow breathing, and a drug-overdose context (often with IV drug use history), while general sedation, hypothermia, bradycardia, and hypotension are supportive but nonspecific; no single finding is fully pathognomonic and no listed finding argues against the diagnosis."},{"id":"osteomyelitis","name":"Osteomyelitis","system":"Musculoskeletal","class":"infective","find":{"boneInvolvement":6,"backPain":6,"subacuteOnset":6,"diabeticFootUlcer":6,"erythemaAtSite":6,"fever":2,"severePain":2,"deepTissueInvolvement":2,"purulentDrainage":2,"peripheralVascularDisease":2,"weightLoss":2,"prolongedFever":2,"afebrile24h":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["boneInvolvement","backPain","subacuteOnset","diabeticFootUlcer","erythemaAtSite"],"supportive":["fever","severePain","deepTissueInvolvement","purulentDrainage","peripheralVascularDisease","weightLoss","prolongedFever"],"negative":["afebrile24h","clinicallyImproving"]},"rationale":"Vertebral or contiguous-focus osteomyelitis is best signaled by localized bone involvement with back pain (in adults, hematogenous disease favors the spine) or a diabetic foot ulcer/deep tissue infection with erythema at the site, often subacute in onset with less than half of patients febrile; fever and systemic findings are supportive but non-specific and only about half of patients are febrile "},{"id":"pagets_disease_bone","name":"Paget's Disease of Bone","system":"Endocrine / Metabolic Bone","class":"non_infective","find":{"boneInvolvement":6,"backPain":6,"headache":2,"subacuteOnset":2,"fever":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["boneInvolvement","backPain"],"supportive":["headache","subacuteOnset"],"negative":["fever","toxicAppearing"]},"rationale":"Paget's disease is usually diagnosed incidentally via isolated raised ALP with normal calcium/phosphate and characteristic imaging, not by bedside findings; the closest available vocabulary keys reflect its bone pain/involvement and skull-related headache, while acute febrile/toxic findings argue against this chronic, afebrile metabolic bone disorder."},{"id":"pancreatic_cancer","name":"Pancreatic Cancer","system":"Oncology","class":"non_infective","find":{"jaundice":6,"weightLoss":6,"abdominalPain":6,"backPain":6,"nauseaVomiting":2,"malignancy":2,"abdominalDiscomfort":2,"diabetesHx":2,"hepatosplenomegaly":2,"fever":-6,"rigors":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["jaundice","weightLoss","abdominalPain","backPain"],"supportive":["nauseaVomiting","malignancy","abdominalDiscomfort","diabetesHx","hepatosplenomegaly"],"negative":["fever","rigors","toxicAppearing"]},"rationale":"Painless jaundice with weight loss and boring epigastric-to-back pain are the classic discriminative triad for pancreatic cancer, while acute infective features like fever/rigors argue against this indolent malignant process; no bedside finding is pathognomonic since diagnosis requires imaging/biopsy."},{"id":"paraneoplastic_syndromes_endocrinologic_he","name":"Paraneoplastic Syndromes: Endocrinologic/Hematologic","system":"Multisystem (Oncology / Endocrine / Hematologic)","class":"non_infective","find":{"malignancy":6,"alteredSensorium":6,"polyuriaPolydipsia":6,"weightLoss":6,"seizure":2,"behavioralChange":2,"dehydration":2,"nauseaVomiting":2,"legSwellingBilateral":2},"tiers":{"pathognomonic":[],"discriminative":["malignancy","alteredSensorium","polyuriaPolydipsia","weightLoss"],"supportive":["seizure","behavioralChange","dehydration","nauseaVomiting","legSwellingBilateral"],"negative":[]},"rationale":"Paraneoplastic endocrine/hematologic syndromes (HHM, SIADH, ectopic ACTH) present with nonspecific bedside findings like altered mentation, polyuria/polydipsia, and weight loss in a patient with known active malignancy, but definitive diagnosis requires biochemical workup (calcium, PTH/PTHrP, sodium/osmolality, ACTH) not captured by exam alone."},{"id":"parathyroid_calcium_disorders","name":"Parathyroid & Calcium Disorders","system":"Endocrine / Metabolic","class":"non_infective","find":{"polyuriaPolydipsia":6,"abdominalPain":6,"seizure":6,"alteredSensorium":6,"weightLoss":2,"constipationOrDiarrhea":2,"nauseaVomiting":2,"abdominalDiscomfort":2,"bradycardia":2,"headache":2,"behavioralChange":2,"fever":-6,"rigors":-6,"toxicAppearing":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["polyuriaPolydipsia","abdominalPain","seizure","alteredSensorium"],"supportive":["weightLoss","constipationOrDiarrhea","nauseaVomiting","abdominalDiscomfort","bradycardia","headache","behavioralChange"],"negative":["fever","rigors","toxicAppearing","petechialRash"]},"rationale":"Parathyroid/calcium disorders present with the classic hypercalcemic triad of 'stones, bones, groans, psychiatric overtones' (polyuria/polydipsia, abdominal pain, altered sensorium/seizure from severe derangement) plus nonspecific GI and neuropsychiatric complaints, but lack fever/rigors/toxic appearance that would suggest an infective or septic process instead."},{"id":"paroxysmal_supraventricular_tachycardias","name":"Paroxysmal Supraventricular Tachycardias","system":"Cardiovascular","class":"non_infective","find":{"palpitations":6,"syncope":6,"tachycardia":6,"chestPain":2,"dyspnea":2,"hypotension":2,"fever":-6,"rigors":-6,"diarrhea":-6},"tiers":{"pathognomonic":[],"discriminative":["palpitations","syncope","tachycardia"],"supportive":["chestPain","dyspnea","hypotension"],"negative":["fever","rigors","diarrhea"]},"rationale":"PSVT is best identified by sudden-onset palpitations with tachycardia, sometimes causing syncope or presyncope from hemodynamic compromise, while infectious/febrile findings argue against a purely arrhythmic paroxysmal event; definitive diagnosis requires ECG rather than bedside findings alone."},{"id":"parvovirus_infections","name":"Parvovirus Infections","system":"Infectious Diseases (Hematologic/Multisystem viral infection)","class":"infective","find":{"symmetricSmallJointInvolvement":6,"severeArthralgia":6,"maculopapularRash":6,"sickleCellHx":6,"rash":2,"myalgiaArthralgia":2,"polyarthralgia":2,"jointSwelling":2,"lymphadenopathy":2,"fever":2,"petechialRash":-6,"eschar":-6},"tiers":{"pathognomonic":[],"discriminative":["symmetricSmallJointInvolvement","severeArthralgia","maculopapularRash","sickleCellHx"],"supportive":["rash","myalgiaArthralgia","polyarthralgia","jointSwelling","lymphadenopathy","fever"],"negative":["petechialRash","eschar"]},"rationale":"Parvovirus B19 classically causes symmetric small-joint arthralgia with a maculopapular rash in adults (or slapped-cheek rash in children), and precipitates transient aplastic crisis in patients with hemolytic disorders like sickle cell disease; presence of eschar or petechial/purpuric rash points away toward other diagnoses (rickettsial disease, meningococcemia)."},{"id":"peptic_ulcer_disease_and_related","name":"Peptic Ulcer Disease and Related Disorders","system":"Gastrointestinal","class":"non_infective","find":{"melena":6,"hematemesis":6,"gibPresentation":6,"abdominalPain":6,"nauseaVomiting":2,"weightLoss":2,"abdominalDiscomfort":2,"dehydration":2,"syncope":2,"severeAbdominalPain":2,"diarrhea":-6,"bloodyStool":-6,"tenesmus":-6},"tiers":{"pathognomonic":[],"discriminative":["melena","hematemesis","gibPresentation","abdominalPain"],"supportive":["nauseaVomiting","weightLoss","abdominalDiscomfort","dehydration","syncope","severeAbdominalPain"],"negative":["diarrhea","bloodyStool","tenesmus"]},"rationale":"Peptic ulcer disease is best signaled by epigastric/abdominal pain together with overt upper GI bleeding features (melena, hematemesis, GI bleeding presentation); most other findings are nonspecific dyspeptic symptoms, and predominantly lower-GI features like diarrhea, bloody stool, and tenesmus argue against it."},{"id":"periarticular_disorders_of_the_extremities","name":"Periarticular Disorders of the Extremities","system":"Musculoskeletal","class":"non_infective","find":{"jointSwelling":6,"skinWarmth":6,"skinErythema":6,"severePain":2,"polyarthralgia":2,"myalgiaArthralgia":2,"fever":-6,"rigors":-6,"toxicAppearing":-6,"purulentDrainage":-6},"tiers":{"pathognomonic":[],"discriminative":["jointSwelling","skinWarmth","skinErythema"],"supportive":["severePain","polyarthralgia","myalgiaArthralgia"],"negative":["fever","rigors","toxicAppearing","purulentDrainage"]},"rationale":"Periarticular disorders (bursitis, tendinopathy, tenosynovitis) present with localized peri-joint pain, swelling, warmth, and provocative-maneuver findings rather than systemic toxicity; presence of fever, rigors, toxic appearance, or purulent drainage argues for septic bursitis/arthritis instead, and definitive diagnosis often requires exam maneuvers, aspiration, or imaging not captured by this v"},{"id":"pericardial_disease","name":"Pericardial Disease","system":"Cardiology","class":"non_infective","find":{"pleuriticChestPain":6,"exertionalChestPain":6,"raisedJVP":6,"hypotension":6,"legSwellingBilateral":6,"chestPain":2,"fever":2,"dyspnea":2,"orthopnea":2,"tachycardia":2,"palpitations":2,"ecgIschemia":-6},"tiers":{"pathognomonic":[],"discriminative":["pleuriticChestPain","exertionalChestPain","raisedJVP","hypotension","legSwellingBilateral"],"supportive":["chestPain","fever","dyspnea","orthopnea","tachycardia","palpitations"],"negative":["ecgIschemia"]},"rationale":"Pericardial disease presents with positional pleuritic chest pain, and tamponade/constriction produce hypotension with raised JVP and peripheral edema; no single bedside finding is fully pathognomonic, and ischemic ECG changes argue more for AMI than pericarditis."},{"id":"peripheral_neuropathy","name":"Peripheral Neuropathy","system":"Neurology","class":"non_infective","find":{"ascendingWeakness":6,"focalNeuroDeficit":6,"ataxia":6,"diabetesHx":2,"alcoholExcess":2,"weightLoss":2,"malignancy":2,"polyuriaPolydipsia":2},"tiers":{"pathognomonic":[],"discriminative":["ascendingWeakness","focalNeuroDeficit","ataxia"],"supportive":["diabetesHx","alcoholExcess","weightLoss","malignancy","polyuriaPolydipsia"],"negative":[]},"rationale":"Peripheral neuropathy is best identified by ascending/length-dependent weakness with sensory loss, focal neurologic deficits (mononeuropathy multiplex), and gait ataxia (sensory ataxia), with diabetes, alcohol excess, malignancy, and weight loss serving as common risk-factor context rather than specific bedside signs."},{"id":"pertussis","name":"Pertussis (Whooping Cough)","system":"Infectious Diseases","class":"infective","find":{"prolongedCough2Weeks":6,"cough":6,"coryza":6,"nasalCongestion":2,"fever":2,"consolidation":-6,"purulentSputum":-6,"pleuriticPain":-6},"tiers":{"pathognomonic":[],"discriminative":["prolongedCough2Weeks","cough","coryza"],"supportive":["nasalCongestion","fever"],"negative":["consolidation","purulentSputum","pleuriticPain"]},"rationale":"Pertussis has no single pathognomonic bedside sign, but a paroxysmal cough lasting more than two weeks preceded by coryza with characteristic absence of high fever or focal pulmonary findings strongly suggests it; presence of consolidation or purulent sputum argues for bacterial pneumonia instead."},{"id":"pheochromocytoma","name":"Pheochromocytoma","system":"Endocrine","class":"non_infective","find":{"paroxysmalFever":6,"palpitations":6,"headacheSevere":6,"hypertensionHx":6,"tachycardia":2,"nauseaVomiting":2,"weightLoss":2,"syncope":2,"fever":-6,"hypotension":-6},"tiers":{"pathognomonic":[],"discriminative":["paroxysmalFever","palpitations","headacheSevere","hypertensionHx"],"supportive":["tachycardia","nauseaVomiting","weightLoss","syncope"],"negative":["fever","hypotension"]},"rationale":"Pheochromocytoma classically presents with episodic paroxysms of severe headache, palpitations, and diaphoresis against a background of hypertension, distinguishing it from infectious/vasodilatory causes; sustained fever or hypotension would argue against an adrenergic-excess state."},{"id":"pituitary_tumor_syndromes","name":"Pituitary Tumor Syndromes","system":"Endocrine","class":"non_infective","find":{"visualDisturbance":6,"papilledema":6,"headacheSevere":6,"headache":2,"polyuriaPolydipsia":2,"behavioralChange":2,"focalNeuroDeficit":2,"nauseaVomiting":2,"fever":-6,"rigors":-6,"toxicAppearing":-6},"tiers":{"pathognomonic":[],"discriminative":["visualDisturbance","papilledema","headacheSevere"],"supportive":["headache","polyuriaPolydipsia","behavioralChange","focalNeuroDeficit","nauseaVomiting"],"negative":["fever","rigors","toxicAppearing"]},"rationale":"Pituitary tumors classically present with progressive visual field loss (bitemporal hemianopia) from chiasmal compression, headache, and mass-effect/endocrine features rather than acute infective or hemodynamic derangement; sudden severe headache with visual loss suggests apoplexy."},{"id":"plague","name":"Plague","system":"Infectious Diseases","class":"infective","find":{"lymphadenopathy":12,"hemoptysis":6,"toxicAppearing":6,"bleedingManifestation":6,"abdominalPain":6,"rash":6,"fever":2,"rigors":2,"headacheSevere":2,"myalgiaArthralgia":2,"nauseaVomiting":2,"tachycardia":2,"symmetricSmallJointInvolvement":-6,"tonsillarExudate":-6,"prolongedFeverUnexplained":-6},"tiers":{"pathognomonic":["lymphadenopathy"],"discriminative":["hemoptysis","toxicAppearing","bleedingManifestation","abdominalPain","rash"],"supportive":["fever","rigors","headacheSevere","myalgiaArthralgia","nauseaVomiting","tachycardia"],"negative":["symmetricSmallJointInvolvement","tonsillarExudate","prolongedFeverUnexplained"]},"rationale":"Bubonic plague's hallmark is an acutely painful, tense, boggy regional lymph node (bubo) with abrupt high fever and toxicity, while pneumonic disease adds rapid-onset hemoptysis and severe illness and septicemic disease causes bleeding/DIC; symmetric small-joint arthralgia, exudative tonsillitis, and unexplained prolonged fever (which favor its chronic mimics) argue against acute plague."},{"id":"plasma_cell_disorders","name":"Plasma Cell Disorders (MGUS, Waldenström)","system":"Oncology / Hematology","class":"non_infective","find":{"backPain":6,"renalImpairment":6,"hepatosplenomegaly":6,"visualDisturbance":6,"headache":6,"bleedingManifestation":6,"weightLoss":2,"malignancy":2,"alteredSensorium":2,"focalNeuroDeficit":2,"hemoglobin":2,"creatinine":2,"subacuteOnset":2,"petechialRash":-6,"diarrhea":-6,"dysuria":-6,"purulentSputum":-6},"tiers":{"pathognomonic":[],"discriminative":["backPain","renalImpairment","hepatosplenomegaly","visualDisturbance","headache","bleedingManifestation"],"supportive":["weightLoss","malignancy","alteredSensorium","focalNeuroDeficit","hemoglobin","creatinine","subacuteOnset"],"negative":["petechialRash","diarrhea","dysuria","purulentSputum"]},"rationale":"Plasma cell disorders are diagnosed mainly via laboratory/marrow studies (SPEP, immunofixation, free light chains, biopsy) rather than a distinct bedside syndrome; the closest clinical clues are CRAB-related findings (renal impairment, anemia, bone/back pain), hyperviscosity features (headache, visual disturbance, altered sensorium, bleeding) and hepatosplenomegaly, none of which are pathognomonic"},{"id":"platelet_disorders","name":"Platelet Disorders (Thrombocytopenia)","system":"Hematology","class":"non_infective","find":{"petechialRash":6,"thrombocytopenia":6,"mucocutaneousBleeding":6,"bleedingManifestation":6,"hepatosplenomegaly":2,"splenomegaly":2,"gibPresentation":2,"melena":2,"hematuria":2,"hematemesis":2,"fever":-6,"rigors":-6},"tiers":{"pathognomonic":[],"discriminative":["petechialRash","thrombocytopenia","mucocutaneousBleeding","bleedingManifestation"],"supportive":["hepatosplenomegaly","splenomegaly","gibPresentation","melena","hematuria","hematemesis"],"negative":["fever","rigors"]},"rationale":"Thrombocytopenia with petechial rash, mucocutaneous bleeding, and other bleeding manifestations are the core bedside/lab clues; splenomegaly supports sequestration-related causes, while overt sepsis features like fever/rigors point more toward infection-driven consumptive processes than a primary platelet disorder."},{"id":"pneumococcal_disease","name":"Pneumococcal Disease","system":"Infectious Diseases","class":"infective","find":{"rigors":6,"purulentSputum":6,"consolidation":6,"multilobar":6,"pleuriticPain":6,"neckStiffness":6,"fever":2,"cough":2,"crepitations":2,"chestPain":2,"toxicAppearing":2,"severeCriteria":2,"headacheSevere":2,"seizure":2,"prolongedFeverUnexplained":-6,"subacuteOnset":-6,"coryza":-6,"nasalCongestion":-6},"tiers":{"pathognomonic":[],"discriminative":["rigors","purulentSputum","consolidation","multilobar","pleuriticPain","neckStiffness"],"supportive":["fever","cough","crepitations","chestPain","toxicAppearing","severeCriteria","headacheSevere","seizure"],"negative":["prolongedFeverUnexplained","subacuteOnset","coryza","nasalCongestion"]},"rationale":"Pneumococcal disease has no single pathognomonic sign, but abrupt-onset lobar/multilobar pneumonia with rigors and pleuritic pain, or meningismus with altered sensorium, strongly suggests it, while a subacute/prolonged unexplained fever course or coryzal upper-respiratory picture argues against classic pneumococcal presentations."},{"id":"pneumocystis_pneumonia","name":"Pneumocystis Pneumonia (PCP)","system":"Infectious Diseases","class":"infective","find":{"immunocompromised":6,"subacuteOnset":6,"dyspnea":6,"hypoxia":6,"supplementalOxygen":6,"fever":2,"cough":2,"tachypnea":2,"weightLoss":2,"spo2":2,"worseningOxygenation":2,"purulentSputum":-6,"consolidation":-6,"pleuriticChestPain":-6,"hemoptysis":-6},"tiers":{"pathognomonic":[],"discriminative":["immunocompromised","subacuteOnset","dyspnea","hypoxia","supplementalOxygen"],"supportive":["fever","cough","tachypnea","weightLoss","spo2","worseningOxygenation"],"negative":["purulentSputum","consolidation","pleuriticChestPain","hemoptysis"]},"rationale":"PCP classically presents as subacute progressive dyspnea and hypoxia disproportionate to exam/CXR findings in an immunocompromised host, without the purulent sputum or lobar consolidation typical of bacterial pneumonia."},{"id":"poisoning_and_drug_overdose","name":"Poisoning and Drug Overdose","system":"Toxicology / Multisystem","class":"non_infective","find":{"miosisSecretions":12,"drugOverdose":6,"alteredSensorium":6,"seizure":6,"rigidity":6,"ataxia":6,"bradypnea":6,"hypothermia":2,"bradycardia":2,"hypotension":2,"tachycardia":2,"gcs":2,"focalNeuroDeficit":-6,"neckStiffness":-6,"photophobia":-6},"tiers":{"pathognomonic":["miosisSecretions"],"discriminative":["drugOverdose","alteredSensorium","seizure","rigidity","ataxia","bradypnea"],"supportive":["hypothermia","bradycardia","hypotension","tachycardia","gcs"],"negative":["focalNeuroDeficit","neckStiffness","photophobia"]},"rationale":"Poisoning/overdose is recognized by a toxidrome context (drugOverdose exposure history) with CNS/respiratory depression (alteredSensorium, bradypnea, low GCS) or cholinergic miosis with secretions, plus seizures/rigidity from stimulant or serotonergic agents; focal neurologic deficits or meningism argue for a structural or infectious mimic instead."},{"id":"polycythemia_vera_and_other_myeloprolifera","name":"Polycythemia Vera and Other Myeloproliferative Neoplasms","system":"Hematologic/Oncologic","class":"non_infective","find":{"splenomegaly":6,"hepatosplenomegaly":6,"legSwellingUnilateral":6,"abdominalPain":6,"thrombocytopenia":6,"headache":2,"visualDisturbance":2,"myalgiaArthralgia":2,"syncope":2,"chestPain":2,"jaundice":2,"fever":-6,"weightLoss":-6,"lymphadenopathy":-6},"tiers":{"pathognomonic":[],"discriminative":["splenomegaly","hepatosplenomegaly","legSwellingUnilateral","abdominalPain","thrombocytopenia"],"supportive":["headache","visualDisturbance","myalgiaArthralgia","syncope","chestPain","jaundice"],"negative":["fever","weightLoss","lymphadenopathy"]},"rationale":"PV/PMF/ET present with hyperviscosity/thrombotic phenomena (splenomegaly, unusual-site venous thrombosis, abdominal pain from splenic infarction or Budd-Chiari) and hemorrhagic risk from extreme thrombocytosis, but lack a single bedside pathognomonic sign; fever and prominent lymphadenopathy argue more for an infective or lymphoproliferative process."},{"id":"polymorphic_ventricular_tachycardia_and_ve","name":"Polymorphic Ventricular Tachycardia and Ventricular Fibrillation","system":"Cardiovascular","class":"non_infective","find":{"syncope":6,"palpitations":6,"chestPain":2,"dyspnea":2},"tiers":{"pathognomonic":[],"discriminative":["syncope","palpitations"],"supportive":["chestPain","dyspnea"],"negative":[]},"rationale":"Diagnosis fundamentally requires ECG (QTc, QRS morphology) which is outside the bedside vocabulary; syncope/palpitations/cardiac-arrest presentation are the only clinical clues, and they are shared with many other arrhythmias and cardiac mimics."},{"id":"porphyria","name":"Porphyria","system":"Metabolic / Hematology","class":"non_infective","find":{"severeAbdominalPain":6,"abdominalDistension":6,"ascendingWeakness":6,"behavioralChange":6,"darkUrine":6,"seizure":6,"abdominalPain":2,"nauseaVomiting":2,"tachycardia":2,"dysuria":2,"urinaryRetention":2,"backPain":2,"petechialRash":-6,"jaundice":-6,"hepatosplenomegaly":-6},"tiers":{"pathognomonic":[],"discriminative":["severeAbdominalPain","abdominalDistension","ascendingWeakness","behavioralChange","darkUrine","seizure"],"supportive":["abdominalPain","nauseaVomiting","tachycardia","dysuria","urinaryRetention","backPain"],"negative":["petechialRash","jaundice","hepatosplenomegaly"]},"rationale":"Acute hepatic porphyria classically presents with severe poorly-localized abdominal pain, distension/ileus, dark urine, autonomic tachycardia, and neuropsychiatric features (motor neuropathy/ascending weakness, behavioral change, seizures) precipitated by drugs/fasting/hormones; findings like jaundice or hepatosplenomegaly argue against it in favor of liver disease mimics."},{"id":"premature_ventricular_contractions_nonsust","name":"Premature Ventricular Contractions, Nonsustained Idioventricular Rhythm","system":"Cardiovascular","class":"non_infective","find":{"palpitations":6,"syncope":6,"chestPain":2,"dyspnea":2,"thunderclapHeadache":-6,"severeAbdominalPain":-6},"tiers":{"pathognomonic":[],"discriminative":["palpitations","syncope"],"supportive":["chestPain","dyspnea"],"negative":["thunderclapHeadache","severeAbdominalPain"]},"rationale":"PVCs/NSVT are primarily an ECG/telemetry diagnosis presenting clinically with palpitations and sometimes syncope or near-syncope; no bedside finding is pathognomonic, and other acute focal complaints argue against this being the primary process."},{"id":"primary_immunodeficiency","name":"Primary Immunodeficiency","system":"Immunology","class":"non_infective","find":{"immunocompromised":6,"mucositis":6,"neutropenia":6,"absoluteNeutrophilCountLow":6,"prolongedFever":2,"weightLoss":2,"hepatosplenomegaly":2,"lymphadenopathy":2,"diarrhea":2},"tiers":{"pathognomonic":[],"discriminative":["immunocompromised","mucositis","neutropenia","absoluteNeutrophilCountLow"],"supportive":["prolongedFever","weightLoss","hepatosplenomegaly","lymphadenopathy","diarrhea"],"negative":[]},"rationale":"Primary immunodeficiency is a genetic diagnosis confirmed by immunoglobulin levels, lymphocyte phenotyping, and functional assays rather than bedside findings; clinically it is suggested by a pattern of immunocompromised host status with severe/opportunistic infection, mucositis, cytopenias, and chronic constitutional features like prolonged fever, weight loss, and hepatosplenomegaly/lymphadenopat"},{"id":"prion_diseases","name":"Prion Diseases (CJD)","system":"Neurology","class":"non_infective","find":{"behavioralChange":6,"rigidity":6,"ataxia":6,"seizure":6,"subacuteOnset":2,"focalNeuroDeficit":2,"headache":2,"fever":-6,"prolongedFeverUnexplained":-6,"nightSweats":-6},"tiers":{"pathognomonic":[],"discriminative":["behavioralChange","rigidity","ataxia","seizure"],"supportive":["subacuteOnset","focalNeuroDeficit","headache"],"negative":["fever","prolongedFeverUnexplained","nightSweats"]},"rationale":"CJD lacks a truly pathognomonic bedside finding (diagnosis rests on MRI/EEG/CSF), but the combination of subacute rapidly progressive dementia (behavioral change) with rigidity, ataxia, and myoclonus/seizure activity is strongly discriminative against typical infectious or slower neurodegenerative mimics; presence of prominent fever or prolonged unexplained fever argues against prion disease and f"},{"id":"protozoal_intestinal_infections_and_tricho","name":"Protozoal Intestinal Infections and Trichomoniasis","system":"Gastrointestinal / Genitourinary (infectious)","class":"infective","find":{"diarrhea":6,"abdominalDistension":6,"nauseaVomiting":6,"immunocompromised":6,"contaminatedFoodWaterExposure":6,"abdominalPain":2,"weightLoss":2,"dehydration":2,"constipationOrDiarrhea":2,"perinealPain":2,"bloodyStool":-6,"fever":-6,"tenesmus":-6},"tiers":{"pathognomonic":[],"discriminative":["diarrhea","abdominalDistension","nauseaVomiting","immunocompromised","contaminatedFoodWaterExposure"],"supportive":["abdominalPain","weightLoss","dehydration","constipationOrDiarrhea","perinealPain"],"negative":["bloodyStool","fever","tenesmus"]},"rationale":"Giardiasis and related protozoal enteric infections present with non-bloody, non-febrile watery/malabsorptive diarrhea, bloating, and nausea/vomiting typically linked to contaminated food/water exposure or immunocompromise (chronic profuse diarrhea in AIDS), whereas fever, blood, or mucus in stool point away toward colitis or bacterial disease."},{"id":"pulmonary_hypertension","name":"Pulmonary Hypertension","system":"Cardiology / Pulmonary","class":"non_infective","find":{"dyspnea":6,"syncope":6,"raisedJVP":6,"legSwellingBilateral":6,"chestPain":6,"palpitations":6,"orthopnea":2,"hypoxia":2,"ascites":2,"exertionalChestPain":2,"legSwellingUnilateral":2,"fever":-6,"purulentSputum":-6,"consolidation":-6,"wheeze":-6},"tiers":{"pathognomonic":[],"discriminative":["dyspnea","syncope","raisedJVP","legSwellingBilateral","chestPain","palpitations"],"supportive":["orthopnea","hypoxia","ascites","exertionalChestPain","legSwellingUnilateral"],"negative":["fever","purulentSputum","consolidation","wheeze"]},"rationale":"Pulmonary hypertension is suggested by exertional dyspnea with signs of right heart strain/failure (raised JVP, bilateral leg edema, syncope, palpitations, chest pain) but has no truly pathognomonic bedside finding since it requires echocardiography/right heart catheterisation for confirmation; febrile or infective/airway findings argue against it as the primary explanation."},{"id":"pulmonic_valve_disease","name":"Pulmonic Valve Disease","system":"Cardiovascular","class":"non_infective","find":{"syncope":6,"raisedJVP":6,"dyspnea":2,"exertionalChestPain":2,"legSwellingBilateral":2,"orthopnea":2,"chestPain":2,"pleuriticChestPain":-6},"tiers":{"pathognomonic":[],"discriminative":["syncope","raisedJVP"],"supportive":["dyspnea","exertionalChestPain","legSwellingBilateral","orthopnea","chestPain"],"negative":["pleuriticChestPain"]},"rationale":"Pulmonic valve disease is a structural/congenital lesion diagnosed by characteristic murmur and echocardiography rather than by systemic bedside findings; syncope and raised JVP with right heart failure signs (dyspnea, leg edema, orthopnea) are the closest available non-specific correlates, while pleuritic chest pain argues for an alternative pulmonary/pericardial cause."},{"id":"rabies","name":"Rabies","system":"Infectious Diseases","class":"infective","find":{"behavioralChange":6,"seizure":6,"focalNeuroDeficit":6,"alteredSensorium":6,"ascendingWeakness":6,"fever":2,"headache":2,"neckStiffness":2,"photophobia":2,"rigidity":2,"ataxia":2},"tiers":{"pathognomonic":[],"discriminative":["behavioralChange","seizure","focalNeuroDeficit","alteredSensorium","ascendingWeakness"],"supportive":["fever","headache","neckStiffness","photophobia","rigidity","ataxia"],"negative":[]},"rationale":"Hydrophobia/aerophobia are not in the vocabulary, so the nearest discriminative markers are prodromal behavioral change progressing to fluctuating consciousness, seizures, focal deficits, or ascending flaccid weakness (paralytic form); fever, meningismus, and headache are supportive but non-specific for an atypical encephalitis with generally preserved consciousness."},{"id":"relapsing_fever","name":"Relapsing Fever","system":"Infectious Disease (Spirochetal / Vector-borne)","class":"infective","find":{"paroxysmalFever":6,"tickExposure":6,"hepatosplenomegaly":6,"myalgiaArthralgia":6,"jaundice":6,"fever":2,"rigors":2,"headache":2,"nauseaVomiting":2,"subacuteOnset":2,"thrombocytopenia":2,"symmetricSmallJointInvolvement":-6,"tonsillarExudate":-6,"purulentSputum":-6},"tiers":{"pathognomonic":[],"discriminative":["paroxysmalFever","tickExposure","hepatosplenomegaly","myalgiaArthralgia","jaundice"],"supportive":["fever","rigors","headache","nauseaVomiting","subacuteOnset","thrombocytopenia"],"negative":["symmetricSmallJointInvolvement","tonsillarExudate","purulentSputum"]},"rationale":"Relapsing fever is best recognized by recurring paroxysmal fever episodes separated by afebrile intervals, often with tick exposure history, hepatosplenomegaly, arthralgia/myalgia, and jaundice from hepatic involvement; there is no single pathognomonic bedside sign, so definitive diagnosis requires blood smear or PCR."},{"id":"renovascular_disease","name":"Renovascular Disease","system":"Renal/Genitourinary","class":"non_infective","find":{"hypertensionHx":6,"ageOver50":6,"flankPain":6,"headache":2,"chestPain":2,"dyspnea":2,"legSwellingBilateral":2,"raisedJVP":2,"oliguria":2,"renalImpairment":2,"fever":-6,"rigors":-6,"toxicAppearing":-6,"diarrhea":-6},"tiers":{"pathognomonic":[],"discriminative":["hypertensionHx","ageOver50","flankPain"],"supportive":["headache","chestPain","dyspnea","legSwellingBilateral","raisedJVP","oliguria","renalImpairment"],"negative":["fever","rigors","toxicAppearing","diarrhea"]},"rationale":"Renovascular disease is suggested by resistant/severe hypertension (especially abrupt-onset in a young woman for FMD, or in an older patient with atherosclerotic risk for ARAS), sometimes with flash pulmonary edema or renal impairment, but has no truly pathognomonic bedside finding; acute infective/inflammatory features argue against it."},{"id":"rickettsial_diseases","name":"Rickettsial Diseases","system":"Infectious / Multisystem (vasculotropic)","class":"infective","find":{"eschar":12,"petechialRash":6,"maculopapularRash":6,"tickExposure":6,"conjunctivalSuffusion":6,"thrombocytopenia":6,"fever":2,"headacheSevere":2,"myalgiaArthralgia":2,"rash":2,"hepatosplenomegaly":2,"alteredSensorium":2,"lymphadenopathy":2,"tonsillarExudate":-6,"purulentSputum":-6},"tiers":{"pathognomonic":["eschar"],"discriminative":["petechialRash","maculopapularRash","tickExposure","conjunctivalSuffusion","thrombocytopenia"],"supportive":["fever","headacheSevere","myalgiaArthralgia","rash","hepatosplenomegaly","alteredSensorium","lymphadenopathy"],"negative":["tonsillarExudate","purulentSputum"]},"rationale":"Eschar at a tick-bite site is near-pathognomonic for spotted fever group rickettsioses, while tick exposure, petechial/maculopapular rash, conjunctival suffusion, and thrombocytopenia strongly discriminate against typhoid, viral syndromes, and bacterial sepsis mimics; fever, myalgia, headache, and hepatosplenomegaly are consistent but nonspecific early findings."},{"id":"rubella_german_measles","name":"Rubella (German Measles)","system":"Infectious Diseases (viral exanthem / congenital infection)","class":"infective","find":{"lymphadenopathy":6,"maculopapularRash":6,"polyarthralgia":6,"pregnancy":6,"fever":2,"coryza":2,"rash":2,"myalgiaArthralgia":2,"headache":2,"tonsillarExudate":-6,"purulentNasalDischarge":-6},"tiers":{"pathognomonic":[],"discriminative":["lymphadenopathy","maculopapularRash","polyarthralgia","pregnancy"],"supportive":["fever","coryza","rash","myalgiaArthralgia","headache"],"negative":["tonsillarExudate","purulentNasalDischarge"]},"rationale":"Rubella lacks a truly pathognomonic sign, but the combination of mild fever with a fleeting maculopapular rash, characteristic occipital/postauricular lymphadenopathy, and post-pubertal arthralgia (especially relevant in a pregnant contact) discriminates it from mimics; tonsillar exudate or purulent nasal discharge point instead toward streptococcal or bacterial sinus processes."},{"id":"salmonellosis","name":"Nontyphoidal Salmonellosis","system":"Infectious Diseases","class":"infective","find":{"bloodyStool":6,"contaminatedFoodWaterExposure":6,"tenesmus":6,"immunocompromised":6,"sickleCellHx":6,"diarrhea":2,"nauseaVomiting":2,"abdominalPain":2,"severeAbdominalPain":2,"fever":2,"dehydration":2,"prolongedFeverUnexplained":-6,"roseSpots":-6,"stepladderFever":-6,"relativeBradycardia":-6},"tiers":{"pathognomonic":[],"discriminative":["bloodyStool","contaminatedFoodWaterExposure","tenesmus","immunocompromised","sickleCellHx"],"supportive":["diarrhea","nauseaVomiting","abdominalPain","severeAbdominalPain","fever","dehydration"],"negative":["prolongedFeverUnexplained","roseSpots","stepladderFever","relativeBradycardia"]},"rationale":"NTS is a food/water-borne gastroenteritis with nonbloody-to-bloody diarrhea, nausea/vomiting, and abdominal pain that is clinically indistinguishable from other enteric infections, so no bedside finding is pathognomonic; typhoidal-pattern findings (rose spots, stepladder fever, relative bradycardia, prolonged unexplained fever) argue against NTS and favor enteric fever instead."},{"id":"schistosomiasis","name":"Schistosomiasis","system":"Infectious Diseases","class":"infective","find":{"waterExposure":6,"travelEndemicArea":6,"maculopapularRash":6,"hematuria":6,"bloodyStool":6,"hepatosplenomegaly":6,"fever":2,"prolongedFever":2,"weightLoss":2,"myalgiaArthralgia":2,"headache":2,"cough":2,"diarrhea":2,"abdominalPain":2,"eschar":-6,"conjunctivalSuffusion":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":[],"discriminative":["waterExposure","travelEndemicArea","maculopapularRash","hematuria","bloodyStool","hepatosplenomegaly"],"supportive":["fever","prolongedFever","weightLoss","myalgiaArthralgia","headache","cough","diarrhea","abdominalPain"],"negative":["eschar","conjunctivalSuffusion","tonsillarExudate"]},"rationale":"Schistosomiasis is suggested by freshwater/water exposure in an endemic area with cercarial (maculopapular) rash, followed by hepatosplenic disease (hepatosplenomegaly, ascites, variceal bleeding) or urogenital disease (painless hematuria); Katayama fever presents with fever, myalgia, cough and abdominal symptoms but is nonspecific, so no bedside finding alone is pathognomonic."},{"id":"seizures_and_epilepsy","name":"Seizures and Epilepsy","system":"Nervous system","class":"non_infective","find":{"seizure":6,"focalNeuroDeficit":6,"behavioralChange":6,"headacheSevere":2,"alteredSensorium":2,"ataxia":2,"neckStiffness":-6,"photophobia":-6,"fever":-6},"tiers":{"pathognomonic":[],"discriminative":["seizure","focalNeuroDeficit","behavioralChange"],"supportive":["headacheSevere","alteredSensorium","ataxia"],"negative":["neckStiffness","photophobia","fever"]},"rationale":"Seizure itself is the defining event but not disease-specific; focal deficits (Todd's paralysis) and behavioral/personality change support an epileptic focus, while meningismus and fever argue for a CNS infection mimic rather than primary epilepsy."},{"id":"sexually_transmitted_infections_overview_a","name":"Sexually Transmitted Infections: Overview and Clinical Approach","system":"Genitourinary / Reproductive","class":"infective","find":{"dysuria":6,"urinaryFrequency":6,"perinealPain":6,"urinaryRetention":6,"abdominalPain":2,"severeAbdominalPain":2,"fever":2,"lymphadenopathy":2,"rash":2,"costovertebralTenderness":-6,"flankPain":-6},"tiers":{"pathognomonic":[],"discriminative":["dysuria","urinaryFrequency","perinealPain","urinaryRetention"],"supportive":["abdominalPain","severeAbdominalPain","fever","lymphadenopathy","rash"],"negative":["costovertebralTenderness","flankPain"]},"rationale":"This is a broad STI-syndrome overview rather than a single pathogen, so findings are nonspecific genitourinary symptoms (dysuria, urethral/pelvic pain) that raise suspicion for an STI syndrome, while costovertebral tenderness/flank pain point instead toward pyelonephritis, a key differential."},{"id":"shigellosis","name":"Shigellosis","system":"Infectious Diseases","class":"infective","find":{"bloodyStool":6,"tenesmus":6,"highFeverGI":6,"severeAbdominalPain":6,"diarrhea":2,"fever":2,"abdominalPain":2,"nauseaVomiting":2,"dehydration":2,"alteredSensorium":2,"oralIntakeAdequate":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["bloodyStool","tenesmus","highFeverGI","severeAbdominalPain"],"supportive":["diarrhea","fever","abdominalPain","nauseaVomiting","dehydration","alteredSensorium"],"negative":["oralIntakeAdequate","clinicallyImproving"]},"rationale":"Shigellosis classically presents as dysentery with fever, tenesmus, and frequent small-volume bloody mucopurulent stools plus cramps; bloody stool and tenesmus with high fever are the most discriminating bedside clues versus non-invasive causes of diarrhea."},{"id":"sickle_cell_disease","name":"Sickle Cell Disease","system":"Haematology","class":"non_infective","find":{"sickleCellHx":12,"severeAbdominalPain":6,"backPain":6,"hemoglobin":6,"jaundice":6,"hypoxia":6,"fever":2,"chestPain":2,"cough":2,"dyspnea":2,"splenomegaly":2,"abdominalPain":2},"tiers":{"pathognomonic":["sickleCellHx"],"discriminative":["severeAbdominalPain","backPain","hemoglobin","jaundice","hypoxia"],"supportive":["fever","chestPain","cough","dyspnea","splenomegaly","abdominalPain"],"negative":[]},"rationale":"Known sickle cell disease history plus acute severe pain (limb/back/abdominal), low hemoglobin, jaundice and hypoxia (suggesting acute chest syndrome) are the key discriminators; there are no findings whose presence should argue against the diagnosis in a known sickler presenting acutely."},{"id":"spondyloarthritis","name":"Spondyloarthritis","system":"Rheumatology","class":"non_infective","find":{"backPain":6,"polyarthralgia":6,"jointSwelling":6,"subacuteOnset":6,"myalgiaArthralgia":6,"weightLoss":2,"abdominalPain":2,"diarrhea":2,"rash":2,"fever":2,"petechialRash":-6,"toxicAppearing":-6,"organDysfunction":-6},"tiers":{"pathognomonic":[],"discriminative":["backPain","polyarthralgia","jointSwelling","subacuteOnset","myalgiaArthralgia"],"supportive":["weightLoss","abdominalPain","diarrhea","rash","fever"],"negative":["petechialRash","toxicAppearing","organDysfunction"]},"rationale":"Spondyloarthritis presents with chronic inflammatory back pain and asymmetric oligoarthritis/enthesitis rather than acute infectious/toxic features, so discriminators center on back/joint pain patterns while toxic-appearing sepsis-type findings argue against it; no single bedside finding is pathognomonic."},{"id":"st_segment_elevation_myocardial_infarction","name":"ST-Segment Elevation Myocardial Infarction","system":"Cardiovascular","class":"non_infective","find":{"ecgIschemia":12,"chestPain":6,"exertionalChestPain":6,"hypotension":6,"newMurmur":6,"raisedJVP":6,"dyspnea":2,"syncope":2,"palpitations":2,"knownCAD":2,"hypertensionHx":2,"diabetesHx":2,"atrialFibHx":2,"pleuriticChestPain":-6,"tenderCervicalNodes":-6},"tiers":{"pathognomonic":["ecgIschemia"],"discriminative":["chestPain","exertionalChestPain","hypotension","newMurmur","raisedJVP"],"supportive":["dyspnea","syncope","palpitations","knownCAD","hypertensionHx","diabetesHx","atrialFibHx"],"negative":["pleuriticChestPain","tenderCervicalNodes"]},"rationale":"STEMI is defined by acute ischemic ST-segment elevation on ECG (pathognomonic when combined with the clinical syndrome), with prolonged substernal/exertional chest pain, hypotension, new mechanical complications (murmur), and elevated JVP (RV infarct) being strongly discriminative; pleuritic pain favors pericarditis/PE over STEMI."},{"id":"staphylococcal_infections","name":"Staphylococcal Infections","system":"Infectious Diseases","class":"infective","find":{"mucosalLesions":6,"newMurmur":6,"embolicPhenomena":6,"erythemaAtSite":6,"purulentDrainage":6,"centralLine":6,"fever":2,"rigors":2,"toxicAppearing":2,"hypotension":2,"skinErythema":2,"skinWarmth":2,"rash":2,"lymphadenopathy":2,"symptomsOver10Days":-6,"doubleSickening":-6,"travelEndemicArea":-6,"paroxysmalFever":-6},"tiers":{"pathognomonic":[],"discriminative":["mucosalLesions","newMurmur","embolicPhenomena","erythemaAtSite","purulentDrainage","centralLine"],"supportive":["fever","rigors","toxicAppearing","hypotension","skinErythema","skinWarmth","rash","lymphadenopathy"],"negative":["symptomsOver10Days","doubleSickening","travelEndemicArea","paroxysmalFever"]},"rationale":"Staphylococcal disease spans skin/soft-tissue infection, device/catheter and endocardial infection, and toxin-mediated syndromes; discriminative clues center on purulent/device-associated foci, new murmur with embolic phenomena, and mucocutaneous involvement, while fever, erythema, and bacteremia are supportive but nonspecific across many bacterial infections."},{"id":"streptococcal_infections","name":"Streptococcal Infections","system":"Infectious Diseases","class":"infective","find":{"soreThroat":6,"tonsillarExudate":6,"tenderCervicalNodes":6,"maculopapularRash":6,"rapidlySpreadingErythema":6,"severePain":6,"fever":2,"skinErythema":2,"skinWarmth":2,"purulentDrainage":2,"lymphadenopathy":2,"toxicAppearing":2,"newMurmur":2,"coryza":-6,"nasalCongestion":-6},"tiers":{"pathognomonic":[],"discriminative":["soreThroat","tonsillarExudate","tenderCervicalNodes","maculopapularRash","rapidlySpreadingErythema","severePain"],"supportive":["fever","skinErythema","skinWarmth","purulentDrainage","lymphadenopathy","toxicAppearing","newMurmur"],"negative":["coryza","nasalCongestion"]},"rationale":"GAS pharyngitis is marked by sore throat with tonsillar exudate and tender cervical nodes, scarlet fever by a sandpaper-like maculopapular rash, and necrotizing soft-tissue/skin infection by rapidly spreading erythema, pain out of proportion, and crepitus/bullae; prominent coryza/nasal congestion argue against streptococcal pharyngitis (favoring a viral cause) and no single finding is fully pathog"},{"id":"superficial_fungal_infections","name":"Superficial Fungal Infections","system":"Skin and Soft Tissue","class":"infective","find":{"sharplyDemarcatedBorder":6,"skinErythema":6,"rash":2,"immunocompromised":2,"fever":-6,"toxicAppearing":-6,"rapidlySpreadingErythema":-6,"severePain":-6},"tiers":{"pathognomonic":[],"discriminative":["sharplyDemarcatedBorder","skinErythema"],"supportive":["rash","immunocompromised"],"negative":["fever","toxicAppearing","rapidlySpreadingErythema","severePain"]},"rationale":"Superficial fungal infections present as chronic, well-demarcated, scaly, non-systemic skin/nail/hair lesions without invasion; systemic toxicity or rapidly spreading erythema/severe pain would argue for bacterial cellulitis or deeper infection instead."},{"id":"syphilis","name":"Syphilis","system":"Infectious Diseases","class":"infective","find":{"lymphadenopathy":6,"maculopapularRash":6,"rash":6,"fever":2,"headache":2,"myalgiaArthralgia":2,"weightLoss":2,"subacuteOnset":2,"petechialRash":-6,"tonsillarExudate":-6},"tiers":{"pathognomonic":[],"discriminative":["lymphadenopathy","maculopapularRash","rash"],"supportive":["fever","headache","myalgiaArthralgia","weightLoss","subacuteOnset"],"negative":["petechialRash","tonsillarExudate"]},"rationale":"Syphilis lacks a truly pathognomonic bedside sign (chancre/condylomata lata/mucous patches aren't in the vocabulary), but the combination of a nonpruritic maculopapular rash with generalized nontender lymphadenopathy is highly discriminative for secondary syphilis; systemic symptoms like fever, headache, arthralgia and weight loss are supportive but nonspecific."},{"id":"systemic_lupus_erythematosus","name":"Systemic Lupus Erythematosus","system":"Immune-Mediated / Rheumatologic (multisystem)","class":"non_infective","find":{"rash":6,"symmetricSmallJointInvolvement":6,"polyarthralgia":6,"photophobia":6,"proteinuria":6,"hematuria":6,"fever":2,"weightLoss":2,"myalgiaArthralgia":2,"jointSwelling":2,"alteredSensorium":2,"focalNeuroDeficit":2,"headache":2,"pleuriticChestPain":2,"tonsillarExudate":-6,"purulentSputum":-6,"dysuria":-6},"tiers":{"pathognomonic":[],"discriminative":["rash","symmetricSmallJointInvolvement","polyarthralgia","photophobia","proteinuria","hematuria"],"supportive":["fever","weightLoss","myalgiaArthralgia","jointSwelling","alteredSensorium","focalNeuroDeficit","headache","pleuriticChestPain"],"negative":["tonsillarExudate","purulentSputum","dysuria"]},"rationale":"SLE is a multisystem autoimmune disease best recognized by the combination of photosensitive rash, symmetric small-joint polyarthralgia/arthritis, cytopenias (thrombocytopenia), renal involvement (proteinuria/hematuria), and neuropsychiatric features (seizure, behavioral change), none of which alone is pathognomonic since diagnosis requires serology (ANA, anti-dsDNA, anti-Sm) not captured in this "},{"id":"tetanus","name":"Tetanus","system":"Infectious Diseases","class":"infective","find":{"rigidity":12,"dysphagia":6,"seizure":6,"fever":2,"tachycardia":2,"hypotension":2,"alteredSensorium":2,"ascendingWeakness":-6},"tiers":{"pathognomonic":["rigidity"],"discriminative":["dysphagia","seizure"],"supportive":["fever","tachycardia","hypotension","alteredSensorium"],"negative":["ascendingWeakness"]},"rationale":"Tetanus is a clinical diagnosis defined by sustained muscle rigidity (trismus, risus sardonicus, opisthotonos) with dysphagia and spasms; ascending weakness/areflexia is characteristic of Guillain-Barre and argues against tetanus, while autonomic instability (fever, tachycardia, hypotension) is a late supportive feature."},{"id":"the_bradyarrhythmias_disorders_of_the","name":"The Bradyarrhythmias: Disorders of the Atrioventricular Node","system":"Cardiovascular","class":"non_infective","find":{"bradycardia":6,"syncope":6,"cardiacImplantableDevice":6,"palpitations":2,"dyspnea":2,"alteredSensorium":2,"hypotension":2,"knownCAD":2,"chestPain":2,"tachycardia":-6},"tiers":{"pathognomonic":[],"discriminative":["bradycardia","syncope","cardiacImplantableDevice"],"supportive":["palpitations","dyspnea","alteredSensorium","hypotension","knownCAD","chestPain"],"negative":["tachycardia"]},"rationale":"Bradyarrhythmias from AV nodal disease present with bradycardia (often with syncope/presyncope) and may already have a pacemaker/ICD placed; nonspecific supportive features include palpitations, dyspnea, altered sensorium, hypotension and underlying coronary disease, while tachycardia argues against the diagnosis."},{"id":"the_hyperbilirubinemias","name":"The Hyperbilirubinemias","system":"Hepatobiliary / Gastrointestinal","class":"non_infective","find":{"bilirubin":6,"darkUrine":6,"jaundice":6,"rightUpperQuadrantPain":2,"hepatosplenomegaly":2,"nauseaVomiting":2,"abdominalDiscomfort":2,"liverDisease":2,"fever":-6,"toxicAppearing":-6,"abdominalPain":-6},"tiers":{"pathognomonic":[],"discriminative":["bilirubin","darkUrine","jaundice"],"supportive":["rightUpperQuadrantPain","hepatosplenomegaly","nauseaVomiting","abdominalDiscomfort","liverDisease"],"negative":["fever","toxicAppearing","abdominalPain"]},"rationale":"Hyperbilirubinemia syndromes present with jaundice and dark urine (bilirubinuria indicating a conjugated fraction) plus elevated serum bilirubin, but definitive subclassification requires fractionation, coproporphyrin analysis, and genotyping beyond bedside findings; presence of toxic appearance, fever, or severe abdominal pain argues for an acute hepatobiliary infective/obstructive process rather"},{"id":"the_vasculitis_syndromes","name":"The Vasculitis Syndromes","system":"Multisystem / Rheumatologic (Immune-Mediated Vascular)","class":"non_infective","find":{"petechialRash":6,"hemoptysis":6,"hematuria":6,"proteinuria":6,"focalNeuroDeficit":6,"unilateralFacialPain":6,"fever":2,"weightLoss":2,"myalgiaArthralgia":2,"polyarthralgia":2,"rash":2,"abdominalPain":2,"renalImpairment":2,"nightSweats":2,"purulentSputum":-6,"dysuria":-6},"tiers":{"pathognomonic":[],"discriminative":["petechialRash","hemoptysis","hematuria","proteinuria","focalNeuroDeficit","unilateralFacialPain"],"supportive":["fever","weightLoss","myalgiaArthralgia","polyarthralgia","rash","abdominalPain","renalImpairment","nightSweats"],"negative":["purulentSputum","dysuria"]},"rationale":"Vasculitis is discriminated by multisystem small-vessel damage signs (purpuric rash, pulmonary hemorrhage, renal involvement with hematuria/proteinuria, mononeuritis-type focal deficits, and new headache/visual symptoms suggesting GCA) rather than any single pathognomonic finding, while constitutional and non-specific findings are only supportive."},{"id":"thrombotic_renovascular_disorders","name":"Thrombotic Renovascular Disorders","system":"Renal/Genitourinary","class":"non_infective","find":{"thrombocytopenia":6,"alteredSensorium":6,"seizure":6,"focalNeuroDeficit":6,"renalImpairment":6,"fever":2,"jaundice":2,"oliguria":2,"hematuria":2,"hypertensionHx":2,"abdominalPain":2,"nauseaVomiting":2,"pregnancy":2,"diarrhea":-6,"bloodyStool":-6,"petechialRash":-6},"tiers":{"pathognomonic":[],"discriminative":["thrombocytopenia","alteredSensorium","seizure","focalNeuroDeficit","renalImpairment"],"supportive":["fever","jaundice","oliguria","hematuria","hypertensionHx","abdominalPain","nauseaVomiting","pregnancy"],"negative":["diarrhea","bloodyStool","petechialRash"]},"rationale":"TTP/HUS present with the MAHA-thrombocytopenia-organ-injury triad (thrombocytopenia, neurologic findings, renal impairment) rather than a single pathognomonic sign; bloody diarrhea points more toward STEC-HUS and prominent petechial rash toward other causes of thrombocytopenia, so their presence is less specific for the primary complement/ADAMTS13-mediated forms."},{"id":"toxic_and_drug_induced_hepatitis","name":"Toxic and Drug-Induced Hepatitis","system":"Hepatobiliary / Gastrointestinal","class":"non_infective","find":{"jaundice":6,"liverDisease":6,"bilirubin":6,"inr":6,"encephalopathyGrade":6,"nauseaVomiting":2,"abdominalDiscomfort":2,"rightUpperQuadrantPain":2,"fever":2,"darkUrine":2,"ascites":2,"asterixis":2,"prolongedFeverUnexplained":-6,"roseSpots":-6,"stepladderFever":-6},"tiers":{"pathognomonic":[],"discriminative":["jaundice","liverDisease","bilirubin","inr","encephalopathyGrade"],"supportive":["nauseaVomiting","abdominalDiscomfort","rightUpperQuadrantPain","fever","darkUrine","ascites","asterixis"],"negative":["prolongedFeverUnexplained","roseSpots","stepladderFever"]},"rationale":"Toxic/drug-induced hepatitis presents with jaundice and hepatocellular injury (elevated bilirubin, coagulopathy via INR, encephalopathy in severe cases) in the context of a known hepatotoxic exposure, with no truly pathognomonic bedside finding since it mimics viral, autoimmune, and ischemic hepatitis; typhoidal fever patterns argue against it."},{"id":"toxoplasmosis","name":"Toxoplasmosis","system":"Infectious Diseases","class":"infective","find":{"immunocompromised":6,"alteredSensorium":6,"seizure":6,"focalNeuroDeficit":6,"lymphadenopathy":6,"fever":2,"headache":2,"myalgiaArthralgia":2,"behavioralChange":2},"tiers":{"pathognomonic":[],"discriminative":["immunocompromised","alteredSensorium","seizure","focalNeuroDeficit","lymphadenopathy"],"supportive":["fever","headache","myalgiaArthralgia","behavioralChange"],"negative":[]},"rationale":"Reactivation toxoplasma encephalitis in an immunocompromised host presenting with altered sensorium, seizure, and focal neurological deficit is the classic severe pattern, while immunocompetent disease most often shows nontender cervical lymphadenopathy with low-grade fever, headache, and malaise; no single bedside finding is pathognomonic since CNS lesions and serology require imaging/lab confirm"},{"id":"transfusion_reactions","name":"Transfusion Reactions","system":"Hematology / Transfusion","class":"non_infective","find":{"fever":6,"rigors":6,"hypotension":6,"tachypnea":6,"dyspnea":6,"facialSwelling":6,"tachycardia":2,"hypoxia":2,"chestPain":2,"backPain":2,"flankPain":2,"jaundice":2,"darkUrine":2,"hematuria":2,"afebrile24h":-6,"clinicallyImproving":-6,"stable":-6},"tiers":{"pathognomonic":[],"discriminative":["fever","rigors","hypotension","tachypnea","dyspnea","facialSwelling"],"supportive":["tachycardia","hypoxia","chestPain","backPain","flankPain","jaundice","darkUrine","hematuria"],"negative":["afebrile24h","clinicallyImproving","stable"]},"rationale":"Transfusion reactions are diagnosed primarily from a temporal relationship to a transfusion plus fever/rigors, hypotension, respiratory distress, or acute allergic features (facial swelling, rash), with jaundice/dark urine/haemoglobinuria and flank/back pain pointing to a haemolytic mechanism; no single vocabulary key is pathognomonic without the transfusion-temporal context, which is not part of "},{"id":"trichinellosis_and_other_tissue_nematode","name":"Trichinellosis and Other Tissue Nematode Infections","system":"Infectious Disease (Parasitology / Tissue Helminths)","class":"infective","find":{"myalgiaArthralgia":6,"contaminatedFoodWaterExposure":6,"fever":2,"diarrhea":2,"abdominalPain":2,"nauseaVomiting":2,"rash":2,"dyspnea":2},"tiers":{"pathognomonic":[],"discriminative":["myalgiaArthralgia","contaminatedFoodWaterExposure"],"supportive":["fever","diarrhea","abdominalPain","nauseaVomiting","rash","dyspnea"],"negative":[]},"rationale":"Trichinellosis lacks a single bedside-pathognomonic sign in this vocabulary (periorbital edema, splinter hemorrhages, eosinophilia are not listed keys), but a suggestive meal history plus severe myalgia/arthralgia after a biphasic enteric-then-migratory illness are the closest discriminative markers, supported by nonspecific fever, GI symptoms, rash, and dyspnea from myositis/pneumonitis."},{"id":"tricuspid_valve_disease","name":"Tricuspid Valve Disease","system":"Cardiovascular","class":"non_infective","find":{"newMurmur":6,"raisedJVP":6,"hepatosplenomegaly":6,"ascites":6,"legSwellingBilateral":6,"dyspnea":2,"abdominalDistension":2,"jaundice":2,"atrialFibHx":2,"knownHeartFailure":2,"orthopnea":2,"pleuriticChestPain":-6,"exertionalChestPain":-6},"tiers":{"pathognomonic":[],"discriminative":["newMurmur","raisedJVP","hepatosplenomegaly","ascites","legSwellingBilateral"],"supportive":["dyspnea","abdominalDistension","jaundice","atrialFibHx","knownHeartFailure","orthopnea"],"negative":["pleuriticChestPain","exertionalChestPain"]},"rationale":"Tricuspid valve disease presents with right-heart congestion signs (elevated JVP with prominent c-v waves, new regurgitant/holosystolic murmur accentuated by inspiration, hepatosplenomegaly, ascites, and bilateral edema) while pleuritic or exertional ischemic-type chest pain argues against it as these are not features of isolated tricuspid disease."},{"id":"trigeminal_neuralgia_bell_s_palsy","name":"Trigeminal Neuralgia, Bell’s Palsy, and Other Cranial Nerve Disorders","system":"Nervous system","class":"non_infective","find":{"unilateralFacialPain":6,"facialPain":6,"headache":2,"focalNeuroDeficit":-6,"alteredSensorium":-6,"behavioralChange":-6},"tiers":{"pathognomonic":[],"discriminative":["unilateralFacialPain","facialPain"],"supportive":["headache"],"negative":["focalNeuroDeficit","alteredSensorium","behavioralChange"]},"rationale":"Trigeminal neuralgia and Bell's palsy are diagnosed primarily by history (paroxysmal unilateral facial pain triggered by touch, or acute unilateral facial weakness) rather than vital signs or labs, so the controlled vocabulary offers only limited facial-pain descriptors; presence of focal neurologic deficit, altered sensorium, or behavioral change argues for a central/structural cause rather than "},{"id":"tubulointerstitial_disease","name":"Tubulointerstitial Kidney Disease","system":"Nephrology","class":"non_infective","find":{"hematuria":6,"proteinuria":6,"polyuriaPolydipsia":6,"flankPain":6,"rash":6,"fever":2,"renalImpairment":2,"oliguria":2,"photophobia":2,"dehydration":2,"dysuria":-6,"costovertebralTenderness":-6,"feverGU":-6},"tiers":{"pathognomonic":[],"discriminative":["hematuria","proteinuria","polyuriaPolydipsia","flankPain","rash"],"supportive":["fever","renalImpairment","oliguria","photophobia","dehydration"],"negative":["dysuria","costovertebralTenderness","feverGU"]},"rationale":"Acute interstitial nephritis presents with drug exposure, rash/eosinophilia-type hypersensitivity features, rising creatinine/renal impairment, hematuria, and flank pain from capsular distention, while chronic TIN shows tubular dysfunction (polyuria/polydipsia) and proteinuria; classic pyelonephritis-type urinary symptoms (dysuria, CVA tenderness, fever with GU source) argue against it since TIN i"},{"id":"tularemia","name":"Tularemia","system":"Infectious Diseases","class":"infective","find":{"eschar":12,"lymphadenopathy":6,"tickExposure":6,"ruralExposure":6,"conjunctivalSuffusion":6,"tonsillarExudate":6,"fever":2,"rigors":2,"headache":2,"myalgiaArthralgia":2,"hepatosplenomegaly":2,"prolongedFever":2,"petechialRash":-6,"maculopapularRash":-6},"tiers":{"pathognomonic":["eschar"],"discriminative":["lymphadenopathy","tickExposure","ruralExposure","conjunctivalSuffusion","tonsillarExudate"],"supportive":["fever","rigors","headache","myalgiaArthralgia","hepatosplenomegaly","prolongedFever"],"negative":["petechialRash","maculopapularRash"]},"rationale":"Tularemia classically presents with a tick/animal-exposure history, a necrotic eschar at the inoculation site with tender regional lymphadenopathy (ulceroglandular form), and influenza-like constitutional symptoms; petechial or diffuse maculopapular rash is atypical and argues against it."},{"id":"uncommon_disseminated_fungal_infections","name":"Uncommon Disseminated Fungal Infections","system":"Multisystem (Infectious Diseases / Mycoses)","class":"infective","find":{"immunocompromised":6,"neutropenia":6,"absoluteNeutrophilCountLow":6,"eschar":6,"mucosalLesions":6,"prolongedFeverUnexplained":6,"fever":2,"prolongedFever":2,"weightLoss":2,"hepatosplenomegaly":2,"lymphadenopathy":2,"subacuteOnset":2,"toxicAppearing":2,"rash":2,"afebrile24h":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["immunocompromised","neutropenia","absoluteNeutrophilCountLow","eschar","mucosalLesions","prolongedFeverUnexplained"],"supportive":["fever","prolongedFever","weightLoss","hepatosplenomegaly","lymphadenopathy","subacuteOnset","toxicAppearing","rash"],"negative":["afebrile24h","clinicallyImproving"]},"rationale":"Disseminated fungal infections classically occur in profoundly immunocompromised/neutropenic hosts with prolonged unexplained fever, necrotic skin/mucosal lesions (eschar, mucositis), and hepatosplenomegaly/lymphadenopathy reflecting reticuloendothelial dissemination; definitive diagnosis still requires culture/histopathology so specificity from bedside findings alone is limited."},{"id":"upper_gastrointestinal_tract_cancers","name":"Upper Gastrointestinal Tract Cancers","system":"Gastrointestinal / Oncology","class":"non_infective","find":{"dysphagia":6,"hematemesis":6,"melena":6,"weightLoss":6,"hepatosplenomegaly":6,"nauseaVomiting":2,"abdominalPain":2,"gibPresentation":2,"ascites":2,"jaundice":2,"subacuteOnset":2,"oralIntakeAdequate":-6,"clinicallyImproving":-6},"tiers":{"pathognomonic":[],"discriminative":["dysphagia","hematemesis","melena","weightLoss","hepatosplenomegaly"],"supportive":["nauseaVomiting","abdominalPain","gibPresentation","ascites","jaundice","subacuteOnset"],"negative":["oralIntakeAdequate","clinicallyImproving"]},"rationale":"Progressive dysphagia/odynophagia with weight loss and occult or overt GI bleeding (hematemesis/melena) in an older patient are the classic alarm features; advanced disease may show hepatomegaly (metastases) or ascites, while normal oral intake and clinical improvement argue against an obstructing malignancy."},{"id":"urinary_tract_infections_cystitis_prostati","name":"Urinary Tract Infections: Cystitis, Prostatitis, and Pyelonephritis","system":"Genitourinary","class":"infective","find":{"dysuria":6,"urinaryFrequency":6,"flankPain":6,"feverGU":6,"costovertebralTenderness":6,"complicatedUTIRisk":6,"urinaryRetention":2,"perinealPain":2,"indwellingCatheter":2,"hematuria":2,"fever":2,"rigors":2,"nauseaVomiting":2},"tiers":{"pathognomonic":[],"discriminative":["dysuria","urinaryFrequency","flankPain","feverGU","costovertebralTenderness","complicatedUTIRisk"],"supportive":["urinaryRetention","perinealPain","indwellingCatheter","hematuria","fever","rigors","nauseaVomiting"],"negative":[]},"rationale":"Dysuria/frequency with suprapubic discomfort defines cystitis, while fever plus flank pain and CVA tenderness distinguish pyelonephritis from simple cystitis; catheter/structural risk factors mark complicated UTI, and prostatitis adds perineal/pelvic pain."},{"id":"urinary_tract_obstruction","name":"Urinary Tract Obstruction","system":"Nephrology / Urology","class":"non_infective","find":{"flankPain":6,"urinaryRetention":6,"oliguria":6,"costovertebralTenderness":6,"dysuria":2,"urinaryFrequency":2,"feverGU":2,"complicatedUTIRisk":2,"indwellingCatheter":2,"perinealPain":2,"abdominalDistension":2,"hematuria":2,"oralIntakeAdequate":-6},"tiers":{"pathognomonic":[],"discriminative":["flankPain","urinaryRetention","oliguria","costovertebralTenderness"],"supportive":["dysuria","urinaryFrequency","feverGU","complicatedUTIRisk","indwellingCatheter","perinealPain","abdominalDistension","hematuria"],"negative":["oralIntakeAdequate"]},"rationale":"Flank pain (worsened by distention of the collecting system), acute urinary retention, oliguria/anuria, and CVA tenderness are the most discriminative bedside clues to obstruction, while dysuria/frequency and catheter/structural risk factors are supportive but non-specific since they overlap heavily with uncomplicated UTI and pyelonephritis mimics."},{"id":"urticaria_angioedema","name":"Urticaria, Angioedema & Allergic Rhinitis","system":"Immunology / Allergy","class":"non_infective","find":{"facialSwelling":6,"rash":6,"severeAbdominalPain":6,"abdominalPain":6,"myalgiaArthralgia":2,"dyspnea":2,"petechialRash":-6,"prolongedFever":-6},"tiers":{"pathognomonic":[],"discriminative":["facialSwelling","rash","severeAbdominalPain","abdominalPain"],"supportive":["myalgiaArthralgia","dyspnea"],"negative":["petechialRash","prolongedFever"]},"rationale":"Urticaria/angioedema is diagnosed by history and exam (pruritic migratory wheals, deep non-pitting facial/upper-body swelling, sometimes with GI colic mimicking acute abdomen); persistent petechial/vasculitic lesions or prolonged fever argue against simple urticaria and suggest urticarial vasculitis or another process instead."},{"id":"varicella_zoster","name":"Varicella-Zoster Virus Infection","system":"Infectious Diseases","class":"infective","find":{"rash":6,"maculopapularRash":6,"eschar":6,"lymphadenopathy":6,"immunocompromised":6,"fever":2,"headache":2,"myalgiaArthralgia":2,"malignancy":2,"petechialRash":-6,"tickExposure":-6},"tiers":{"pathognomonic":[],"discriminative":["rash","maculopapularRash","eschar","lymphadenopathy","immunocompromised"],"supportive":["fever","headache","myalgiaArthralgia","malignancy"],"negative":["petechialRash","tickExposure"]},"rationale":"Varicella-zoster produces a characteristic crops-of-vesicles rash (best approximated by rash/maculopapularRash in this vocabulary) often with lymphadenopathy and increased severity/dissemination in immunocompromised hosts; eschar and tick exposure are negative discriminators favoring rickettsial mimics rather than VZV."},{"id":"vascular_dementia","name":"Vascular Dementia","system":"Neurology","class":"non_infective","find":{"focalNeuroDeficit":6,"cerebrovascularDisease":6,"ataxia":6,"behavioralChange":6,"atrialFibHx":6,"hypertensionHx":2,"diabetesHx":2,"knownCAD":2,"peripheralVascularDisease":2,"subacuteOnset":2,"age":2,"rigidity":-6,"seizure":-6},"tiers":{"pathognomonic":[],"discriminative":["focalNeuroDeficit","cerebrovascularDisease","ataxia","behavioralChange","atrialFibHx"],"supportive":["hypertensionHx","diabetesHx","knownCAD","peripheralVascularDisease","subacuteOnset","age"],"negative":["rigidity","seizure"]},"rationale":"Vascular dementia is best identified by focal neurological deficits and documented cerebrovascular disease (stroke/TIA) with vascular risk factors (hypertension, diabetes, atrial fibrillation, CAD, PVD), often with gait/ataxia and behavioral change, while prominent rigidity/myoclonus argues against it (suggesting CJD) as does isolated seizure as an alternative explanation."},{"id":"viral_gastroenteritis","name":"Viral Gastroenteritis","system":"Gastrointestinal","class":"infective","find":{"diarrhea":6,"nauseaVomiting":6,"oralIntakeAdequate":6,"contaminatedFoodWaterExposure":6,"fever":2,"abdominalPain":2,"dehydration":2,"constipationOrDiarrhea":2,"bloodyStool":-6,"toxicAppearing":-6,"immunocompromised":-6},"tiers":{"pathognomonic":[],"discriminative":["diarrhea","nauseaVomiting","oralIntakeAdequate","contaminatedFoodWaterExposure"],"supportive":["fever","abdominalPain","dehydration","constipationOrDiarrhea"],"negative":["bloodyStool","toxicAppearing","immunocompromised"]},"rationale":"Viral gastroenteritis presents with acute watery, nonbloody diarrhea and vomiting with mild systemic symptoms; bloody stool, toxic appearance, or immunocompromised host status point toward bacterial/inflammatory or complicated disease instead."},{"id":"viral_hemorrhagic_fever","name":"Viral Hemorrhagic Fever","system":"Infectious Diseases","class":"infective","find":{"mucocutaneousBleeding":6,"petechialRash":6,"conjunctivalSuffusion":6,"travelEndemicArea":6,"bleedingManifestation":6,"fever":2,"headache":2,"myalgiaArthralgia":2,"rash":2,"nauseaVomiting":2,"thrombocytopenia":2,"alteredSensorium":2,"symmetricSmallJointInvolvement":-6,"tonsillarExudate":-6,"purulentSputum":-6},"tiers":{"pathognomonic":[],"discriminative":["mucocutaneousBleeding","petechialRash","conjunctivalSuffusion","travelEndemicArea","bleedingManifestation"],"supportive":["fever","headache","myalgiaArthralgia","rash","nauseaVomiting","thrombocytopenia","alteredSensorium"],"negative":["symmetricSmallJointInvolvement","tonsillarExudate","purulentSputum"]},"rationale":"VHF has no single pathognomonic finding; mucocutaneous bleeding, petechiae, and conjunctival suffusion in a traveler/exposure from an endemic area are the most discriminating clues, while overt hemorrhage and nonspecific febrile-viral symptoms are supportive but not specific enough to distinguish it from malaria, typhoid, or other mimics."},{"id":"vitamin_and_trace_mineral_deficiency","name":"Vitamin and Trace Mineral Deficiency and Excess","system":"Nutritional / Gastrointestinal","class":"non_infective","find":{"ataxia":6,"alcoholExcess":6,"alteredSensorium":6,"mucocutaneousBleeding":6,"legSwellingBilateral":6,"weightLoss":2,"dehydration":2,"hepatosplenomegaly":2,"asterixis":2,"jaundice":2,"rash":2,"toxicAppearing":-6,"petechialRash":-6,"prolongedFeverUnexplained":-6},"tiers":{"pathognomonic":[],"discriminative":["ataxia","alcoholExcess","alteredSensorium","mucocutaneousBleeding","legSwellingBilateral"],"supportive":["weightLoss","dehydration","hepatosplenomegaly","asterixis","jaundice","rash"],"negative":["toxicAppearing","petechialRash","prolongedFeverUnexplained"]},"rationale":"Vitamin/trace mineral deficiency is best recognized by classic syndromic clusters (Wernicke ataxia/confusion in an alcoholic, bleeding from vitamin K deficiency, high-output edema from wet beriberi) rather than any single pathognomonic bedside sign, and acute infectious toxicity or unexplained prolonged fever argue against a purely nutritional cause."},{"id":"whipple_disease","name":"Whipple Disease","system":"Infectious Diseases","class":"infective","find":{"polyarthralgia":6,"weightLoss":6,"diarrhea":6,"lymphadenopathy":6,"abdominalPain":2,"hepatosplenomegaly":2,"fever":2,"subacuteOnset":2,"nauseaVomiting":2},"tiers":{"pathognomonic":[],"discriminative":["polyarthralgia","weightLoss","diarrhea","lymphadenopathy"],"supportive":["abdominalPain","hepatosplenomegaly","fever","subacuteOnset","nauseaVomiting"],"negative":[]},"rationale":"Whipple disease is ultimately confirmed by small-bowel biopsy with PAS staining and PCR, but its classic clinical picture of polyarticular/migratory arthralgia preceding chronic weight loss, diarrhea, abdominal pain, and lymphadenopathy over years is distinctive enough to raise strong bedside suspicion."},{"id":"wilsons_disease","name":"Wilson's Disease","system":"Hepatology / Neurology","class":"non_infective","find":{"jaundice":6,"liverDisease":6,"hepatosplenomegaly":6,"behavioralChange":6,"ataxia":6,"dysphagia":6,"weightLoss":2,"abdominalDistension":2,"ascites":2,"rigidity":2,"darkUrine":2},"tiers":{"pathognomonic":[],"discriminative":["jaundice","liverDisease","hepatosplenomegaly","behavioralChange","ataxia","dysphagia"],"supportive":["weightLoss","abdominalDistension","ascites","rigidity","darkUrine"],"negative":[]},"rationale":"Wilson's disease presents with young-onset liver disease (jaundice, hepatosplenomegaly, ascites) combined with neuropsychiatric features (behavioral change, ataxia, dysarthria/dysphagia, rigidity from basal ganglia copper deposition); the Kayser-Fleischer ring is pathognomonic but is a slit-lamp/ophthalmologic finding not present in the bedside vocabulary, so no pathognomonic key was mapped."}]};
